properties.query:
// An AI agent driving attack tools
// Agentic attack detections by ThreatDefence (cross-framework behavior, first written for Cairn). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1059 (Command and Scripting Interpreter), T1046 (Network Service Discovery), T1588.007 (Obtain Capabilities: Artificial Intelligence)
// Example hunt for Defender XDR advanced hunting. Test and baseline before alerting.
// Agent CLIs run shell commands for the model. What ties an attack tool to an agent is the process tree:
//  - Claude Code runs every command through its own shell. On Linux and macOS that is
//    zsh -c source ~/.claude/shell-snapshots/snapshot-<shell>-<time>-<id>.sh ..., and on Windows a PowerShell launcher
//    named in CLAUDE_CODE_SHELL_LAUNCHER_SCRIPT. The tool's parent is that shell, not the agent.
//  - Qwen Code, Kimi CLI, Codex, opencode and Pi run <shell> -c <command>, so the agent is the tool's grandparent.
//  - Agents installed with npm or pip run under node or python, so the agent is found by its command line.
// The model behind the agent is usually DeepSeek, Qwen, GLM or Kimi, and it does not matter here.
// Auto-approve flags (claude --dangerously-skip-permissions, codex --dangerously-bypass-approvals-and-sandbox,
// qwen or kimi --yolo, --auto-approve) are shown in the AutoApprove column and are not a filter. On real telemetry
// they were common on staff machines, and an agent ran nmap with no flag at all, so the flag neither finds an
// attacker nor clears a colleague. The attack tool carries the signal: review who ran it and against what.
let Window = 30d;
let AttackTools = dynamic(["nmap", "naabu", "masscan", "nuclei", "katana", "dalfox", "ffuf", "gobuster", "feroxbuster",
    "dirsearch", "nikto", "sqlmap", "wpscan", "hydra", "medusa", "kerbrute", "netexec", "nxc", "crackmapexec",
    "bloodyad", "coercer", "enum4linux-ng", "chisel", "pwncat", "pwncat-cs", "evil-winrm", "responder",
    "cloudfox", "msfconsole", "searchsploit", "hashcat"]);
let AgentBinaries = dynamic(["claude", "codex", "qwen", "kimi", "opencode", "hermes"]);
let AgentCommandLine = @'(?i)(@anthropic-ai[/\\]claude-code|@qwen-code[/\\]|@openai[/\\]codex|kimi[-_]cli|opencode-ai|(^"?|[/\\])(claude|codex|qwen|kimi|opencode)(\.exe|\.cmd|\.js)?"?(\s|$)|--provider cairn|model_provider="cairn"|/tmp/cairn-pi/)';
let AutoApproveFlag = @'(--dangerously-skip-permissions|--dangerously-bypass-approvals-and-sandbox|\s--yolo\b|\s--auto-approve\b|--approval-mode[\s=]+yolo)';
// Tools written in Python, Ruby or Perl (sqlmap, NetExec, wpscan, nikto, Metasploit and others) run as their interpreter:
// FileName is python3.14, ruby3.3 or perl, and the tool is the script in the command line. ScriptTool finds the tool as the
// script that runs: its path followed by an argument or at the end of the command line, or its .py or .pl file. A folder
// or file that only has a tool name in it (src/responder/handler.py, /srv/nxcloud) does not match. The Tools column
// shows the tool name, not the interpreter.
let ScriptTool = @'(?i)/(sqlmap|nikto|wpscan|netexec|nxc|crackmapexec|bloodyad|coercer|evil-winrm|msfconsole|dirsearch|enum4linux-ng|pwncat|pwncat-cs|responder)(\s|$)|[/\\ ]((sqlmap|bloodyad|dirsearch|enum4linux-ng)\.py|nikto\.pl)|(^|[/\\ ])(coercer[/\\]coercer|responder[/\\]responder)\.py';
let Tools = DeviceProcessEvents
    | where Timestamp > ago(Window)
    | extend Tool = replace_string(tolower(FileName), ".exe", "")
    | extend ScriptName = iff(FileName matches regex @'(?i)^(python|ruby|perl)', tolower(extract(ScriptTool, 0, ProcessCommandLine)), "")
    | where Tool in (AttackTools) or isnotempty(ScriptName) or ProcessCommandLine has_any ("impacket-", "ysoserial", "jwt_tool", "PayloadsAllTheThings", "/home/kali/pocs/")
    | extend Tool = iff(isnotempty(ScriptName), trim(@'[/\\\s]+', ScriptName), Tool);
// 1. The process tree names the agent: its own shell, or the agent binary as parent or grandparent
let ByTree = Tools
    | extend Via = case(
        InitiatingProcessCommandLine contains "shell-snapshots" or InitiatingProcessCommandLine contains "CLAUDE_CODE_SHELL_LAUNCHER_SCRIPT", "Claude Code shell is the parent",
        replace_string(tolower(InitiatingProcessFileName), ".exe", "") in (AgentBinaries), strcat(InitiatingProcessFileName, " is the parent"),
        replace_string(tolower(InitiatingProcessParentFileName), ".exe", "") in (AgentBinaries), strcat(InitiatingProcessParentFileName, " is the grandparent"),
        "")
    | where isnotempty(Via)
    | extend AgentCmd = InitiatingProcessCommandLine;
// 2. Agents that run under node, python or bun: find the agent by its command line, then its children and grandchildren
let Agents = DeviceProcessEvents
    | where Timestamp > ago(Window)
    | where ProcessCommandLine matches regex AgentCommandLine
    | project DeviceId, AgentPid=ProcessId, AgentTime=Timestamp, AgentCmd=ProcessCommandLine;
let ByAgentProcess = Tools
    | join kind=inner Agents on DeviceId
    | where Timestamp between (AgentTime .. (AgentTime + 7d)) and (InitiatingProcessParentId == AgentPid or InitiatingProcessId == AgentPid)
    | summarize arg_max(AgentTime, AgentCmd) by DeviceId, DeviceName, AccountName, Timestamp, FileName, Tool, ProcessCommandLine, ProcessId
    | extend Via = "agent found by its command line";
union ByTree, ByAgentProcess
| summarize Tools=make_set(Tool, 20), Commands=make_set(substring(ProcessCommandLine, 0, 200), 15),
    FirstTool=min(Timestamp), LastTool=max(Timestamp), Via=make_set(Via, 5), AgentCmds=make_set(substring(AgentCmd, 0, 300), 5)
    by DeviceName, AccountName
| extend AutoApprove = tostring(AgentCmds) matches regex AutoApproveFlag, CairnMarker = tostring(AgentCmds) contains "cairn"
| order by CairnMarker desc, array_length(Tools) desc

// AI model API traffic from servers: an agentic attack tool running on your infrastructure
// Agentic attack detections by ThreatDefence (cross-framework behavior). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1588.007 (Obtain Capabilities: Artificial Intelligence), T1071.001 (Application Layer Protocol: Web Protocols)
// Example hunt for Microsoft Sentinel. Needs an outbound proxy that records the host and user agent. Test before alerting.
// Every agentic attack framework needs a model, and the ones seen in real intrusions mostly use Chinese models and
// gateways: CyberStrikeAI ships configured for Qwen on Alibaba DashScope, Huntback's CyberStrikeAI operator ran
// DeepSeek, the Cairn panels NorForge found ran DeepSeek behind a Claude Code client, and operators also use GLM
// (Zhipu, BigModel and Z.ai), Kimi (Moonshot), MiniMax, Doubao (Volcano Engine), SiliconFlow and OpenRouter. The consoles
// (ARTEX, PentAGI, CyberStrikeAI) call these APIs from Go or Python, and the agent clients (Qwen Code, Kimi CLI,
// opencode, Claude Code, Codex) call them with their own user agents. Endpoints below are taken from the provider lists
// in Qwen Code, Kimi CLI and opencode.
// A server, container host or build agent calling a model API it has no business calling is the lead, whatever the
// client. Exclude your developer subnets and approved AI gateways, then look at what started the traffic.
let Window = 14d;
let ServerNets = dynamic([]);          // e.g. ["10.20.0.0/16"]; empty means every source
let AllowedNets = dynamic([]);         // developer subnets and approved AI gateways
let ChinaModels = dynamic(["api.deepseek.com", "dashscope.aliyuncs.com", "dashscope-intl.aliyuncs.com", "dashscope-us.aliyuncs.com",
    "open.bigmodel.cn", "api.z.ai", "api.moonshot.cn", "api.moonshot.ai", "api.kimi.com", "code.kimi.com", "api.kimi.ai",
    "api.minimax.io", "api.minimax.cn", "api.minimaxi.com", "ark.cn-beijing.volces.com", "api.siliconflow.cn", "api.siliconflow.com",
    "api.stepfun.com", "api.stepfun.ai", "tokenhub.tencentmaas.com", "api.lkeap.cloud.tencent.com", "api.hunyuan.cloud.tencent.com",
    "qianfan.baidubce.com", "api.xiaomimimo.com", "api-inference.modelscope.cn"]);
let Gateways = dynamic(["openrouter.ai", "api.novita.ai", "zenmux.ai", "api.ofox.ai", "api.together.xyz", "api.groq.com", "api.tensorx.ai"]);
let Western = dynamic(["api.openai.com", "api.anthropic.com", "generativelanguage.googleapis.com", "api.mistral.ai", "api.x.ai"]);
let AgentUA = @"^(claude-cli/|codex_exec/|codex_cli_rs/|pi/\d|QwenCode/|KimiCLI/|opencode/)";
CommonSecurityLog
| where TimeGenerated > ago(Window)
| extend Host = tolower(coalesce(DestinationHostName, extract(@"https?://([^/:]+)", 1, RequestURL)))
| extend Provider = case(Host has_any (ChinaModels), "Chinese model API", Host has_any (Gateways), "model gateway",
    Host has_any (Western), "Western model API", "")
| where isnotempty(Provider)
| where array_length(ServerNets) == 0 or ipv4_is_in_any_range(SourceIP, ServerNets)
| where not(ipv4_is_in_any_range(SourceIP, AllowedNets))
| extend UA = RequestClientApplication
| extend Client = case(UA matches regex AgentUA, extract(@"^([A-Za-z]+)", 1, UA), UA startswith "Go-http-client/", "Go program (ARTEX, PentAGI, CyberStrikeAI consoles)",
    UA startswith "python-requests/" or UA startswith "OpenAI/Python" or UA startswith "AsyncOpenAI/Python" or UA startswith "Anthropic/Python", "Python program",
    UA startswith "OpenAI/JS" or UA startswith "node", "Node program", isempty(UA), "no user agent (TLS, not inspected)", "other")
| summarize Requests=count(), Providers=make_set(Provider), Hosts=make_set(Host, 10), Clients=make_set(Client, 10), UAs=make_set(UA, 10),
    FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated) by SourceIP, SourceUserName
| extend Score = toint(set_has_element(Providers, "Chinese model API")) * 2 + toint(set_has_element(Providers, "model gateway"))
    + toint(array_length(set_intersect(Clients, dynamic(["claude", "codex", "pi", "QwenCode", "KimiCLI", "opencode"]))) > 0)
    + toint(array_length(Hosts) >= 2)
| order by Score desc, Requests desc

// An AI agent's page reader on your application, next to attack traffic from the same source
// Agentic attack detections by ThreatDefence (cross-framework behavior, first written for Cairn). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1594 (Search Victim-Owned Websites), T1595.002 (Active Scanning: Vulnerability Scanning), T1190 (Exploit Public-Facing Application)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// Agent CLIs read pages with their own fetch tools, which send their own user agents, while the attack itself goes
// through curl, Python and Kali tools in the agent's shell:
//  - Qwen Code web fetch: "QwenCode/<version> (<os>; <arch>)" (packages/core/src/tools/web-fetch.ts)
//  - Kimi CLI search: "KimiCLI/<version>" (src/kimi_cli/constant.py); its page fetch poses as Chrome 91
//  - opencode: "opencode/<channel>/<version>/<name>" (packages/core/src/app.ts)
//  - Claude Code WebFetch, which Cairn's workers use with DeepSeek behind it:
//    "Claude-User (claude-code/<version>; +https://support.anthropic.com/)"
// Ordinary users of these tools send the same strings, so a reader hit alone means little. The same address reading
// pages with an agent and sending attack tooling or payloads to the same host is an AI agent attacking that host.
let Window = 14d;
let AgentReader = @"(Claude-User \(claude-code/|^QwenCode/|^KimiCLI/|^opencode/)";
let Web = union isfuzzy=true
    (CommonSecurityLog | where TimeGenerated > ago(Window) and isnotempty(RequestURL)
        | project TimeGenerated, Src=SourceIP, Host=DestinationHostName, Url=RequestURL, UA=RequestClientApplication),
    (W3CIISLog | where TimeGenerated > ago(Window)
        | project TimeGenerated, Src=cIP, Host=csHost, Url=strcat(csUriStem, "?", csUriQuery), UA=replace_string(csUserAgent, "+", " "));
let Readers = Web
    | where UA matches regex AgentReader
    | summarize ReaderRequests=count(), ReaderUA=take_any(UA), ReaderFirst=min(TimeGenerated) by Src, Host;
Web
| where not(UA matches regex AgentReader)
| extend Tool = case(UA startswith "curl/", "curl", UA startswith "python-requests/" or UA startswith "Python-urllib/", "python",
    UA has_any ("sqlmap", "Nuclei", "nuclei", "Fuzz Faster U Fool", "Nikto", "dirsearch", "WPScan", "katana", "dalfox"), "scanner",
    UA has "HeadlessChrome", "headless browser", "")
| extend Payload = Url matches regex @"(?i)(union(\s|\+|%20)+select|sleep\(|\.\./|%2e%2e|/etc/passwd|<script|%3cscript|\$\{|\{\{|/\.git/|/\.env)"
| where isnotempty(Tool) or Payload
| summarize Requests=count(), Tools=make_set(Tool, 6), PayloadHits=countif(Payload), SampleURLs=make_set(Url, 8),
    FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated) by Src, Host
| join kind=inner Readers on Src, Host
| project Src, Host, ReaderUA, ReaderRequests, Requests, Tools, PayloadHits, SampleURLs, FirstSeen, LastSeen
| order by PayloadHits desc, Requests desc

// One site probed through hundreds of rotating proxy addresses
// Agentic attack detections by ThreatDefence (cross-framework behavior, first written for Cairn). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1090.002 (Proxy: External Proxy), T1595.002 (Active Scanning: Vulnerability Scanning)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From public research. Gambit's operator told its agents to "run these, use the proxy, high severity only" and used
// the residential proxy services IPRoyal, 711proxy and 1024proxy. In the Japanese breach wave, Cyber Security Cloud saw
// one attacker rotate through 326 addresses in about 40 minutes for more than 1,200 requests, few per address, then
// return to the same site days later, and judged it to be an AI agent because it changed tactics after each response.
// Per-address thresholds miss this. Count distinct addresses per target host instead, and keep the ones whose requests
// carry attack payloads or hit login and admin paths. Exclude your CDN, uptime monitoring and partner integrations.

let Window = 7d;
let Payload = @"(?i)(union(\s|\+|%20)+select|sleep\(|extractvalue|\.\./|%2e%2e|/etc/passwd|<script|%3cscript|\$\{|\{\{|/\.git/|/\.env|wp-config|phpinfo)";
let Sensitive = @"(?i)/(login|signin|admin|wp-admin|wp-login|api/auth|user/login|account|checkout|upload)";
union isfuzzy=true
    (CommonSecurityLog | where TimeGenerated > ago(Window) and isnotempty(RequestURL)
        | project TimeGenerated, Src=SourceIP, Host=DestinationHostName, Url=RequestURL, UA=RequestClientApplication),
    (W3CIISLog | where TimeGenerated > ago(Window)
        | project TimeGenerated, Src=cIP, Host=csHost, Url=strcat(csUriStem, "?", csUriQuery), UA=csUserAgent)
| where not(ipv4_is_private(Src))
| extend Hit = Url matches regex Payload or Url matches regex Sensitive
| where Hit
| summarize Requests=count(), Sources=dcount(Src), UAs=dcount(UA), SampleUAs=make_set(UA, 10), SampleURLs=make_set(Url, 10)
    by Host, Window40m=bin(TimeGenerated, 40m)
| join kind=inner (
    union isfuzzy=true
        (CommonSecurityLog | where TimeGenerated > ago(Window) | project TimeGenerated, Src=SourceIP, Host=DestinationHostName),
        (W3CIISLog | where TimeGenerated > ago(Window) | project TimeGenerated, Src=cIP, Host=csHost)
    | summarize PerSource=count() by Host, Window40m=bin(TimeGenerated, 40m), Src
    | summarize MedianPerSource=percentile(PerSource, 50) by Host, Window40m) on Host, Window40m
// Many addresses, few requests each, one host
| where Sources >= 50 and MedianPerSource <= 10
| project Window40m, Host, Sources, Requests, MedianPerSource, UAs, SampleUAs, SampleURLs
| order by Sources desc

// Configuration and backup file theft, and probes of internet-facing WSUS servers
// Agentic attack detections by ThreatDefence (cross-framework behavior, first written for Cairn). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1595.003 (Active Scanning: Wordlist Scanning), T1552.001 (Unsecured Credentials: Credentials In Files), T1190 (Exploit Public-Facing Application)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From public research. JPCERT/CC's Case E (October 23, 2026) describes attacks with Cairn, CyberStrikeAI and ARTEX on
// Japanese organizations: probing web applications for known flaws, stealing configuration and backup files, and
// attacking internet-facing WSUS servers. Scutum's WAF saw the AI agents in the same wave check robots.txt and the
// sitemap, then request .git/HEAD, .env, .env.bak, backup.zip and database backups across hundreds of directories at
// about 44 a minute, some with a Range header that returns 206.
// A 200 or 206 answer to any of these paths is the row to look at first: that file has left your network.

let Window = 30d;
let BackupPath = @"(?i)(/\.git/(HEAD|config)|/\.env(\.bak|\.old|\.backup|\.local)?$|/\.hg/|/\.svn/|backup\.(zip|tar|tar\.gz|sql)|db_back|database\.sql|dump\.sql|wp-config\.php\.(bak|old|save)|web\.config\.(bak|old))";
let WsusAdmin = @"(?i)/(ApiRemoting30/WebService\.asmx|ServerSyncWebService/ServerSyncWebService\.asmx|ReportingWebService/ReportingWebService\.asmx)";
let WsusClient = @"(?i)/(ClientWebService/client\.asmx|SimpleAuthWebService/SimpleAuth\.asmx|selfupdate/)";
union isfuzzy=true
    (CommonSecurityLog | where TimeGenerated > ago(Window) and isnotempty(RequestURL)
        | project TimeGenerated, Src=SourceIP, Host=DestinationHostName, Port=DestinationPort, Url=RequestURL,
            Status=toint(extract(@"\b([1-5]\d\d)\b", 1, tostring(EventOutcome))), UA=RequestClientApplication),
    (W3CIISLog | where TimeGenerated > ago(Window)
        | project TimeGenerated, Src=cIP, Host=csHost, Port=sPort, Url=csUriStem, Status=toint(scStatus), UA=csUserAgent)
| where not(ipv4_is_private(Src))
// Remote WSUS clients use the client endpoints legitimately; the admin and sync APIs have no business answering the internet.
| extend Kind = case(Url matches regex WsusAdmin, "WSUS admin or sync API", Url matches regex WsusClient or Port in (8530, 8531), "WSUS client endpoint",
    Url matches regex BackupPath, "config or backup file", "")
| where isnotempty(Kind)
| summarize Requests=count(), Served=countif(Status in (200, 206)), Paths=dcount(Url), SampleURLs=make_set(Url, 15),
    UAs=make_set(UA, 8), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated) by Src, Host, Kind
| where Paths >= 5 or Served > 0 or Kind == "WSUS admin or sync API"
| order by Served desc, Paths desc

// Kerberos user enumeration and SMB or WinRM fan-out from one address
// Agentic attack detections by ThreatDefence (cross-framework behavior, first written for Cairn). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1087.002 (Account Discovery: Domain Account), T1110.003 (Brute Force: Password Spraying), T1021.002 (Remote Services: SMB/Windows Admin Shares), T1021.006 (Remote Services: Windows Remote Management)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the Cairn source code. The worker image ships kerbrute 1.0.3, netexec, bloodyAD, coercer, enum4linux-ng,
// Impacket and chisel, and the workspace guide tells the agent that "level 4" targets are Active Directory networks
// and to use the impacket-* tools, chisel and proxychains (container/Dockerfile, container/AGENTS.md). Kerbrute sends
// bare Kerberos AS-REQs: unknown names fail with 0x6 and real names without pre-authentication return a ticket, so user
// enumeration shows as many 4768 events from one address in minutes. Its password spray shows as 4771 with 0x18.
// Netexec then fans out over SMB and WinRM. Domain controller security events need Kerberos authentication service
// auditing turned on.

let Window = 14d;
union isfuzzy=true
    (SecurityEvent
        | where TimeGenerated > ago(Window)
        | where EventID in (4768, 4771)
        | extend Code = tostring(Status), Src = trim_start(@"::ffff:", IpAddress)
        | summarize Events=count(), Accounts=dcount(TargetUserName), Unknown=countif(EventID == 4768 and Code =~ "0x6"),
            BadPassword=countif(EventID == 4771 and Code =~ "0x18"), Sample=make_set(TargetUserName, 15)
            by Src, Window10m=bin(TimeGenerated, 10m)
        | where Accounts >= 25 and (Unknown >= 10 or BadPassword >= 10)
        | project Window10m, Src, Signal="Kerberos enumeration or spray", Events, Targets=Accounts, Sample),
    (SecurityEvent
        | where TimeGenerated > ago(Window)
        | where EventID == 4624 and LogonType == 3 and AuthenticationPackageName in ("NTLM", "Kerberos")
        | extend Src = IpAddress
        | summarize Events=count(), Hosts=dcount(Computer), Sample=make_set(Computer, 15) by Src, Window10m=bin(TimeGenerated, 10m)
        | where Hosts >= 10
        | project Window10m, Src, Signal="network logons to many hosts", Events, Targets=Hosts, Sample)
| order by Window10m desc

// A server calls back to the address that was probing it
// Agentic attack detections by ThreatDefence (cross-framework behavior). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1190 (Exploit Public-Facing Application), T1071 (Application Layer Protocol)
// Example hunt for Defender XDR advanced hunting with web logs in Microsoft Sentinel. Test and baseline before alerting.
// Agentic frameworks catch reverse shells and out-of-band callbacks on the same machine that runs the attack. PentAGI
// publishes two listener ports per engagement from 28000 on every interface of its host (backend/pkg/docker/client.go),
// and Elastic lists connections from compromised hosts to TCP 28000 to 29999 on the PentAGI host as the thing to watch.
// Cairn's workers share the host network, and its workspace guide tells the agent that reverse shells and out-of-band
// callbacks should use the host's own external address. In both cases, a server you own opens an outbound connection to
// an address that was sending it requests shortly before. Ordinary servers rarely connect out to the addresses that
// browse them.

let Window = 7d;
let Lookback = 1d;
let Probers = union isfuzzy=true
    (CommonSecurityLog | where TimeGenerated > ago(Window) | project TimeGenerated, Prober=SourceIP, Target=DestinationIP),
    (W3CIISLog | where TimeGenerated > ago(Window) | project TimeGenerated, Prober=cIP, Target=sIP)
    | where not(ipv4_is_private(Prober))
    | summarize ProbeRequests=count(), FirstProbe=min(TimeGenerated), LastProbe=max(TimeGenerated) by Prober;
DeviceNetworkEvents
| where Timestamp > ago(Window)
| where ActionType in ("ConnectionSuccess", "ConnectionAttempt") and RemoteIPType == "Public"
| join kind=inner Probers on $left.RemoteIP == $right.Prober
// Outbound to the prober during or within a day after its requests
| where Timestamp between (FirstProbe .. (LastProbe + Lookback))
| extend PentagiPorts = RemotePort between (28000 .. 29999)
| summarize Connections=count(), Ports=make_set(RemotePort, 10), Processes=make_set(InitiatingProcessFileName, 10),
    Commands=make_set(substring(InitiatingProcessCommandLine, 0, 200), 5), FirstCallback=min(Timestamp),
    PentagiPortHit=max(toint(PentagiPorts)) by DeviceName, RemoteIP, ProbeRequests
| extend Note = iff(PentagiPortHit == 1, "callback to a PentAGI worker port range", "callback to the probing address")
| order by PentagiPortHit desc, Connections desc

// AWS credentials used at machine speed from one outside address
// Agentic attack detections by ThreatDefence (cross-framework behavior). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1078.004 (Valid Accounts: Cloud Accounts), T1580 (Cloud Infrastructure Discovery), T1555.006 (Credentials from Password Stores: Cloud Secrets Management Stores), T1651 (Cloud Administration Command)
// Example hunt for Microsoft Sentinel with AWS CloudTrail. Test and baseline before alerting.
// Elastic traced an intrusion to a CyberStrikeAI server that used eight AWS identities across four accounts from one
// address in Hong Kong (September 30 to October 16, 2026). What gave it away was speed and spread, not any one call:
//  - GetCallerIdentity for three identities in three accounts in the same second, from one external address.
//  - 56 DescribeInstanceAttribute calls for userData in 141 milliseconds from one assumed-role session.
//  - EC2 instance role credentials (session named after the instance ID) used from outside AWS for GetSecretValue
//    and GetSessionToken.
//  - GetParameter with decryption followed 29 seconds later by SSM SendCommand from the same role.
// Any agentic framework with stolen keys behaves like this; ARTEX's AWS hunts in frameworks/artex cover more APIs.

let Window = 30d;
// Your NAT gateway and instance public addresses: instance roles calling AWS from these are normal
let YourEgress = dynamic([]);
let External = AWSCloudTrail
    | where TimeGenerated > ago(Window)
    // Calls from a public IPv4 address (AWS services show a host name here, not an address)
    | where SourceIpAddress matches regex @"^\d+\.\d+\.\d+\.\d+$" and not(ipv4_is_private(SourceIpAddress))
    | where UserIdentityType != "AWSService";
union isfuzzy=true
    // Several identities or accounts checked from one address within ten minutes
    (External
        | where EventName == "GetCallerIdentity" and UserIdentityType != "AssumedRole"
        | summarize Identities=dcount(UserIdentityArn), Accounts=dcount(RecipientAccountId), Arns=make_set(UserIdentityArn, 10),
            Timestamp=min(TimeGenerated) by SourceIpAddress, bin(TimeGenerated, 10m)
        | where Identities >= 3
        | project Timestamp, SourceIpAddress, Signal="GetCallerIdentity for several identities from one address",
            Detail=strcat(Identities, " identities in ", Accounts, " accounts: ", tostring(Arns))),
    // Bulk user data reads from one principal
    (External
        | where EventName == "DescribeInstanceAttribute" and RequestParameters has "userData"
        | extend Instance = tostring(parse_json(RequestParameters).instanceId)
        | summarize Instances=dcount(Instance), Calls=count(), First=min(TimeGenerated), Last=max(TimeGenerated)
            by SourceIpAddress, UserIdentityArn, bin(TimeGenerated, 10m)
        | where Instances > 20
        | project Timestamp=First, SourceIpAddress, Signal="Bulk EC2 user data reads",
            Detail=strcat(UserIdentityArn, ": ", Instances, " instances, ", Calls, " calls in ", datetime_diff("millisecond", Last, First), " ms")),
    // Instance role credentials used from outside AWS
    (External
        | where UserIdentityType == "AssumedRole" and UserIdentityArn matches regex @"/i-[0-9a-f]{8,17}$" and SourceIpAddress !in (YourEgress)
        // The role's own instance calls from one stable address; an outside user shows up as a second address
        | join kind=inner (External | where UserIdentityArn matches regex @"/i-[0-9a-f]{8,17}$"
            | summarize RoleAddresses=dcount(SourceIpAddress) by UserIdentityArn | where RoleAddresses > 1) on UserIdentityArn
        | where EventName in ("GetSecretValue", "GetSessionToken", "GetParameter", "GetParameters", "SendCommand", "DescribeInstanceAttribute", "GetCallerIdentity")
        | summarize Events=make_set(EventName, 10), Calls=count(), Timestamp=min(TimeGenerated) by SourceIpAddress, UserIdentityArn
        | project Timestamp, SourceIpAddress, Signal="EC2 instance role credentials used from an outside address",
            Detail=strcat(UserIdentityArn, " ", tostring(Events), " x", Calls)),
    // Decrypt a parameter, then run a command, within a minute
    (External
        | where EventName == "GetParameter" and RequestParameters has "withDecryption" and RequestParameters has "true"
        | project DecryptTime=TimeGenerated, SourceIpAddress, UserIdentityArn
        | join kind=inner (External | where EventName == "SendCommand" | project SendTime=TimeGenerated, UserIdentityArn, Command=RequestParameters) on UserIdentityArn
        | where SendTime between (DecryptTime .. (DecryptTime + 1m))
        | project Timestamp=DecryptTime, SourceIpAddress, Signal="Decrypted parameter then SSM SendCommand",
            Detail=strcat(UserIdentityArn, " ", substring(Command, 0, 200)))
| order by Timestamp desc

// Servers resolving out-of-band testing domains: blind bugs being confirmed against you
// Agentic attack detections by ThreatDefence (cross-framework behavior). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1190 (Exploit Public-Facing Application), T1071.004 (Application Layer Protocol: DNS)
// Example hunt for Defender XDR advanced hunting and Microsoft Sentinel DNS logs. Test and baseline before alerting.
// Agents confirm blind SQL injection, SSRF, XXE, command injection and log4j-style bugs by making the target look up or
// fetch a unique name under a callback service, then checking the service for the hit. Strix's sandbox ships
// interactsh-client and its skills tell the agent to use *.oast.fun; nuclei uses the same interactsh servers; CyberStrikeAI's
// operators used dnslog.cn; Burp uses oastify.com. When one of YOUR servers resolves or contacts one of these names, a
// payload ran on it, and the process that did it is the vulnerable one. Pentests and bug bounty hunters do this too.
// Burp Suite polls polling.oastify.com and polling.burpcollaborator.net for results from the tester's own machine. That is
// not a payload firing, so those two names are left out. Only the exact names: a payload name can carry a polling. label
// in front and still reach the callback service.

let Window = 14d;
let BurpPolling = dynamic(["polling.oastify.com", "polling.burpcollaborator.net"]);
let OOB = dynamic(["oast.fun", "oast.pro", "oast.live", "oast.site", "oast.online", "oast.me", "interact.sh", "oastify.com", "burpcollaborator.net", "dnslog.cn", "ceye.io", "requestrepo.com"]);
union isfuzzy=true
    (DeviceNetworkEvents
        | where Timestamp > ago(Window)
        | where RemoteUrl has_any (OOB) and trim_end(@"\.", tolower(RemoteUrl)) !in (BurpPolling)
        | project Timestamp, DeviceName, Source="DeviceNetworkEvents", Name=RemoteUrl,
            Process=strcat(InitiatingProcessFileName, " ", substring(InitiatingProcessCommandLine, 0, 200))),
    (DeviceEvents
        | where Timestamp > ago(Window)
        | where ActionType == "DnsQueryResponse"
        | extend Name = tostring(parse_json(AdditionalFields).DnsQueryString)
        | where Name has_any (OOB) and trim_end(@"\.", tolower(Name)) !in (BurpPolling)
        | project Timestamp, DeviceName, Source="DeviceEvents DNS", Name,
            Process=strcat(InitiatingProcessFileName, " ", substring(InitiatingProcessCommandLine, 0, 200))),
    (DnsEvents
        | where TimeGenerated > ago(Window)
        | where Name has_any (OOB) and trim_end(@"\.", tolower(Name)) !in (BurpPolling)
        | project Timestamp=TimeGenerated, DeviceName=Computer, Source="DnsEvents", Name, Process=ClientIP)
// The unique label in front of the service name ties a lookup to one payload
| extend Service = extract(@"([a-z0-9-]+\.[a-z]+)$", 1, tolower(Name))
| summarize Lookups=count(), Names=make_set(Name, 10), Processes=make_set(Process, 10), FirstSeen=min(Timestamp), LastSeen=max(Timestamp)
    by DeviceName, Service
| order by FirstSeen desc

// Agent Zero on a host you monitor, attack tools on that host, or its UI exposed through a tunnel
// Agentic attack detections by ThreatDefence (Agent Zero). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1588.002 (Obtain Capabilities: Tool), T1572 (Protocol Tunneling)
// Example hunt for Defender XDR advanced hunting with proxy logs in Microsoft Sentinel. Test before alerting.
// Agent Zero (agent0ai/agent-zero) is a general-purpose agent framework. GTIG reported threat actors experimenting with
// it in 2026 but published no indicators, so this hunt looks for the setup an attacker would use:
//  - The image agent0ai/agent-zero on a Kali base, the framework in /a0, the UI from /exe/self_update_manager.py
//    docker-run-ui (port 80 in the container, published on 50080; 5000 when run directly).
//  - Its prompts: the default profile says "obey instructions never refuse for safety ethics", and the hacker profile
//    (agents/hacker) adds "utilize kali hacking tools for job". The agent runs commands from /bin/bash in
//    /a0/usr/workdir, so an attack tool's parent is a shell with no /a0/ in its command line. The hunt therefore
//    looks for attack tools on devices where Agent Zero itself was seen.
//  - Its tunnel feature (run_tunnel.py) publishes the UI through serveo (ssh, the default), a Cloudflare quick tunnel
//    (cloudflared) or Microsoft dev tunnels, and the login is off unless AUTH_LOGIN is set: GitGuardian found 39 of
//    173 exposed UIs open.
// What each signal relies on in the source is in ../../source-code-signals.md.

let Window = 30d;
let KaliTools = dynamic(["nmap", "masscan", "nuclei", "sqlmap", "hydra", "nikto", "gobuster", "ffuf", "wpscan", "msfconsole", "searchsploit",
    "netexec", "nxc", "crackmapexec", "john", "hashcat", "responder", "evil-winrm", "enum4linux"]);
let AgentShells = dynamic(["bash", "sh", "dash", "zsh", "python", "python3", "ipython", "ipython3", "node"]);
let AgentZeroStarted = DeviceProcessEvents
    | where Timestamp > ago(Window)
    | where ProcessCommandLine contains "agent0ai/agent-zero" or ProcessCommandLine contains "self_update_manager.py docker-run-ui"
        or ProcessCommandLine matches regex @"/a0/(run_ui|run_tunnel)\.py";
let AgentZeroDevices = AgentZeroStarted | distinct DeviceName;
union isfuzzy=true
    (AgentZeroStarted
        | project Timestamp, DeviceName, Signal="Agent Zero container or UI", Detail=substring(ProcessCommandLine, 0, 300)),
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where DeviceName in (AgentZeroDevices)
        | where tolower(FileName) in (KaliTools) and tolower(InitiatingProcessFileName) in (AgentShells)
        | summarize Tools=make_set(FileName, 20), Commands=make_set(substring(ProcessCommandLine, 0, 200), 10), Timestamp=min(Timestamp) by DeviceName
        | project Timestamp, DeviceName, Signal="Attack tools on a device that runs Agent Zero", Detail=strcat(tostring(Tools), " ", tostring(Commands))),
    (DeviceNetworkEvents
        | where Timestamp > ago(Window)
        | where DeviceName in (AgentZeroDevices)
        | where RemoteUrl has_any ("trycloudflare.com", "serveo.net", "devtunnels.ms")
            or (InitiatingProcessFileName =~ "ssh" and InitiatingProcessCommandLine has "serveo.net")
        | summarize Timestamp=min(Timestamp), Connections=count() by DeviceName, RemoteUrl, InitiatingProcessFileName
        | project Timestamp, DeviceName, Signal="Tunnel opened on a device that runs Agent Zero", Detail=strcat(InitiatingProcessFileName, " ", RemoteUrl, " x", Connections)),
    (CommonSecurityLog
        | where TimeGenerated > ago(Window)
        | where RequestClientApplication startswith "agent-zero/"
        | summarize Requests=count(), Timestamp=min(TimeGenerated) by DeviceName=SourceIP, UA=RequestClientApplication
        | project Timestamp, DeviceName, Signal="Agent Zero user agent through the proxy (sign-in with a ChatGPT subscription)", Detail=strcat(UA, " x", Requests))
| order by Timestamp desc

// Password spray at a fixed rhythm
// Agentic attack detections by ThreatDefence (ARTEX). Source: https://threatdefence.com/article/artex-agentic-attack-framework-detection-hunting
// ATT&CK: T1110.003 (Brute Force: Password Spraying)
// Example hunt for Microsoft Sentinel and Defender XDR advanced hunting. Test and baseline before alerting.
// Find sources that fail sign-ins for many users with a steady gap of a second or two.
// In Okta, run the same check on the System Log: failed `user.session.start` events and `user.account.lock` events from one address across many users, at about one attempt a second.

// Example: failed sign-ins from one source and user agent, many users, median gap of two seconds or less
union isfuzzy=true SigninLogs, AADNonInteractiveUserSignInLogs
| where TimeGenerated >= datetime(2026-08-01)
| where ResultType != "0"
| project TimeGenerated, IPAddress, UserAgent, UserPrincipalName, ResultType
| sort by IPAddress asc, UserAgent asc, TimeGenerated asc
| extend GapSec = iff(IPAddress == prev(IPAddress) and UserAgent == prev(UserAgent),
    datetime_diff('second', TimeGenerated, prev(TimeGenerated)), long(null))
| summarize Attempts=count(), Users=dcount(UserPrincipalName), MedianGapSec=percentile(GapSec, 50),
    Lockouts=countif(ResultType == "50053"), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated)
    by IPAddress, UserAgent, bin(TimeGenerated, 1h)
| where Attempts >= 200 and Users >= 20 and MedianGapSec <= 2
| order by Attempts desc

// A spray that ends in a successful sign-in
// Agentic attack detections by ThreatDefence (ARTEX). Source: https://threatdefence.com/article/artex-agentic-attack-framework-detection-hunting
// ATT&CK: T1110.003 (Brute Force: Password Spraying), T1078.004 (Valid Accounts: Cloud Accounts)
// Example hunt for Microsoft Sentinel and Defender XDR advanced hunting. Test and baseline before alerting.

// Example: a successful sign-in from an address that failed against many users
let Sprayers = union isfuzzy=true SigninLogs, AADNonInteractiveUserSignInLogs
    | where TimeGenerated >= datetime(2026-08-01) and ResultType != "0"
    | summarize Failures=count(), TargetedUsers=dcount(UserPrincipalName) by IPAddress
    | where Failures >= 100 and TargetedUsers >= 20;
union isfuzzy=true SigninLogs, AADNonInteractiveUserSignInLogs
| where TimeGenerated >= datetime(2026-08-01) and ResultType == "0"
| join kind=inner Sprayers on IPAddress
| project TimeGenerated, UserPrincipalName, IPAddress, UserAgent, AppDisplayName, Failures, TargetedUsers
| order by TimeGenerated asc

// Applications changing their own access
// Agentic attack detections by ThreatDefence (ARTEX). Source: https://threatdefence.com/article/artex-agentic-attack-framework-detection-hunting
// ATT&CK: T1098.001 (Account Manipulation: Additional Cloud Credentials), T1098.003 (Account Manipulation: Additional Cloud Roles)
// Example hunt for Microsoft Sentinel and Defender XDR advanced hunting. Test and baseline before alerting.
// Storm-0940's agents added credentials to applications and one application assigned itself Global Administrator.
// Check every row against a change record. Automation accounts will appear here, so build a list of the ones you expect.

// Example: credential additions and role or permission grants made by an application, not a person
AuditLogs
| where TimeGenerated >= datetime(2026-08-01)
| where OperationName in ("Add service principal credentials", "Add member to role", "Add app role assignment to service principal")
    or OperationName has "Certificates and secrets management"
| extend ActorApp = tostring(InitiatedBy.app.displayName), ActorSpId = tostring(InitiatedBy.app.servicePrincipalId)
| where isnotempty(ActorSpId)
| extend Target = tostring(TargetResources[0].displayName), TargetId = tostring(TargetResources[0].id)
| extend SelfChange = ActorSpId == TargetId
| project TimeGenerated, OperationName, ActorApp, ActorSpId, Target, TargetId, SelfChange, Result
| order by TimeGenerated asc

// Scripted Microsoft Graph bursts by an application
// Agentic attack detections by ThreatDefence (ARTEX). Source: https://threatdefence.com/article/artex-agentic-attack-framework-detection-hunting
// ATT&CK: T1087.004 (Account Discovery: Cloud Account), T1069.003 (Permission Groups Discovery: Cloud Groups)
// Example hunt for Microsoft Sentinel and Defender XDR advanced hunting. Test and baseline before alerting.
// This needs Microsoft Graph activity logs sent to your workspace. Graph reads are not in the Entra audit log.

// Example: service principals calling Graph with scripted clients, at volume or with many denials
MicrosoftGraphActivityLogs
| where TimeGenerated >= datetime(2026-08-01)
| where isnotempty(ServicePrincipalId)
| where UserAgent has "urllib" or UserAgent has "python-requests" or UserAgent startswith "curl/"
    or UserAgent startswith "azure-toolkit/" or UserAgent has "artex"
| summarize Requests=count(), Denied=countif(ResponseStatusCode in (401, 403)),
    Endpoints=dcount(tostring(split(RequestUri, "?")[0])), IPs=make_set(IPAddress, 10)
    by AppId, ServicePrincipalId, UserAgent, bin(TimeGenerated, 1h)
| where Requests >= 100 or Denied >= 20
| order by Requests desc

// Bulk Key Vault secret reads
// Agentic attack detections by ThreatDefence (ARTEX). Source: https://threatdefence.com/article/artex-agentic-attack-framework-detection-hunting
// ATT&CK: T1555.006 (Credentials from Password Stores: Cloud Secrets Management Stores)
// Example hunt for Microsoft Sentinel and Defender XDR advanced hunting. Test and baseline before alerting.

// Example: one identity reading many secrets across several vaults in 15 minutes
AzureDiagnostics
| where TimeGenerated >= datetime(2026-08-01)
| where ResourceProvider == "MICROSOFT.KEYVAULT" and OperationName == "SecretGet"
| summarize SecretGets=count(), Vaults=dcount(Resource), IPs=make_set(CallerIPAddress, 10)
    by identity_claim_appid_g, bin(TimeGenerated, 15m)
| where SecretGets >= 20 and Vaults >= 3
| order by SecretGets desc

// CloudWatch log searches with a stolen AWS key
// Agentic attack detections by ThreatDefence (ARTEX). Source: https://threatdefence.com/article/artex-agentic-attack-framework-detection-hunting
// ATT&CK: T1078.004 (Valid Accounts: Cloud Accounts), T1213 (Data from Information Repositories)
// Example hunt for Microsoft Sentinel and Defender XDR advanced hunting. Test and baseline before alerting.
// Read the search patterns in the result. Company names combined with words like Fund, Invoice, Billing and LLC match what Datadog saw.

// Example: FilterLogEvents with the fixed limit of 1000 or secret-hunting search terms
AWSCloudTrail
| where TimeGenerated >= datetime(2026-08-01)
| where EventName == "FilterLogEvents"
| extend Params = parse_json(RequestParameters)
| extend Limit = toint(Params.limit), Pattern = tostring(Params.filterPattern), LogGroup = tostring(Params.logGroupName)
| where Limit == 1000 or Pattern has_any ("AKIA", "password", "presigned", "mongo") or Pattern has "s3://"
| summarize Calls=count(), LogGroups=dcount(LogGroup), Patterns=make_set(Pattern, 50)
    by UserIdentityArn, UserIdentityAccessKeyId, SourceIpAddress, bin(TimeGenerated, 1h)
| where Calls >= 20
| order by Calls desc

// Cognito sign-up abuse and the discovery sweep after it
// Agentic attack detections by ThreatDefence (ARTEX). Source: https://threatdefence.com/article/artex-agentic-attack-framework-detection-hunting
// ATT&CK: T1136.003 (Create Account: Cloud Account), T1530 (Data from Cloud Storage), T1580 (Cloud Infrastructure Discovery)
// Example hunt for Microsoft Sentinel and Defender XDR advanced hunting. Test and baseline before alerting.
// Every ARTEX session Datadog reviewed opened with unauthenticated S3 reads. In CloudTrail data events these have a `userIdentity.type` of `AWSAccount` and an `accountId` of `anonymous`. Check S3 data events or server access logs for anonymous `GetObject` and `ListObjects` calls, and for the placeholder object names listed above.
// Hunts 10 to 13 are **example** KQL for Microsoft Defender for Endpoint advanced hunting. Hunts 14 to 16 are example KQL for Microsoft Sentinel. Adapt and test them the same way.

// Example: bursts of Cognito sign-up and recovery calls from one source
AWSCloudTrail
| where TimeGenerated >= datetime(2026-08-01)
| where EventSource == "cognito-idp.amazonaws.com"
| where EventName in ("SignUp", "InitiateAuth", "ForgotPassword", "ResendConfirmationCode", "RespondToAuthChallenge")
| summarize Calls=count(), Errors=countif(isnotempty(ErrorCode)), Events=make_set(EventName),
    Agents=make_set(UserAgent, 10)
    by SourceIpAddress, bin(TimeGenerated, 1h)
| where Calls >= 30
| order by Calls desc

// Cognito sign-up abuse and the discovery sweep after it
// Agentic attack detections by ThreatDefence (ARTEX). Source: https://threatdefence.com/article/artex-agentic-attack-framework-detection-hunting
// ATT&CK: T1136.003 (Create Account: Cloud Account), T1530 (Data from Cloud Storage), T1580 (Cloud Infrastructure Discovery)
// Example hunt for Microsoft Sentinel and Defender XDR advanced hunting. Test and baseline before alerting.
// Every ARTEX session Datadog reviewed opened with unauthenticated S3 reads. In CloudTrail data events these have a `userIdentity.type` of `AWSAccount` and an `accountId` of `anonymous`. Check S3 data events or server access logs for anonymous `GetObject` and `ListObjects` calls, and for the placeholder object names listed above.
// Hunts 10 to 13 are **example** KQL for Microsoft Defender for Endpoint advanced hunting. Hunts 14 to 16 are example KQL for Microsoft Sentinel. Adapt and test them the same way.

// Example: a Cognito-issued identity trying many discovery calls that are denied
AWSCloudTrail
| where TimeGenerated >= datetime(2026-08-01)
| where UserIdentityArn has "CognitoIdentityCredentials"
| where ErrorCode has "AccessDenied" or ErrorCode has "Unauthorized"
| summarize Denied=count(), Actions=dcount(EventName), Sample=make_set(EventName, 25)
    by UserIdentityArn, SourceIpAddress, bin(TimeGenerated, 1h)
| where Actions >= 8
| order by Denied desc

// ARTEX names in files, folders and command lines
// Agentic attack detections by ThreatDefence (ARTEX). Source: https://threatdefence.com/article/artex-agentic-attack-framework-detection-hunting
// ATT&CK: T1588.002 (Obtain Capabilities: Tool)
// Example hunt for Microsoft Sentinel and Defender XDR advanced hunting. Test and baseline before alerting.
// Expect a few false matches on words that contain the same letters. A numbered `artex-probe` file or anything under `C:\ProgramData\artx5v\` is not one of them.

// Example: Defender for Endpoint, files, folders and commands carrying the names the agents leave behind
union isfuzzy=true
  (DeviceFileEvents
   | where Timestamp >= datetime(2026-08-01)
   | where FileName startswith "artex-probe" or FolderPath has @"\ProgramData\artx"
       or FileName in~ ("cl1217.jsp", "f1219a.jsp", "z1219.jsp", "graphics-hook-filter64.dll", "graphics-hook_config.bin")
   | project Timestamp, DeviceName, Kind = "file", Detail = FolderPath, Actor = InitiatingProcessFileName,
             Command = InitiatingProcessCommandLine),
  (DeviceProcessEvents
   | where Timestamp >= datetime(2026-08-01)
   // artex-<name>, artex_<name>, artx<digit> and a binary called artex. The bare word is left out: Artex Risk Solutions is a real company
   | where ProcessCommandLine matches regex @"(?i)((^|[\s\\/""'=])(artex|artx)[-_][\w.-]+|(^|[\s\\/""'=])artx\d\w*|(^|[\s\\/""'])artex(\.exe)?(\s|""|$))"
       or ProcessCommandLine has "art18-"
   | where not(ProcessCommandLine matches regex @"(?i)artex[\s_-]?risk")
   | project Timestamp, DeviceName, Kind = "process", Detail = FolderPath, Actor = InitiatingProcessFileName,
             Command = ProcessCommandLine)
| order by Timestamp asc

// Web and database services starting shells and download tools
// Agentic attack detections by ThreatDefence (ARTEX). Source: https://threatdefence.com/article/artex-agentic-attack-framework-detection-hunting
// ATT&CK: T1505.003 (Server Software Component: Web Shell), T1190 (Exploit Public-Facing Application), T1059 (Command and Scripting Interpreter)
// Example hunt for Microsoft Sentinel and Defender XDR advanced hunting. Test and baseline before alerting.
// A web shell, a command injection flaw and a database that can run operating system commands all look the same in process data: the service starts a shell.
// The threshold of five different commands in ten minutes picks out the agent's trial and error. Lower it to find a single careful command.

// Example: Defender for Endpoint, shells, discovery commands and download tools started by web or database services
let ServiceProcesses = dynamic(["w3wp.exe", "httpd.exe", "httpd", "nginx.exe", "nginx", "php-cgi.exe", "php-fpm",
    "php", "tomcat.exe", "tomcat9.exe", "java.exe", "java", "node.exe", "node", "sqlservr.exe", "mysqld.exe", "mysqld"]);
let Tools = dynamic(["cmd.exe", "powershell.exe", "pwsh.exe", "sh", "bash", "dash", "curl.exe", "curl", "wget",
    "nc", "ncat", "nc.exe", "whoami.exe", "whoami", "tasklist.exe", "net.exe", "nltest.exe", "certutil.exe", "python3"]);
DeviceProcessEvents
| where Timestamp >= datetime(2026-08-01)
| where InitiatingProcessFileName in~ (ServiceProcesses) and FileName in~ (Tools)
// java and node also run Jenkins, npm and AI agent CLIs: count them only under a service account
| where InitiatingProcessFileName !in~ ("java", "java.exe", "node", "node.exe")
    or AccountName in~ ("www-data", "apache", "nginx", "http", "tomcat", "tomcat9", "jetty", "jboss", "wildfly", "node", "nodejs", "nobody", "daemon",
        "network service", "local service", "iusr")
    or AccountDomain =~ "iis apppool"
| summarize Commands=count(), Distinct=dcount(ProcessCommandLine), Sample=make_set(ProcessCommandLine, 15),
            FirstSeen=min(Timestamp), LastSeen=max(Timestamp)
    by DeviceName, InitiatingProcessFileName, AccountName, bin(Timestamp, 10m)
| where Distinct >= 5
| order by Distinct desc

// Servers calling webhook and tunnel services, or downloading from a bare address
// Agentic attack detections by ThreatDefence (ARTEX). Source: https://threatdefence.com/article/artex-agentic-attack-framework-detection-hunting
// ATT&CK: T1105 (Ingress Tool Transfer), T1567.004 (Exfiltration Over Web Service: Exfiltration Over Webhook), T1572 (Protocol Tunneling)
// Example hunt for Microsoft Sentinel and Defender XDR advanced hunting. Test and baseline before alerting.
// Microsoft's own hunt for Storm-3358 follows the same idea: list the addresses curl downloaded from in the last day that it did not use in the week before.

// Example: Defender for Endpoint, curl, wget and netcat talking to collection services or raw IP addresses
DeviceProcessEvents
| where Timestamp >= datetime(2026-08-01)
| where FileName in~ ("curl.exe", "curl", "wget", "nc", "ncat", "nc.exe")
| extend Target = extract(@"(https?://[^\s""']+)", 1, ProcessCommandLine)
| extend RawIP = extract(@"https?://(\d{1,3}(?:\.\d{1,3}){3})", 1, ProcessCommandLine)
| where ProcessCommandLine has_any ("webhook.site", "oast.", "interact.sh", "ngrok", "trycloudflare.com")
    or (isnotempty(RawIP) and not(ipv4_is_private(RawIP)))
    or (FileName in~ ("nc", "ncat", "nc.exe") and ProcessCommandLine has_any (" -e ", " -c "))
| project Timestamp, DeviceName, AccountName, InitiatingProcessFileName, FileName, Target, ProcessCommandLine
| order by Timestamp asc

// Scripts written into web directories
// Agentic attack detections by ThreatDefence (ARTEX). Source: https://threatdefence.com/article/artex-agentic-attack-framework-detection-hunting
// ATT&CK: T1505.003 (Server Software Component: Web Shell)
// Example hunt for Microsoft Sentinel and Defender XDR advanced hunting. Test and baseline before alerting.
// A script file created by `mysqld`, `sqlservr.exe`, `java` or `w3wp.exe` itself deserves attention first. In MySQL, also check whether `general_log_file` or `slow_query_log_file` points into a web directory.

// Example: Defender for Endpoint, server-side script files created in web roots by something other than a deployment tool
let Deployers = dynamic(["msdeploy.exe", "git.exe", "git", "rsync", "dpkg", "rpm", "apt", "yum", "dotnet.exe", "octopus.tentacle.exe"]);
DeviceFileEvents
| where Timestamp >= datetime(2026-08-01)
| where ActionType in ("FileCreated", "FileModified")
| where FileName endswith ".jsp" or FileName endswith ".jspx" or FileName endswith ".php" or FileName endswith ".aspx" or FileName endswith ".ashx"
| where FolderPath has_any (@"\inetpub\", @"\webapps\", @"\htdocs\", "/var/www/", "/webapps/", "/usr/share/nginx/")
| where InitiatingProcessFileName !in~ (Deployers)
| project Timestamp, DeviceName, FolderPath, InitiatingProcessFileName, InitiatingProcessAccountName,
          InitiatingProcessCommandLine, SHA256
| order by Timestamp asc

// AWS permission testing and the foothold that follows
// Agentic attack detections by ThreatDefence (ARTEX). Source: https://threatdefence.com/article/artex-agentic-attack-framework-detection-hunting
// ATT&CK: T1078.004 (Valid Accounts: Cloud Accounts), T1580 (Cloud Infrastructure Discovery), T1098.001 (Account Manipulation: Additional Cloud Credentials)
// Example hunt for Microsoft Sentinel and Defender XDR advanced hunting. Test and baseline before alerting.
// Check `GetCallerIdentity` from the same identity just before either result. It is the first call most stolen keys make.

// Example: Sentinel AWSCloudTrail, bursts of DryRun calls from one identity
AWSCloudTrail
| where TimeGenerated >= datetime(2026-08-01)
| where ErrorCode in ("Client.DryRunOperation", "Client.UnauthorizedOperation")
| summarize Calls=count(), Actions=dcount(EventName), Allowed=countif(ErrorCode == "Client.DryRunOperation"),
            Sample=make_set(EventName, 25), Agents=make_set(UserAgent, 5)
    by UserIdentityArn, SourceIpAddress, bin(TimeGenerated, 5m)
| where Calls >= 10 and Actions >= 5
| order by Calls desc

// AWS permission testing and the foothold that follows
// Agentic attack detections by ThreatDefence (ARTEX). Source: https://threatdefence.com/article/artex-agentic-attack-framework-detection-hunting
// ATT&CK: T1078.004 (Valid Accounts: Cloud Accounts), T1580 (Cloud Infrastructure Discovery), T1098.001 (Account Manipulation: Additional Cloud Credentials)
// Example hunt for Microsoft Sentinel and Defender XDR advanced hunting. Test and baseline before alerting.
// Check `GetCallerIdentity` from the same identity just before either result. It is the first call most stolen keys make.

// Example: Sentinel AWSCloudTrail, one identity creating a key pair, an Elastic IP, instances or large volumes in an hour
AWSCloudTrail
| where TimeGenerated >= datetime(2026-08-01)
| where isempty(ErrorCode)
| where EventName in ("CreateKeyPair", "ImportKeyPair", "AllocateAddress", "AssociateAddress", "RunInstances",
                      "CreateVolume", "ModifyVolume", "CreateSecurityGroup", "ModifyInstanceAttribute")
| extend Params = parse_json(RequestParameters)
| extend InstanceType = tostring(Params.instanceType), VolumeSize = toint(Params.size)
| summarize Events=make_set(EventName), Kinds=dcount(EventName), Types=make_set(InstanceType, 5),
            LargestVolumeGB=max(VolumeSize), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated)
    by UserIdentityArn, SourceIpAddress, bin(TimeGenerated, 1h)
| where Kinds >= 3
| order by FirstSeen asc

// Azure capability checks, validate sweeps and Kudu sign-ins
// Agentic attack detections by ThreatDefence (ARTEX). Source: https://threatdefence.com/article/artex-agentic-attack-framework-detection-hunting
// ATT&CK: T1526 (Cloud Service Discovery), T1580 (Cloud Infrastructure Discovery), T1078.004 (Valid Accounts: Cloud Accounts)
// Example hunt for Microsoft Sentinel and Defender XDR advanced hunting. Test and baseline before alerting.
// Normal backup and deployment tools also write and delete test blobs, so start with callers you cannot name.

// Example: Sentinel StorageBlobLogs, a blob written and deleted by the same caller within two seconds
let Writes = StorageBlobLogs
    | where TimeGenerated >= datetime(2026-08-01)
    | where OperationName in ("PutBlob", "PutBlockList") and StatusCode in (200, 201)
    | project WriteTime=TimeGenerated, AccountName, ObjectKey, CallerIpAddress, WriteAgent=UserAgentHeader;
StorageBlobLogs
| where TimeGenerated >= datetime(2026-08-01)
| where OperationName == "DeleteBlob" and StatusCode in (200, 202)
| project DeleteTime=TimeGenerated, AccountName, ObjectKey, CallerIpAddress
| join kind=inner Writes on AccountName, ObjectKey, CallerIpAddress
| where DeleteTime between (WriteTime .. WriteTime + 2s)
| summarize Tests=count(), Accounts=dcount(AccountName), FirstSeen=min(WriteTime), Agents=make_set(WriteAgent, 5)
    by CallerIpAddress
| order by Tests desc

// Azure capability checks, validate sweeps and Kudu sign-ins
// Agentic attack detections by ThreatDefence (ARTEX). Source: https://threatdefence.com/article/artex-agentic-attack-framework-detection-hunting
// ATT&CK: T1526 (Cloud Service Discovery), T1580 (Cloud Infrastructure Discovery), T1078.004 (Valid Accounts: Cloud Accounts)
// Example hunt for Microsoft Sentinel and Defender XDR advanced hunting. Test and baseline before alerting.
// Normal backup and deployment tools also write and delete test blobs, so start with callers you cannot name.

// Example: Sentinel AzureActivity, deployment validation dry runs across several resource types in one minute
AzureActivity
| where TimeGenerated >= datetime(2026-08-01)
| where OperationNameValue =~ "Microsoft.Resources/deployments/validate/action"
| summarize Validations=count(), ResourceGroups=dcount(ResourceGroup), FirstSeen=min(TimeGenerated)
    by Caller, CallerIpAddress, bin(TimeGenerated, 1m)
| where Validations >= 5
| order by Validations desc

// Azure capability checks, validate sweeps and Kudu sign-ins
// Agentic attack detections by ThreatDefence (ARTEX). Source: https://threatdefence.com/article/artex-agentic-attack-framework-detection-hunting
// ATT&CK: T1526 (Cloud Service Discovery), T1580 (Cloud Infrastructure Discovery), T1078.004 (Valid Accounts: Cloud Accounts)
// Example hunt for Microsoft Sentinel and Defender XDR advanced hunting. Test and baseline before alerting.
// Normal backup and deployment tools also write and delete test blobs, so start with callers you cannot name.

// Example: Sentinel AppServiceAuditLogs, publishing sign-ins through Kudu or FTP from addresses not used before
let Known = AppServiceAuditLogs
    | where TimeGenerated between (ago(90d) .. ago(7d))
    | distinct _ResourceId, UserAddress;
AppServiceAuditLogs
| where TimeGenerated > ago(7d)
| join kind=leftanti Known on _ResourceId, UserAddress
| project TimeGenerated, _ResourceId, User, UserDisplayName, UserAddress, Protocol
| order by TimeGenerated asc

// Kerberoasting, DCSync and WinRM fan-out
// Agentic attack detections by ThreatDefence (ARTEX). Source: https://threatdefence.com/article/artex-agentic-attack-framework-detection-hunting
// ATT&CK: T1558.003 (Steal or Forge Kerberos Tickets: Kerberoasting), T1003.006 (OS Credential Dumping: DCSync), T1021.006 (Remote Services: Windows Remote Management)
// Example hunt for Microsoft Sentinel and Defender XDR advanced hunting. Test and baseline before alerting.
// Event 4662 is only written where directory service access auditing is turned on. Add your directory synchronization accounts to the exclusion in the second query.
// ## Detection rules to keep

// Example: Sentinel SecurityEvent, one account requesting RC4 service tickets for many services
SecurityEvent
| where TimeGenerated >= datetime(2026-08-01)
| where EventID == 4769
// TicketEncryptionType is not a SecurityEvent column: read it from the event XML
| extend TicketEncryptionType = extract(@'TicketEncryptionType">([^<]+)<', 1, EventData)
| where TicketEncryptionType =~ "0x17" and ServiceName !endswith "$" and TargetUserName !has "$@"
| summarize Tickets=count(), Services=dcount(ServiceName), Sample=make_set(ServiceName, 15)
    by TargetUserName, IpAddress, bin(TimeGenerated, 10m)
| where Services >= 10
| order by Services desc

// Kerberoasting, DCSync and WinRM fan-out
// Agentic attack detections by ThreatDefence (ARTEX). Source: https://threatdefence.com/article/artex-agentic-attack-framework-detection-hunting
// ATT&CK: T1558.003 (Steal or Forge Kerberos Tickets: Kerberoasting), T1003.006 (OS Credential Dumping: DCSync), T1021.006 (Remote Services: Windows Remote Management)
// Example hunt for Microsoft Sentinel and Defender XDR advanced hunting. Test and baseline before alerting.
// Event 4662 is only written where directory service access auditing is turned on. Add your directory synchronization accounts to the exclusion in the second query.
// ## Detection rules to keep

// Example: Sentinel SecurityEvent, directory replication rights used by an account that is not a domain controller
SecurityEvent
| where TimeGenerated >= datetime(2026-08-01)
| where EventID == 4662
| where Properties has_any ("1131f6aa-9c07-11d1-f79f-00c04fc2dcd2", "1131f6ad-9c07-11d1-f79f-00c04fc2dcd2",
                            "89e95b76-444d-4c62-991a-0facbeda640c")
| where SubjectUserName !endswith "$" and SubjectUserName !startswith "MSOL_"
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated) by SubjectUserName, Computer
| order by FirstSeen asc

// Kerberoasting, DCSync and WinRM fan-out
// Agentic attack detections by ThreatDefence (ARTEX). Source: https://threatdefence.com/article/artex-agentic-attack-framework-detection-hunting
// ATT&CK: T1558.003 (Steal or Forge Kerberos Tickets: Kerberoasting), T1003.006 (OS Credential Dumping: DCSync), T1021.006 (Remote Services: Windows Remote Management)
// Example hunt for Microsoft Sentinel and Defender XDR advanced hunting. Test and baseline before alerting.
// Event 4662 is only written where directory service access auditing is turned on. Add your directory synchronization accounts to the exclusion in the second query.
// ## Detection rules to keep

// Example: Defender for Endpoint, one host opening WinRM to many machines in ten minutes
DeviceNetworkEvents
| where Timestamp >= datetime(2026-08-01)
| where RemotePort in (5985, 5986) and ActionType == "ConnectionSuccess"
| summarize Targets=dcount(RemoteIP), Sample=make_set(RemoteIP, 20), Processes=make_set(InitiatingProcessFileName, 5)
    by DeviceName, bin(Timestamp, 10m)
| where Targets >= 10
| order by Targets desc

// User agent family burst from one source
// Agentic attack detections by ThreatDefence (ARTEX). Source: https://threatdefence.com/article/artex-agentic-attack-framework-detection-hunting
// ATT&CK: T1595.002 (Active Scanning: Vulnerability Scanning)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// ARTEX runs several workers per task (scanners such as nuclei, httpx, katana, ffuf and sqlmap, plus Python, curl and
// AWS SDK clients) from the same host, so one source address shows several unrelated user agent families inside a minute.
// Logic after Elastic Security Labs (November 13, 2026): three or more families and twenty or more requests per minute.
// Point it at the web, WAF or proxy table you collect. CommonSecurityLog and W3CIISLog are shown.

let Families = (ua:string) { case(
    ua startswith "Boto3" or ua startswith "aws-cli" or ua startswith "aws-sdk", "aws",
    ua has "python-requests" or ua has "Python-urllib" or ua has "aiohttp" or ua has "httpx", "python",
    ua startswith "curl/", "curl",
    ua startswith "norma", "norma",
    ua startswith "Go-http-client", "go",
    ua has_any ("nuclei", "sqlmap", "ffuf", "katana", "gobuster", "nikto"), "scanner",
    ua startswith "Mozilla/5.0", "browser",
    "other") };
union isfuzzy=true
    (CommonSecurityLog | where isnotempty(RequestClientApplication)
        | project TimeGenerated, Src=SourceIP, UA=RequestClientApplication),
    (W3CIISLog | project TimeGenerated, Src=cIP, UA=csUserAgent)
| where TimeGenerated > ago(14d)
| where not(ipv4_is_private(Src)) and not(ipv4_is_in_range(Src, "100.64.0.0/10")) and Src != "127.0.0.1"
| extend Family = Families(UA)
| summarize Requests=count(), Families=dcount(Family), FamilyList=make_set(Family), SampleUAs=make_set(UA, 10)
    by Src, bin(TimeGenerated, 1m)
| where Families >= 3 and Requests >= 20
| summarize Minutes=count(), TotalRequests=sum(Requests), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated),
    FamilyList=make_set(FamilyList), SampleUAs=make_set(SampleUAs, 20) by Src
| order by Minutes desc

// Service principal secret guessing followed by a success
// Agentic attack detections by ThreatDefence (ARTEX). Source: https://threatdefence.com/article/artex-agentic-attack-framework-detection-hunting
// ATT&CK: T1110.001 (Brute Force: Password Guessing), T1078.004 (Valid Accounts: Cloud Accounts)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// Storm-0940's agents signed in as compromised applications. A source that fails with invalid client secrets
// (AADSTS7000215) or expired secrets (AADSTS7000222) and then succeeds, or that signs in as three or more
// service principals, is worth a look.

AADServicePrincipalSignInLogs
| where TimeGenerated > ago(14d)
| summarize Failures=countif(ResultType in ("7000215", "7000222")), Successes=countif(ResultType == "0"),
    ServicePrincipals=dcount(ServicePrincipalId), Apps=make_set(ServicePrincipalName, 20),
    Resources=make_set(ResourceDisplayName, 20), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated)
    by IPAddress
| where (Failures > 0 and Successes > 0) or ServicePrincipals >= 3
| order by ServicePrincipals desc, Failures desc

// One application requesting tokens for many resources in minutes
// Agentic attack detections by ThreatDefence (ARTEX). Source: https://threatdefence.com/article/artex-agentic-attack-framework-detection-hunting
// ATT&CK: T1526 (Cloud Service Discovery), T1078.004 (Valid Accounts: Cloud Accounts)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// An agent that has an application's credentials tries every API it can reach: Microsoft Graph, Azure Resource
// Manager, Key Vault, Storage and more, inside a few minutes. Most applications use one or two resources.

AADServicePrincipalSignInLogs
| where TimeGenerated > ago(14d)
| where ResultType == "0"
| summarize Resources=dcount(ResourceDisplayName), ResourceList=make_set(ResourceDisplayName, 20),
    Sources=make_set(IPAddress, 10) by ServicePrincipalName, ServicePrincipalId, bin(TimeGenerated, 15m)
| where Resources >= 3
| join kind=leftanti (
    AADServicePrincipalSignInLogs
    | where TimeGenerated between (ago(44d) .. ago(14d)) and ResultType == "0"
    | summarize HistoricResources=dcount(ResourceDisplayName) by ServicePrincipalId, bin(TimeGenerated, 15m)
    | where HistoricResources >= 3
    | distinct ServicePrincipalId
) on ServicePrincipalId
| order by Resources desc

// An ARTEX console or a backdoored ARTEX image inside your network
// Agentic attack detections by ThreatDefence (ARTEX). Source: https://threatdefence.com/article/artex-agentic-attack-framework-detection-hunting
// ATT&CK: T1588.002 (Obtain Capabilities: Tool), T1071.001 (Application Layer Protocol: Web Protocols)
// Example hunt for Defender XDR advanced hunting. Test before alerting.
// Someone running ARTEX on your own hosts is either an authorized tester, an insider or an intruder. Backdoored
// container images (tomicdd/artex, congdonglinux/artex) also hand the host to a third party: BadByte reported
// the console binary /app/artex spawning sh -c and a login API that accepts a captcha field.

let ArtexHash = dynamic(["d5070f52262effe216b840711343bff8f2787f39208d887d8dfd9c673f8d1573"]);
union isfuzzy=true
    (DeviceProcessEvents
        | where Timestamp > ago(30d)
        | where SHA256 in (ArtexHash) or FolderPath endswith "/app/artex"
            or (InitiatingProcessFolderPath endswith "/app/artex" and FileName in~ ("sh", "bash"))
            or ProcessCommandLine has_any ("tomicdd/artex", "congdonglinux/artex", "Autumn-27/ARTEX")
        | project Timestamp, DeviceName, Signal="process", Process=FileName, Path=FolderPath,
            CommandLine=ProcessCommandLine, Detail=InitiatingProcessCommandLine),
    (DeviceNetworkEvents
        | where Timestamp > ago(30d)
        | where ActionType == "ListeningConnectionCreated" and LocalPort in (8787, 8790, 8890)
        | project Timestamp, DeviceName, Signal="listening port", Process=InitiatingProcessFileName,
            Path=InitiatingProcessFolderPath, CommandLine=InitiatingProcessCommandLine,
            Detail=strcat("port ", LocalPort))
| order by Timestamp desc

// Indicator sweep with the ARTEX watchlist
// Agentic attack detections by ThreatDefence (ARTEX). Source: https://threatdefence.com/article/artex-agentic-attack-framework-detection-hunting
// ATT&CK: T1595 (Active Scanning), T1071 (Application Layer Protocol)
// Upload feeds/sentinel-watchlist.csv as a Microsoft Sentinel watchlist with the alias AGENTIC_IOCs and the search
// key "value". A match needs investigation. Addresses are reassigned, so check the reported date and review_by.

let IOC = _GetWatchlist('AGENTIC_IOCs') | where framework has "artex" | project value=tostring(SearchKey), type, confidence, actor, source;
let IPList = toscalar(IOC | where type == "ipv4" | summarize make_list(value));  // single addresses and CIDR ranges
let UAs = IOC | where type == "user_agent" and confidence in ("high", "medium") | project value;
let Domains = IOC | where type == "domain" and confidence in ("high", "medium") | project value;
union isfuzzy=true
    (SigninLogs | where TimeGenerated > ago(90d)
        | where ipv4_is_in_any_range(IPAddress, IPList) or UserAgent has_any (UAs)
        | project TimeGenerated, Table="SigninLogs", Indicator=coalesce(IPAddress, UserAgent), UserPrincipalName, IPAddress, UserAgent),
    (AADServicePrincipalSignInLogs | where TimeGenerated > ago(90d)
        | where ipv4_is_in_any_range(IPAddress, IPList)
        | project TimeGenerated, Table="AADServicePrincipalSignInLogs", Indicator=IPAddress, UserPrincipalName=ServicePrincipalName, IPAddress, UserAgent=""),
    (AWSCloudTrail | where TimeGenerated > ago(90d)
        | where ipv4_is_in_any_range(SourceIpAddress, IPList) or UserAgent has_any (UAs)
        | project TimeGenerated, Table="AWSCloudTrail", Indicator=coalesce(SourceIpAddress, UserAgent), UserPrincipalName=UserIdentityArn, IPAddress=SourceIpAddress, UserAgent),
    (CommonSecurityLog | where TimeGenerated > ago(90d)
        | where ipv4_is_in_any_range(SourceIP, IPList) or ipv4_is_in_any_range(DestinationIP, IPList) or RequestClientApplication has_any (UAs) or DestinationHostName in (Domains)
        | project TimeGenerated, Table="CommonSecurityLog", Indicator=coalesce(SourceIP, DestinationIP), UserPrincipalName=SourceUserName, IPAddress=SourceIP, UserAgent=RequestClientApplication),
    (DeviceNetworkEvents | where Timestamp > ago(30d)
        | where ipv4_is_in_any_range(RemoteIP, IPList) or RemoteUrl has_any (Domains)
        | project TimeGenerated=Timestamp, Table="DeviceNetworkEvents", Indicator=coalesce(RemoteIP, RemoteUrl), UserPrincipalName=InitiatingProcessAccountName, IPAddress=RemoteIP, UserAgent="")
| order by TimeGenerated desc

// Payload hosts and fake system binaries from the SQL Server toolkit active in ARTEX operations
// Agentic attack detections by ThreatDefence (ARTEX). Source: https://threatdefence.com/article/artex-agentic-attack-framework-detection-hunting
// ATT&CK: T1105 (Ingress Tool Transfer), T1036.005 (Masquerading: Match Legitimate Resource Name or Location), T1496 (Resource Hijacking)
// Example hunt for Defender XDR advanced hunting. Test before alerting.
// ThreatDefence saw these hosts active in ARTEX operator toolkits on November 20, 2026. Fortinet reports the same
// vietnam852.com hosts in a campaign that brute-forces Microsoft SQL Servers, enables xp_cmdshell and installs
// Gh0st RAT (as winlogon.exe) and an XMRig miner (as MicrosoftEdgeUpdate.exe with the WinRing0x64.sys driver).

let Hosts = dynamic(["vietnam852.com", "zhzy999.net", "jiancai008.com"]);
let IPs = dynamic(["177.104.169.18", "103.229.52.185", "172.86.84.225"]);
let Hashes = dynamic(["3f64b0146b323c5716043360e84384a5a197a897f46088df93a910470a29e1a0",
    "2a23e10bfc097e98295cbff8124bd403c4cb677e709b48ccc53d6aca216c3061",
    "da4128aa5d006e05c58f0d240c2d8e5fb02774b6acf314f1230059c7a3498724"]);
union isfuzzy=true
    (DeviceNetworkEvents | where Timestamp > ago(30d)
        | where RemoteUrl has_any (Hosts) or RemoteIP in (IPs)
        | project Timestamp, DeviceName, Signal="network", Detail=coalesce(RemoteUrl, RemoteIP),
            Process=InitiatingProcessFileName, CommandLine=InitiatingProcessCommandLine),
    (DeviceProcessEvents | where Timestamp > ago(30d)
        | where SHA256 in (Hashes)
            or (FileName in~ ("smss.exe", "winlogon.exe", "dllhost.exe", "sihost.exe")
                and not(FolderPath startswith @"C:\Windows\System32\" or FolderPath startswith @"C:\Windows\SysWOW64\"))
            or (FileName =~ "MicrosoftEdgeUpdate.exe" and not(FolderPath has @"\Microsoft\EdgeUpdate\" or FolderPath has @"\Microsoft\Temp\"))
            or (InitiatingProcessFileName =~ "sqlservr.exe" and FileName in~ ("cmd.exe", "powershell.exe", "certutil.exe"))
            or (FileName =~ "schtasks.exe" and ProcessCommandLine has_any ("CEC15D9B-F4BB-446A-B6E1-C61E74B016A2", "4C33CE3F-7722-4257-AF83-351A4911C159", "Microsoft_UPDATES"))
        | project Timestamp, DeviceName, Signal="process", Detail=FolderPath, Process=FileName, CommandLine=ProcessCommandLine),
    (DeviceFileEvents | where Timestamp > ago(30d)
        | where SHA256 in (Hashes) or (FileName =~ "WinRing0x64.sys" and FolderPath has_any (@"\Users\", @"\ProgramData\", @"\Temp\"))
            or FileOriginUrl has_any (Hosts)
        | project Timestamp, DeviceName, Signal="file", Detail=FolderPath, Process=InitiatingProcessFileName, CommandLine=InitiatingProcessCommandLine)
| order by Timestamp desc

// ARTEX page reads (norma/0.4) and the enrichment probe that follows
// Agentic attack detections by ThreatDefence (ARTEX). Source: https://threatdefence.com/article/artex-agentic-attack-framework-detection-hunting
// ATT&CK: T1594 (Search Victim-Owned Websites), T1595.002 (Active Scanning: Vulnerability Scanning)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the ARTEX source code. Every WebFetch call the agents make is a plain GET with the user agent "norma/0.4",
// hard-coded in the agent library ARTEX builds against (BaaRai/Norma v0.4.11, tool/webfetch.go:236). WebFetch refuses
// .js, .css, image, font and media URLs (tool/webfetch.go:177-204), so the source reads pages and API responses but
// never loads the assets a browser would. When an agent records a new site, ARTEX's enrichment engine sends one more
// GET to it with Go's default "Go-http-client/1.1", Connection: close, redirects not followed and certificate checks
// off (enrich/enrich.go:104-128, 247). Both leave from the ARTEX host, so they share a source address.
// Changing "norma/0.4" needs a rebuild. ARTEX_TARGET_USER_AGENT does not replace it, because it only fills in requests
// that carry no user agent (egress/egress.go:459). It does replace the Go default on the enrichment probe, so the
// second half is the more fragile one. Other tools built on norma share the user agent: treat a match as a lead.

let Window = 14d;
let StaticExt = dynamic([".js", ".mjs", ".css", ".map", ".png", ".jpg", ".jpeg", ".gif", ".svg", ".webp", ".ico",
    ".woff", ".woff2", ".ttf", ".otf", ".eot", ".wasm", ".mp4", ".webm", ".mp3"]);
let Web = union isfuzzy=true
    (CommonSecurityLog
        | where TimeGenerated > ago(Window) and isnotempty(RequestClientApplication)
        | project TimeGenerated, Src=SourceIP, Host=DestinationHostName, Method=RequestMethod,
            Url=RequestURL, UA=RequestClientApplication),
    (W3CIISLog
        | where TimeGenerated > ago(Window)
        | project TimeGenerated, Src=cIP, Host=csHost, Method=csMethod, Url=csUriStem, UA=csUserAgent)
    | extend UA = replace_string(UA, "+", " ")
    | extend Path = tolower(tostring(split(Url, "?")[0]));
let Norma = Web
    | where UA == "norma/0.4"
    | summarize NormaRequests=count(), NormaPaths=dcount(Path), Methods=make_set(Method, 5),
        StaticHits=countif(Path has_any (StaticExt)), SamplePaths=make_set(Path, 15),
        NormaFirst=min(TimeGenerated), NormaLast=max(TimeGenerated) by Src, Host;
let Enrich = Web
    | where UA == "Go-http-client/1.1" and Method == "GET"
    | summarize EnrichProbes=count(), EnrichPaths=make_set(Path, 5), EnrichFirst=min(TimeGenerated) by Src, Host;
Norma
| join kind=leftouter Enrich on Src, Host
| extend EnrichNearNorma = isnotempty(EnrichFirst) and abs(datetime_diff('minute', EnrichFirst, NormaFirst)) <= 30
// A real norma client is GET only and never asks for static assets.
| where StaticHits == 0 and Methods has "GET" and array_length(Methods) == 1
| extend Strength = iff(EnrichNearNorma, "norma page reads plus a Go enrichment probe", "norma page reads only")
| project Src, Host, Strength, EnrichNearNorma, NormaRequests, NormaPaths, SamplePaths, NormaFirst, NormaLast, EnrichProbes, EnrichPaths, EnrichFirst
| order by EnrichNearNorma desc, NormaRequests desc

// The ARTEX container toolchain seen from one source
// Agentic attack detections by ThreatDefence (ARTEX). Source: https://threatdefence.com/article/artex-agentic-attack-framework-detection-hunting
// ATT&CK: T1595.002 (Active Scanning: Vulnerability Scanning)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting. Refines hunt 17.
// From the ARTEX source code. The image is always built from the repository Dockerfile, on Debian bookworm, with pinned
// tools: sqlmap 1.9.9, ffuf v2.3.0, nuclei v3.11.1, httpx v1.12.0, katana v1.8.0, dalfox v3.2.4, bbot 3.0.2, nmap from
// apt and Playwright 1.64.1 with headless Chromium (Dockerfile:71-220). Next to the scanners sit ARTEX's own clients:
// WebFetch ("norma/0.4"), the enrichment probe ("Go-http-client/1.1"), the api-recon skill scripts
// ("Mozilla/5.0 (spa-api-recon)" and "Mozilla/5.0 (spa-api-recon spider)", skills/api-recon/scripts/harvest_static.py:23,
// spider_mpa.py:22) and bookworm's curl 7.88.1 and Wget 1.21.3. Hunt 17 counts any user agent families. This one scores
// the specific clients the ARTEX image carries, so three or more of them from one address in an hour is a much narrower
// lead. Each scanner user agent can be changed with a flag, the bookworm versions change with the base image, and
// "norma/0.4" and "spa-api-recon" need a code change.

let Window = 14d;
let Clients = (ua:string) { case(
    ua == "norma/0.4", "norma WebFetch",
    ua == "Go-http-client/1.1", "Go enrichment probe",
    ua has "spa-api-recon", "api-recon skill",
    ua startswith "sqlmap/1.9", "sqlmap 1.9",
    ua has "Fuzz Faster U Fool", "ffuf",
    ua has "Nmap Scripting Engine", "nmap NSE",
    ua has "HeadlessChrome", "headless Chromium",
    ua == "curl/7.88.1", "bookworm curl",
    ua == "Wget/1.21.3", "bookworm wget",
    ua startswith "python-requests/" or ua startswith "Python-urllib/3.12", "Python 3.12 clients",
    "") };
union isfuzzy=true
    (CommonSecurityLog | where TimeGenerated > ago(Window) and isnotempty(RequestClientApplication)
        | project TimeGenerated, Src=SourceIP, Host=DestinationHostName, UA=RequestClientApplication),
    (W3CIISLog | where TimeGenerated > ago(Window)
        | project TimeGenerated, Src=cIP, Host=csHost, UA=replace_string(csUserAgent, "+", " "))
| where not(ipv4_is_private(Src)) and Src != "127.0.0.1"
| extend Client = Clients(UA)
| where isnotempty(Client)
| summarize Requests=count(), Clients=dcount(Client), ClientList=make_set(Client), Hosts=make_set(Host, 10),
    SampleUAs=make_set(UA, 10) by Src, bin(TimeGenerated, 1h)
| where Clients >= 3
// The ARTEX-specific clients weigh more than the generic ones.
| extend Specific = set_intersect(ClientList, dynamic(["norma WebFetch", "api-recon skill", "Go enrichment probe"]))
| summarize Hours=count(), TotalRequests=sum(Requests), MaxClients=max(Clients), ClientList=make_set(ClientList),
    Specific=make_set(Specific), Hosts=make_set(Hosts, 20), SampleUAs=make_set(SampleUAs, 20),
    FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated) by Src
| order by array_length(Specific) desc, MaxClients desc, TotalRequests desc

// Metronomic request rates that match the ARTEX noise profiles
// Agentic attack detections by ThreatDefence (ARTEX). Source: https://threatdefence.com/article/artex-agentic-attack-framework-detection-hunting
// ATT&CK: T1595.002 (Active Scanning: Vulnerability Scanning)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the ARTEX source code. An operator who wants to stay quiet turns on a noise profile (ARTEX_NOISE_PROFILE or the
// Target noise card). The egress governor then paces requests per host with a token bucket and a small uniform jitter of
// at most min(jitter/rate, 250 ms) (egress/egress.go:50-57): quiet = 2 requests a second (gaps of 500 to 750 ms),
// balanced = 5 (200 to 240 ms), aggressive = 20 (50 to 55 ms). The agents are also handed matching scanner flags such as
// nmap "-T2 --max-rate 2 --max-retries 2", ffuf "-rate 2 -t 1" and sqlmap "--delay=0.5 --threads=1"
// (agent/noise_profile.go:56-67). The result is a source that hits one host every second of a long window at an almost
// fixed rate. People never do that, and most scanners run faster and burstier.
// Web logs usually keep whole seconds, so this hunt uses requests per second rather than gaps. The default profile is
// off, so this only finds operators who chose to be careful. Rates are fixed in code, but a rebuild can change them.

let Window = 7d;
let Web = union isfuzzy=true
    (CommonSecurityLog | where TimeGenerated > ago(Window) and isnotempty(RequestURL)
        | project TimeGenerated, Src=SourceIP, Host=DestinationHostName, UA=RequestClientApplication),
    (W3CIISLog | where TimeGenerated > ago(Window)
        | project TimeGenerated, Src=cIP, Host=csHost, UA=csUserAgent);
Web
| summarize PerSecond=count(), UAs=make_set(UA, 5) by Src, Host, Second=bin(TimeGenerated, 1s)
| summarize ActiveSeconds=count(), Requests=sum(PerSecond), MeanRps=avg(PerSecond), StdevRps=stdev(PerSecond),
    MaxRps=max(PerSecond), UAs=make_set(UAs, 10) by Src, Host, Window10m=bin(Second, 10m)
// Busy in at least 80% of the 600 seconds, with almost no spread around the mean.
| where ActiveSeconds >= 480 and StdevRps <= 0.8
| extend Profile = case(
    MeanRps between (1.2 .. 2.1) and MaxRps <= 4, "quiet (2/s)",
    MeanRps between (4.0 .. 5.2) and MaxRps <= 10, "balanced (5/s)",
    MeanRps between (17.0 .. 20.5) and MaxRps <= 40, "aggressive (20/s)",
    "")
| where isnotempty(Profile)
| summarize Windows=count(), Requests=sum(Requests), Profiles=make_set(Profile), UAs=make_set(UAs, 10),
    FirstSeen=min(Window10m), LastSeen=max(Window10m) by Src, Host
// Two paced windows or more. Exclude your own monitoring and uptime checkers here.
| where Windows >= 2
| order by Windows desc

// Headless browsers and ARTEX clients signing in, and the pause while a person relays the MFA code
// Agentic attack detections by ThreatDefence (ARTEX). Source: https://threatdefence.com/article/artex-agentic-attack-framework-detection-hunting
// ATT&CK: T1078.004 (Valid Accounts: Cloud Accounts), T1111 (Multi-Factor Authentication Interception)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the ARTEX source code. ARTEX has no Entra ID or Okta module of its own. When an agent logs in to an application
// it drives the bundled Playwright MCP server with headless Chromium (Dockerfile:212-220), whose user agent says
// "HeadlessChrome" unless the operator overrides it. Captcha, email codes and MFA are handed to the operator through
// the ask_operator tool, which pauses the agent until a person types the answer (agent/worker.go:288-290). Approval
// gates hold a call for up to 300 seconds (intercept/intercept.go:85). In the sign-in logs that reads as an MFA
// challenge from a headless or scripted client, a silence of one to fifteen minutes, then success from the same address.
// Credentials the agents find or create are kept per task and reused across workers (agent/tools_creds.go), so one
// account can appear from several of these clients in the same hour.
// "HeadlessChrome" disappears if the operator sets a browser user agent. The relay pause does not depend on it.

let Window = 14d;
let AgentClient = (ua:string) { ua has "HeadlessChrome" or ua == "norma/0.4" or ua has "spa-api-recon"
    or ua startswith "Go-http-client/" or ua startswith "python-requests/" or ua startswith "curl/" };
let SignIns = union isfuzzy=true SigninLogs, AADNonInteractiveUserSignInLogs
    | where TimeGenerated > ago(Window)
    | project TimeGenerated, UserPrincipalName, IPAddress, UserAgent, ResultType=tostring(ResultType), AppDisplayName;
// Part 1: every sign-in attempt from a headless or scripted client named above
let Clients = SignIns
    | where AgentClient(UserAgent)
    | summarize Attempts=count(), Successes=countif(ResultType == "0"), Results=make_set(ResultType, 10),
        Apps=make_set(AppDisplayName, 10), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated)
        by UserPrincipalName, IPAddress, UserAgent
    | extend Signal = "headless or scripted client";
// Part 2: an MFA interrupt from such a client, then a success from the same user and address 1 to 15 minutes later
let Interrupts = SignIns
    | where ResultType in ("50074", "50076", "50079", "500121") and AgentClient(UserAgent)
    | project InterruptTime=TimeGenerated, UserPrincipalName, IPAddress, InterruptUA=UserAgent;
let Relay = Interrupts
    | join kind=inner (SignIns | where ResultType == "0" | project SuccessTime=TimeGenerated, UserPrincipalName, IPAddress,
        SuccessApp=AppDisplayName) on UserPrincipalName, IPAddress
    | extend PauseMin = datetime_diff('minute', SuccessTime, InterruptTime)
    | where PauseMin between (1 .. 15)
    | summarize Attempts=count(), Successes=dcount(SuccessTime), Results=make_set(strcat("pause ", PauseMin, " min"), 10),
        Apps=make_set(SuccessApp, 10), FirstSeen=min(InterruptTime), LastSeen=max(SuccessTime)
        by UserPrincipalName, IPAddress, UserAgent=InterruptUA
    | extend Signal = "MFA relayed after a pause";
union Clients, Relay
| summarize Signals=make_set(Signal), Attempts=sum(Attempts), Successes=sum(Successes), Results=make_set(Results, 20),
    Apps=make_set(Apps, 20), FirstSeen=min(FirstSeen), LastSeen=max(LastSeen) by UserPrincipalName, IPAddress, UserAgent
| order by array_length(Signals) desc, Successes desc

// Accounts registered by a source that is also probing the application
// Agentic attack detections by ThreatDefence (ARTEX). Source: https://threatdefence.com/article/artex-agentic-attack-framework-detection-hunting
// ATT&CK: T1136 (Create Account), T1595.002 (Active Scanning: Vulnerability Scanning)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the ARTEX source code. Workers are told to test on objects they own first and to touch at most three objects that
// belong to someone else (agent/worker.go:285). In practice they register their own accounts on the target with a strong
// unique password, store them with save_task_credential and hand them to the next worker (agent/tools_creds.go:92-117),
// so authenticated testing starts with sign-ups from the same address that is reading the application. The seeded
// safety rules block HTTP DELETE and paths such as /delete, /remove, /purge and /reset-all (db/db.go:437-720,
// deleteEndpointPathPattern at :688), so an ARTEX source that creates accounts and objects rarely deletes them.
// Adjust the registration paths to your applications. Operators can delete the safety rules, so the DELETE check is a
// hint, not a filter.

let Window = 14d;
let RegisterPath = @"(?i)/(register|registration|signup|sign-up|sign_up|join|users/new|account/create|auth/register|api/users)(?:[/?]|$)";
let Web = union isfuzzy=true
    (CommonSecurityLog | where TimeGenerated > ago(Window) and isnotempty(RequestURL)
        | project TimeGenerated, Src=SourceIP, Host=DestinationHostName, Method=RequestMethod, Url=RequestURL,
            UA=RequestClientApplication),
    (W3CIISLog | where TimeGenerated > ago(Window)
        | project TimeGenerated, Src=cIP, Host=csHost, Method=csMethod, Url=csUriStem, UA=replace_string(csUserAgent, "+", " "));
Web
| summarize Requests=count(), Paths=dcount(tostring(split(Url, "?")[0])),
    Registrations=countif(Method == "POST" and Url matches regex RegisterPath),
    Deletes=countif(Method == "DELETE"),
    AgentUA=countif(UA == "norma/0.4" or UA has "spa-api-recon" or UA has "HeadlessChrome" or UA == "Go-http-client/1.1"),
    UAs=make_set(UA, 10), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated)
    by Src, Host, Day=bin(TimeGenerated, 1d)
// Several sign-ups from one address on one day, while it reads many distinct paths
| where Registrations >= 2 and Paths >= 50
| extend Strength = iff(AgentUA > 0, "sign-ups plus ARTEX client user agents", "sign-ups during probing")
| project Day, Src, Host, Strength, Registrations, Paths, Requests, Deletes, AgentUA, UAs, FirstSeen, LastSeen
| order by AgentUA desc, Registrations desc

// ARTEX running on a host you monitor: agent shells, the recording proxy, resolver fan-out and archives
// Agentic attack detections by ThreatDefence (ARTEX). Source: https://threatdefence.com/article/artex-agentic-attack-framework-detection-hunting
// ATT&CK: T1588.002 (Obtain Capabilities: Tool), T1059.004 (Command and Scripting Interpreter: Unix Shell)
// Example hunt for Defender XDR advanced hunting and Microsoft Sentinel. Test before alerting. Refines hunt 20.
// From the ARTEX source code. Signals the binary leaves on the machine it runs on, for an insider, an intruder staging
// from your network, or a tester you did not know about:
//  - Agent commands run through a shim: "bash" is a symlink to the artex binary in a temporary "artex-exec-" folder,
//    run as uid/gid 10001, and MCP servers start as "artex __artex-exec-drop <uid> <gid> -- <cmd>"
//    (server/execpriv.go:25, server/execpriv_unix.go:539-575).
//  - Agent shells carry HTTP_PROXY=http://artex-pace:artex-pace@127.0.0.1:8788 (egress/pace.go:20, agent/worker.go:229-252).
//  - The UI listens on 8787 and the recording proxy on 8788, both on loopback by default and on every interface in the
//    Docker image (cmd/artex/main.go:101-103, Dockerfile:243-245).
//  - The enrichment engine resolves every new domain by sending UDP/53 straight to eight public resolvers, past your
//    own DNS servers (enrich/enrich.go:71-76, dnsx DefaultResolvers).
//  - Skill scripts and outputs: harvest_static.py, spider_mpa.py, runtime_harvest.js, bbot runs with "-o bbot-output".
//  - Noise-profile scanner flags are handed to the agents verbatim (agent/noise_profile.go:56-67).
//  - Task archives can go to S3 under "artex/tasks/task-" (archivestore/s3.go:76-79).
//  - The browser capture extension is named "ARTEX Traffic Capture" (extension/manifest.json).
// The shim, the proxy credential and the resolver list need a code change to remove. Ports, paths and flags do not.

let Window = 30d;
let PublicResolvers = dynamic(["1.1.1.1", "1.0.0.1", "8.8.8.8", "8.8.4.4", "9.9.9.9", "149.112.112.112",
    "208.67.222.222", "208.67.220.220"]);
let NoiseFlags = @"--max-rate 2 --max-retries 2|-rate-limit 2 -c 1|-rl 2 -[tc] 1|-rate 2 -t 1|--rate-limit 2 --workers 1|--delay=0\.(5|2|05)\b";
union isfuzzy=true
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where FolderPath contains "/artex-exec-" or InitiatingProcessFolderPath contains "/artex-exec-"
            or ProcessCommandLine matches regex @"__artex-exec-drop|artex-pace:artex-pace|harvest_static\.py|spider_mpa\.py|runtime_harvest\.js|-o bbot-output"
            or (ProcessCommandLine matches regex NoiseFlags and FileName in~ ("nmap", "nuclei", "httpx", "katana", "ffuf", "dalfox", "python3", "sqlmap"))
            or (InitiatingProcessFileName =~ "artex" and FileName in~ ("bash", "sh", "nuclei", "httpx", "katana", "ffuf", "nmap", "node"))
        | project Timestamp, DeviceName, Signal="process", Process=FileName, Path=FolderPath, Account=AccountName,
            CommandLine=ProcessCommandLine, Detail=InitiatingProcessCommandLine),
    (DeviceNetworkEvents
        | where Timestamp > ago(Window)
        | where ActionType == "ListeningConnectionCreated" and LocalPort in (8787, 8788)
            and (InitiatingProcessFileName =~ "artex" or InitiatingProcessFolderPath endswith "/artex")
        | project Timestamp, DeviceName, Signal="console or recording proxy listening", Process=InitiatingProcessFileName,
            Path=InitiatingProcessFolderPath, Account=InitiatingProcessAccountName, CommandLine=InitiatingProcessCommandLine,
            Detail=strcat("port ", LocalPort)),
    (DeviceNetworkEvents
        | where Timestamp > ago(Window)
        | where RemotePort == 53 and RemoteIP in (PublicResolvers)
        | summarize Resolvers=dcount(RemoteIP), Queries=count(), FirstQuery=min(Timestamp),
            Process=take_any(InitiatingProcessFileName), Path=take_any(InitiatingProcessFolderPath)
            by DeviceName, Hour=bin(Timestamp, 1h)
        // dnsx spreads queries across the whole list; a normal forwarder uses one or two
        | where Resolvers >= 5
        | project Timestamp=FirstQuery, DeviceName, Signal="direct DNS to the dnsx resolver list", Process, Path, Account="",
            CommandLine="", Detail=strcat(Resolvers, " resolvers, ", Queries, " queries")),
    (DeviceTvmBrowserExtensions
        | where ExtensionName =~ "ARTEX Traffic Capture"
        | project Timestamp=now(), DeviceName=DeviceId, Signal="ARTEX capture extension installed", Process=BrowserName,
            Path=ExtensionId, Account="", CommandLine="", Detail=tostring(ExtensionRisk)),
    (AWSCloudTrail
        | where TimeGenerated > ago(Window)
        | where EventName in ("PutObject", "CreateMultipartUpload", "CompleteMultipartUpload")
        | where tostring(parse_json(RequestParameters).key) startswith "artex/tasks/task-"
        | project Timestamp=TimeGenerated, DeviceName=SourceIpAddress, Signal="ARTEX task archive written to S3",
            Process=UserAgent, Path=tostring(parse_json(RequestParameters).bucketName), Account=UserIdentityArn,
            CommandLine="", Detail=tostring(parse_json(RequestParameters).key))
| order by Timestamp desc

// ARTEX console and side-channel traffic in your outbound proxy logs
// Agentic attack detections by ThreatDefence (ARTEX). Source: https://threatdefence.com/article/artex-agentic-attack-framework-detection-hunting
// ATT&CK: T1071.001 (Application Layer Protocol: Web Protocols)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the ARTEX source code. Someone on your network who drives a remote ARTEX console, or an ARTEX host behind your
// proxy, leaves requests a TLS-inspecting proxy can name:
//  - Console API paths on port 8787: /api/auth/status, /api/auth/login (the username is always "ARTEX"), /api/health,
//    /api/tasks, and /api/traffic/ingest, where the "ARTEX Traffic Capture" browser extension posts captured traffic
//    in batches of ten (server/auth.go:287-293, extension/background.js:10-11,148-151). Development builds put the
//    session token in the query string as ?token= (web/src/lib/api.ts:214-226).
//  - The opt-in update check: GET https://api.github.com/repos/BaaRai/ARTEX/releases/latest with the user agent
//    "artex-update-check", at most once a day (server/update_check.go:18-71).
//  - The Keenable search backend, which sends "X-Keenable-Title: ARTEX" to api.keenable.ai (agent/worker.go:46).
//  - Finding alerts sent straight to DingTalk, Feishu, WeCom or Telegram, never through the ARTEX proxy, so they show
//    the operator's real address (notify/http.go:111-125).
// Paths and the port can be changed with a reverse proxy, the update check is off by default, and the Keenable and
// notification channels are optional. The "artex-update-check" user agent needs a code change.

let Window = 30d;
let NotifyHosts = dynamic(["oapi.dingtalk.com", "open.feishu.cn", "open.larksuite.com", "qyapi.weixin.qq.com", "api.telegram.org"]);
CommonSecurityLog
| where TimeGenerated > ago(Window) and isnotempty(RequestURL)
| extend Signal = case(
    RequestClientApplication == "artex-update-check" or RequestURL has "/repos/BaaRai/ARTEX/releases", "ARTEX update check",
    RequestURL has "/api/traffic/ingest", "capture extension posting to a console",
    RequestURL has_any ("/api/auth/status", "/api/auth/login", "/api/ready") and (DestinationPort == 8787 or RequestURL contains ":8787/"),
        "console sign-in on port 8787",
    (DestinationPort == 8787 or RequestURL contains ":8787/") and RequestURL contains "token=ey", "console session token in a URL",
    RequestURL has "api.keenable.ai", "Keenable search backend",
    "")
| where isnotempty(Signal)
| summarize Requests=count(), Signals=make_set(Signal), Destinations=make_set(DestinationHostName, 10),
    SampleURLs=make_set(RequestURL, 10), UAs=make_set(RequestClientApplication, 5),
    FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated) by SourceIP, SourceUserName
// Bring in the chat-ops alerts from the same internal source as context
| join kind=leftouter (CommonSecurityLog
    | where TimeGenerated > ago(Window) and DestinationHostName in (NotifyHosts)
    | summarize NotifyRequests=count(), NotifyDestinations=make_set(DestinationHostName) by SourceIP) on SourceIP
| project-away SourceIP1
| order by array_length(Signals) desc, Requests desc

// Bracketed-paste bytes in shell input on a compromised host
// Agentic attack detections by ThreatDefence (ARTEX). Source: https://threatdefence.com/article/artex-agentic-attack-framework-detection-hunting
// ATT&CK: T1059.004 (Command and Scripting Interpreter: Unix Shell)
// Example hunt for Microsoft Sentinel and Defender XDR advanced hunting. Low confidence on its own. Test before alerting.
// From the ARTEX source code. Agents drive interactive sessions (nc shells, ssh, database clients, REPLs) through the
// shell_open and shell_send tools, which are on by default for every agent (db/db.go:314-321). When the model sends
// several lines at once, the library wraps them in the terminal bracketed-paste codes ESC[200~ and ESC[201~
// (BaaRai/Norma v0.4.11, tool/shell_tools.go:225-227), presses Enter as a carriage return and waits for eight seconds of
// silence before reading (tool/shell_session.go:26). A real terminal hides those codes. A raw reverse shell does not:
// the shell receives "^[[200~" in front of the first command and "^[[201~" after the last, and usually prints a
// "not found" error for both. The library echoes no completion marker, so the rest of the command line is the model's.
// Where shell input, TTY audit or command errors reach your logs, look for those bytes. They are rare in any other
// source. The codes are fixed in the library and need a code change to remove.

let Window = 30d;
union isfuzzy=true
    (Syslog
        | where TimeGenerated > ago(Window)
        | where SyslogMessage contains "[200~" or SyslogMessage contains "[201~" or SyslogMessage contains "1b5b3230307e"
        | project TimeGenerated, Computer, Source="Syslog", Process=ProcessName, Detail=SyslogMessage),
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine contains "[200~" or ProcessCommandLine contains "[201~"
        | project TimeGenerated=Timestamp, Computer=DeviceName, Source="DeviceProcessEvents", Process=FileName,
            Detail=strcat(InitiatingProcessFileName, " > ", ProcessCommandLine)),
    (DeviceEvents
        | where Timestamp > ago(Window)
        | where tostring(AdditionalFields) contains "[200~" or ProcessCommandLine contains "[200~"
        | project TimeGenerated=Timestamp, Computer=DeviceName, Source="DeviceEvents", Process=FileName,
            Detail=strcat(ActionType, " ", ProcessCommandLine))
| order by TimeGenerated desc

// AntiFox intrusion pattern: an IIS web shell, web.config theft, then AWS enumeration from hosting infrastructure
// Agentic attack detections by ThreatDefence (ARTEX, AntiFox fork). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1505.003 (Server Software Component: Web Shell), T1552.001 (Unsecured Credentials: Credentials In Files), T1580 (Cloud Infrastructure Discovery)
// Example hunt for Defender XDR advanced hunting and Microsoft Sentinel with AWS CloudTrail. Test and baseline before alerting.
// Arctic Wolf Labs (November 10, 2026) tied AntiFox consoles on Alibaba Cloud (47.79.4.33, 8.208.101.210) to intrusions:
//  - w3wp.exe wrote an ASPX web shell (pwn*.aspx) into an upload folder and started cmd.exe, powershell.exe, where.exe,
//    whoami.exe and icacls.exe to check the user, list the app folder and test write access to the web root.
//  - PowerShell read web.config connection strings and app settings through System.Web.Configuration
//    (WebConfigurationManager, WebConfigurationFileMap, VirtualDirectoryMapping), and copied config and logs into the
//    upload folder under .txt names (cfg*.txt, wc*.txt, el*.txt).
//  - With AWS keys, one source cycled through several identities and sent hundreds of List, Get and Describe calls across
//    dozens of services in about half an hour (Boto3/Botocore 1.43.125). Most were denied; a GetSecretValue on a
//    production secret and S3 GetObject, CopyObject and DeleteObject calls succeeded.
// AntiFox is ARTEX's code renamed, so the other ARTEX hunts apply too. Do not dismiss a burst because most calls failed.

let Window = 14d;
let WebShellChildren = dynamic(["cmd.exe", "powershell.exe", "pwsh.exe", "where.exe", "whoami.exe", "icacls.exe", "7z.exe", "rar.exe", "tar.exe", "certutil.exe"]);
union isfuzzy=true
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where InitiatingProcessFileName =~ "w3wp.exe" and FileName in~ (WebShellChildren)
        | extend ConfigRead = ProcessCommandLine has_any ("WebConfigurationManager", "WebConfigurationFileMap", "VirtualDirectoryMapping", "ConnectionStrings", "AppSettings")
        | summarize Commands=make_set(substring(ProcessCommandLine, 0, 200), 15), Children=make_set(FileName, 10), ConfigReads=countif(ConfigRead),
            Timestamp=min(Timestamp) by DeviceName, AppPool=InitiatingProcessCommandLine
        | project Timestamp, Device=DeviceName, Signal=iff(ConfigReads > 0, "w3wp shell reading web.config secrets", "w3wp started shell tools"),
            Detail=strcat(tostring(Children), " ", tostring(Commands))),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where InitiatingProcessFileName =~ "w3wp.exe" and ActionType == "FileCreated"
        | where FileName endswith ".aspx" or FileName matches regex @"(?i)^(pwn.*\.aspx|cfg.*\.txt|wc.*\.txt|el.*\.txt)$"
        | project Timestamp, Device=DeviceName, Signal="w3wp wrote an ASPX or a copied config/log file", Detail=FolderPath),
    (AWSCloudTrail
        | where TimeGenerated > ago(Window)
        | where UserAgent has_any ("Boto3/", "Botocore/", "aws-sdk-go", "aws-cli/")
        | where EventName startswith "List" or EventName startswith "Get" or EventName startswith "Describe" or EventName in ("HeadObject", "CopyObject", "DeleteObject")
        | summarize Calls=count(), Denied=countif(ErrorCode in ("AccessDenied", "AccessDeniedException", "UnauthorizedOperation")),
            Services=dcount(EventSource), Identities=dcount(UserIdentityArn),
            Succeeded=make_set_if(EventName, isempty(ErrorCode) and EventName in ("GetSecretValue", "GetObject", "CopyObject", "DeleteObject", "GetParameter"), 10),
            UAs=make_set(UserAgent, 3), Timestamp=min(TimeGenerated) by SourceIpAddress, bin(TimeGenerated, 30m)
        | where Services >= 8 and Calls >= 100
        | extend Known = SourceIpAddress in ("47.79.4.33", "8.208.101.210")
        | project Timestamp, Device=SourceIpAddress,
            Signal=iff(Known, "AWS burst from a reported AntiFox address", "AWS enumeration burst across many services"),
            Detail=strcat(Calls, " calls, ", Denied, " denied, ", Services, " services, ", Identities, " identities, succeeded: ", tostring(Succeeded), " ", tostring(UAs)))
| order by Timestamp desc

// AutoPT on a host you monitor
// Agentic attack detections by ThreatDefence (AutoPT). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1059.006 (Command and Scripting Interpreter: Python), T1595.002 (Active Scanning: Vulnerability Scanning)
// Example hunt for Defender XDR advanced hunting. Test and baseline before alerting.
// AutoPT (evenhu9/AutoPT, upstream Dizzy-K/AutoPT) is a research LLM agent that scans one IP with nmap and xray, pulls
// a vulhub proof of concept from GitHub and runs it with shell commands, without approval. No report of its use in a
// real intrusion was found on November 26, 2026, so this hunt looks for the software itself, from its source code:
//  - The CLI: python main.py --name <service/CVE> --ip_addr <IP>, or upstream autopt run --benchmark-name ... --ip-addr ...
//  - The web console: python app.py, listening on TCP 5000 on every interface, with no login.
//  - Agent commands as children of Python: nmap -sS -p- --min-rate 3000 -T4 <IP> (a prompt example), and xray run from
//    <repo>/xray/xray_linux_amd64 or xray_windows_amd64.exe with ws --url.
//  - Result files: src/result/<model>/<service>_<CVE>_<model>_FSM.jsonl.
// What each signal relies on in the source is in ../../source-code-signals.md.

let Window = 30d;
let AutoptProcesses = DeviceProcessEvents
    | where Timestamp > ago(Window)
    | where (ProcessCommandLine has "main.py" and ProcessCommandLine has "--ip_addr" and ProcessCommandLine has "--name")
        or (ProcessCommandLine has "autopt" and ProcessCommandLine has "--benchmark-name" and ProcessCommandLine has "--ip-addr")
        or (InitiatingProcessFileName startswith "python" and ProcessCommandLine has "nmap -sS -p- --min-rate 3000 -T4")
        or (FileName in~ ("xray_linux_amd64", "xray_windows_amd64.exe", "xray_darwin_amd64") and ProcessCommandLine has " ws --url ");
let ConsoleListeners = DeviceNetworkEvents
    | where Timestamp > ago(Window)
    | where ActionType == "ListeningConnectionCreated" and LocalPort == 5000
    | where InitiatingProcessFileName startswith "python" and InitiatingProcessCommandLine has "app.py";
union isfuzzy=true
    (AutoptProcesses
        | summarize Commands=make_set(substring(ProcessCommandLine, 0, 200), 10), Timestamp=min(Timestamp) by DeviceName
        | project Timestamp, DeviceName, Signal="AutoPT CLI, scan step or xray run", Detail=tostring(Commands)),
    (ConsoleListeners
        | summarize Timestamp=min(Timestamp), Commands=make_set(InitiatingProcessCommandLine, 5) by DeviceName
        | project Timestamp, DeviceName, Signal="Python app.py listening on 5000 (possible AutoPT console; check for the page title)", Detail=tostring(Commands)),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FileName endswith "_FSM.jsonl" and (FolderPath has "/result/" or FolderPath has @"\result\")
        | summarize Files=make_set(FolderPath, 10), Timestamp=min(Timestamp) by DeviceName
        | project Timestamp, DeviceName, Signal="AutoPT run result written", Detail=tostring(Files))
| order by Timestamp desc

// Indicator sweep with the agentic watchlist
// Agentic attack detections by ThreatDefence (AutoPT). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1595 (Active Scanning), T1071 (Application Layer Protocol)
// Upload feeds/sentinel-watchlist.csv as a Microsoft Sentinel watchlist with the alias AGENTIC_IOCs and the search key
// "value". A match needs investigation.
// No AutoPT infrastructure has been published, so these rows are fingerprints of the software and its console. The
// truncated Chrome user agent is shared with CyberStrikeAI and Xalgorix; a match on it alone does not mean AutoPT.

let IOC = _GetWatchlist('AGENTIC_IOCs') | where framework has "autopt" | project value=tostring(SearchKey), type, confidence, actor, source;
let UAs = toscalar(IOC | where type == "user_agent" and confidence in ("high", "medium") | summarize make_list(value));
let Domains = toscalar(IOC | where type == "domain" | summarize make_list(value));
union isfuzzy=true
    (CommonSecurityLog | where TimeGenerated > ago(90d)
        | where RequestClientApplication in (UAs) or DestinationHostName has_any (Domains)
        | project TimeGenerated, Source="CommonSecurityLog", Detail=RequestURL,
            Indicator=iff(RequestClientApplication in (UAs), RequestClientApplication, DestinationHostName)),
    (W3CIISLog | where TimeGenerated > ago(90d)
        | extend UA=replace_string(csUserAgent, "+", " ")
        | where UA in (UAs)
        | project TimeGenerated, Source="W3CIISLog", Indicator=UA, Detail=strcat(cIP, " ", csUriStem)),
    (DeviceNetworkEvents | where Timestamp > ago(30d)
        | where RemoteUrl has_any (Domains)
        | project TimeGenerated=Timestamp, Source="DeviceNetworkEvents", Indicator=RemoteUrl,
            Detail=strcat(DeviceName, " ", InitiatingProcessFileName)),
    (DnsEvents | where TimeGenerated > ago(90d)
        | where Name has_any (Domains)
        | project TimeGenerated, Source="DnsEvents", Indicator=Name, Detail=ClientIP)
| join kind=leftouter (IOC) on $left.Indicator == $right.value
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Details=make_set(Detail, 10)
    by Source, Indicator, actor, confidence
| order by LastSeen desc

// AutoPT testing you, or its console used: user agents and console API paths in web and proxy logs
// Agentic attack detections by ThreatDefence (AutoPT). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1595.002 (Active Scanning: Vulnerability Scanning), T1071.001 (Application Layer Protocol: Web Protocols)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the AutoPT source code (evenhu9/AutoPT at e38e2086, Dizzy-K/AutoPT at fb26e0c4):
//  - ReadHTML sends AutoPT/1.0 (upstream) or a Chrome string cut off before "(KHTML, like Gecko)" (evenhu9). The
//    truncated string is shared with CyberStrikeAI's implant and a Xalgorix prompt example.
//  - Before each exploit, evenhu9/AutoPT fetches raw.githubusercontent.com/vulhub/vulhub/master/<service>/<CVE>/README.md
//    with the truncated string (visible only with TLS inspection).
//  - The console (port 5000, no login) answers /api/config with the model keys and starts agent runs on POST
//    /api/task/start. A request to these from anywhere but the operator's own host is someone else using it.
//  - Scans come from nmap -sS -p- --min-rate 3000 -T4 and xray ws --url, which look like any nmap or xray scan.

let Truncated = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36";
let ConsolePaths = dynamic(["/api/task/start", "/api/system/info", "/api/docker/envs", "/api/docker/start"]);
union isfuzzy=true
    (W3CIISLog | extend UA=replace_string(csUserAgent, "+", " ")
        | where UA == Truncated or UA startswith "AutoPT/"
        | project TimeGenerated, Source="W3CIISLog", Src=cIP, Target=csHost, Detail=strcat(csMethod, " ", csUriStem, "?", csUriQuery), UA),
    (CommonSecurityLog
        | where RequestClientApplication == Truncated or RequestClientApplication startswith "AutoPT/"
            or RequestURL has "/vulhub/vulhub/master/" and RequestClientApplication == Truncated
            or RequestURL has_any (ConsolePaths)
        | project TimeGenerated, Source="CommonSecurityLog", Src=SourceIP, Target=DestinationHostName, Detail=RequestURL, UA=RequestClientApplication)
| where TimeGenerated > ago(90d)
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Samples=make_set(Detail, 10),
    UAs=make_set(UA, 5) by Source, Src, Target
| order by FirstSeen asc

// CAI (Cybersecurity AI) running on a host you monitor
// Agentic attack detections by ThreatDefence (CAI). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1588.002 (Obtain Capabilities: Tool), T1059.004 (Command and Scripting Interpreter: Unix Shell), T1543.002 (Create or Modify System Process: Systemd Service)
// Example hunt for Defender XDR advanced hunting. Test before alerting.
// From the CAI source code (aliasrobotics/cai at 6dc79257, v1.1.5, archived August 22, 2026). CAI is a Python CLI,
// package cai-framework, whose agents run shell commands on the operator's machine, in Docker or over SSH:
//  - The operator runs: cai, cai --tui, cai --api [--api-host 0.0.0.0], cai --yaml <file>, cai --yolo, cai --unrestricted.
//    Version 1.x installs from Alias's private index: pip install --index-url https://packages.aliasrobotics.com:664/<key>/.
//  - Every agent command is /bin/sh -c <command> under the python .../bin/cai process, in ~/.cai/workspace.
//  - /virtualization starts docker run -d --name kali-security --network=host ... --security-opt=seccomp=unconfined
//    kalilinux/kali-rolling tail -f /dev/null, then docker exec -w /workspace <id> sh -c <command>.
//  - Session logs: ~/.cai/logs/cai_<uuid>_<time>_<user>_<os>_<ip>.jsonl; API users: ~/.cai/api_auth.json.
//  - The continuous-ops wizard installs ~/.config/systemd/user/cai-cops-run_<hex>.service running
//    python -m cai.continuous_ops.loop_runner --run-dir ~/.cai/continuous_ops/run_<hex>, Restart=always.
//  - Network: logs.aliasrobotics.com (telemetry upload), api.aliasrobotics.com on TCP 666/665, packages.aliasrobotics.com on 664.
// A bare "cai" command line is too short to match on its own; the child-process branch catches it by its children.

let Window = 30d;
let CaiCli = @"(^|[/\\\s])cai(\.exe)?[""']?\s(.*\s)?(--api|--api-host|--api-port|--tui|--yaml|--prompt|--yolo|--unrestricted)([\s=]|$)";
let CaiInstall = @"((pip|pip3|pipx)\s+install|uv\s+(tool\s+install|tool\s+run|pip\s+install|add)|uvx)\s(.*\s)?[""']?cai-framework";
union isfuzzy=true
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine matches regex CaiCli or ProcessCommandLine matches regex CaiInstall
            or ProcessCommandLine has "packages.aliasrobotics.com" or ProcessCommandLine has "cai.continuous_ops.loop_runner"
            or (ProcessCommandLine has "--name kali-security" and ProcessCommandLine has "seccomp=unconfined")
        | project Timestamp, DeviceName, Signal="CAI command, install, loop runner or Kali container", Detail=substring(ProcessCommandLine, 0, 300),
            Parent=strcat(InitiatingProcessFileName, " ", substring(InitiatingProcessCommandLine, 0, 150))),
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where InitiatingProcessCommandLine matches regex @"[/\\]bin[/\\]cai([""'\s]|$)" and FileName in~ ("sh", "bash", "dash", "docker")
        | summarize Commands=make_set(substring(ProcessCommandLine, 0, 200), 15), Timestamp=min(Timestamp), N=count()
            by DeviceName, Parent=substring(InitiatingProcessCommandLine, 0, 150)
        | project Timestamp, DeviceName, Signal="Shell commands run by the cai process", Detail=strcat("x", N, " ", tostring(Commands)), Parent),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FolderPath matches regex @"[/\\]\.cai[/\\]logs[/\\]([A-Za-z0-9_-]+_)?cai_[0-9a-f-]{36}_\d{8}_\d{6}_"
            or FolderPath matches regex @"[/\\]\.cai[/\\](api_auth\.json|continuous_ops[/\\]run_)"
            or (FolderPath has "/systemd/user/" and FileName startswith "cai-cops-")
        | summarize Files=make_set(FileName, 10), Timestamp=min(Timestamp) by DeviceName, Folder=tostring(split(FolderPath, ".cai")[0])
        | project Timestamp, DeviceName, Signal="CAI files under ~/.cai or its systemd unit", Detail=strcat(Folder, " ", tostring(Files)), Parent=""),
    (DeviceNetworkEvents
        | where Timestamp > ago(Window)
        | where RemoteUrl has_any ("logs.aliasrobotics.com", "api.aliasrobotics.com", "packages.aliasrobotics.com")
            or (RemotePort in (664, 665, 666) and InitiatingProcessCommandLine has "cai")
        | project Timestamp, DeviceName, Signal="CAI telemetry, Alias gateway or package index", Detail=strcat(RemoteUrl, " ", RemoteIP, ":", RemotePort),
            Parent=InitiatingProcessCommandLine)
| order by Timestamp desc

// CAI telemetry, Alias gateway, its API backend and its fetch_url user agent in network, proxy and web logs
// Agentic attack detections by ThreatDefence (CAI). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1071.001 (Application Layer Protocol: Web Protocols), T1594 (Search Victim-Owned Websites)
// Example hunt for Microsoft Sentinel. DNS works everywhere; URL paths need a proxy that records full URLs. Test before alerting.
// From the CAI source code (aliasrobotics/cai at 6dc79257):
//  - Telemetry: POST https://logs.aliasrobotics.com/upload at the end of a session (off with CAI_TELEMETRY=false) and
//    /upload/intermediate every 5 model interactions (not turned off by CAI_TELEMETRY), multipart field "log" with the
//    whole session log cai_<uuid>_<time>_<user>_<os>_<ip>.jsonl. The URL is base64-obfuscated in the code.
//  - Licence check GET https://api.aliasrobotics.com:666/key/info on every start; default model alias1 on the same host
//    and port; private package index https://packages.aliasrobotics.com:664/<ALIAS_API_KEY>/ (the key in the URL).
//  - fetch_url sends "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36":
//    a two-part Chrome version real Chrome never sends (CAI_FETCH_USER_AGENT overrides it).
//  - cai --api serves /api/v1/health, /api/tags, /api/openapi.json, /api/docs and /api/v1/sessions/... on 8000 by
//    default; clients send X-CAI-API-Key. Without ALIAS_API_KEY or CAI_API_KEY every route is open.

let Window = 30d;
let FetchUA = "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36";
let AliasHosts = dynamic(["logs.aliasrobotics.com", "api.aliasrobotics.com", "packages.aliasrobotics.com"]);
union isfuzzy=true
    (DnsEvents
        | where TimeGenerated > ago(Window)
        | where Name in~ (AliasHosts)
        | summarize Queries=count(), Names=make_set(Name, 3), Timestamp=min(TimeGenerated) by Src=ClientIP
        | project Timestamp, Src, Signal="DNS for CAI telemetry or the Alias gateway", Detail=strcat("x", Queries, " ", tostring(Names))),
    (CommonSecurityLog
        | where TimeGenerated > ago(Window)
        | where DestinationHostName in~ (AliasHosts) or RequestURL has_any (AliasHosts)
            or RequestURL has "/api/v1/auth/add-ip" or RequestURL has "/messages/stream_tokens"
        | extend Kind = case(RequestURL has "logs.aliasrobotics.com/upload/intermediate", "intermediate log upload",
            RequestURL has "logs.aliasrobotics.com", "session log upload", RequestURL has "/key/info", "licence check",
            RequestURL has "packages.aliasrobotics.com", "private package index", RequestURL has "aliasrobotics.com", "Alias gateway", "CAI API route")
        | summarize Requests=count(), Kinds=make_set(Kind, 6), URLs=make_set(RequestURL, 5), Timestamp=min(TimeGenerated) by Src=SourceIP
        | project Timestamp, Src, Signal="CAI telemetry, gateway or API through the proxy", Detail=strcat(tostring(Kinds), " ", tostring(URLs))),
    (W3CIISLog
        | where TimeGenerated > ago(Window)
        | where replace_string(csUserAgent, "+", " ") == FetchUA
        | summarize Requests=count(), Paths=make_set(csUriStem, 10), Timestamp=min(TimeGenerated) by Src=cIP, Site=csHost
        | project Timestamp, Src, Signal="CAI fetch_url user agent on your site", Detail=strcat(Site, " x", Requests, " ", tostring(Paths))),
    (CommonSecurityLog
        | where TimeGenerated > ago(Window)
        | where RequestClientApplication == FetchUA
        | summarize Requests=count(), URLs=make_set(RequestURL, 10), Timestamp=min(TimeGenerated) by Src=SourceIP
        | project Timestamp, Src, Signal="CAI fetch_url user agent through the proxy or WAF", Detail=strcat("x", Requests, " ", tostring(URLs)))
| order by Timestamp desc

// Indicator sweep
// Agentic attack detections by ThreatDefence (Cairn). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1595 (Active Scanning), T1071 (Application Layer Protocol)
// Example hunt for Microsoft Sentinel and Defender XDR advanced hunting. Test and baseline before alerting.
// Every address and domain published for Cairn operations so far: JPCERT/CC Case E (Cairn, CyberStrikeAI and ARTEX
// attacks on Japanese web apps and WSUS servers), NorForge's AIA0002 staging servers, Scutum's AI-agent sources and the
// staging, C2 and skimmer infrastructure Gambit Security recovered from an operator running Hermes, Strix and Cairn.
// Seven of the JPCERT/CC addresses match the partly redacted addresses of NorForge's AIA0001 Cairn panels on port 8000.
// Addresses are VPS and hosting space that gets reassigned, so check each hit's date against the review_by column in
// iocs/indicators.csv. Hunt from July 1, 2026, the start of the Gambit campaign.

let CairnIPs = dynamic([
    "199.247.25.25","199.247.27.2","31.59.92.155","31.56.206.187","38.244.50.120",
    "46.8.227.73","64.44.24.195","94.183.184.98","94.183.184.254","95.182.99.112",
    "176.65.144.71","38.54.56.121","185.196.220.130","192.236.229.229","155.254.22.215",
    "209.126.4.170","213.21.239.62","172.245.224.188","172.245.89.137"]);
let CairnDomains = dynamic([
    "medbooksource.com","traffic-analyzer.net","b8t.shop","cdn.netlfjs.com",
    "x1opay.co","static-js.com","cdn.js-static.com","js-static.com",
    "jsnetlify.com","netlifyjs.com","newssjs.com"]);
union isfuzzy=true
    (SigninLogs | project TimeGenerated, Source="EntraSignIn", IP=IPAddress, Detail=UserPrincipalName, Extra=UserAgent),
    (AADNonInteractiveUserSignInLogs | project TimeGenerated, Source="EntraNonInteractive", IP=IPAddress, Detail=UserPrincipalName, Extra=UserAgent),
    (CommonSecurityLog | project TimeGenerated, Source="WebOrProxy", IP=SourceIP, Detail=RequestURL, Extra=DestinationIP),
    (W3CIISLog | project TimeGenerated, Source="IIS", IP=cIP, Detail=csUriStem, Extra=csUserAgent),
    (DeviceNetworkEvents | project TimeGenerated=Timestamp, Source="DeviceNetwork", IP=RemoteIP, Detail=RemoteUrl, Extra=DeviceName),
    (DnsEvents | project TimeGenerated, Source="DNS", IP=ClientIP, Detail=Name, Extra=IPAddresses),
    (AWSCloudTrail | project TimeGenerated, Source="CloudTrail", IP=SourceIpAddress, Detail=EventName, Extra=UserAgent)
| where TimeGenerated >= datetime(2026-07-01)
| where IP in (CairnIPs) or Extra in (CairnIPs) or Detail has_any (CairnDomains)
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Samples=make_set(Detail, 10)
    by Source, IP, Extra
| order by FirstSeen asc

// Indicator sweep with the agentic watchlist
// Agentic attack detections by ThreatDefence (Cairn). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1595 (Active Scanning), T1071 (Application Layer Protocol)
// Upload feeds/sentinel-watchlist.csv as a Microsoft Sentinel watchlist with the alias AGENTIC_IOCs and the search key
// "value". A match needs investigation. Addresses are reassigned, so check the reported date and review_by.

let IOC = _GetWatchlist('AGENTIC_IOCs') | where framework has "cairn" | project value=tostring(SearchKey), type, confidence, actor, source;
let IPList = toscalar(IOC | where type == "ipv4" | summarize make_list(value));
let UAs = toscalar(IOC | where type == "user_agent" and confidence in ("high", "medium") | summarize make_list(value));
let Domains = toscalar(IOC | where type == "domain" | summarize make_list(value));
union isfuzzy=true
    (SigninLogs | where TimeGenerated > ago(90d)
        | where IPAddress in (IPList) or UserAgent has_any (UAs)
        | project TimeGenerated, Source="SigninLogs", Indicator=coalesce(IPAddress, UserAgent), Detail=UserPrincipalName),
    (CommonSecurityLog | where TimeGenerated > ago(90d)
        | where SourceIP in (IPList) or DestinationIP in (IPList) or RequestClientApplication has_any (UAs) or DestinationHostName has_any (Domains)
        | project TimeGenerated, Source="CommonSecurityLog", Detail=RequestURL,
            Indicator=case(SourceIP in (IPList), SourceIP, DestinationIP in (IPList), DestinationIP, DestinationHostName)),
    (W3CIISLog | where TimeGenerated > ago(90d)
        | where cIP in (IPList) or replace_string(csUserAgent, "+", " ") has_any (UAs)
        | project TimeGenerated, Source="W3CIISLog", Indicator=cIP, Detail=csUriStem),
    (DeviceNetworkEvents | where Timestamp > ago(30d)
        | where RemoteIP in (IPList) or RemoteUrl has_any (Domains)
        | project TimeGenerated=Timestamp, Source="DeviceNetworkEvents", Indicator=coalesce(RemoteUrl, RemoteIP), Detail=DeviceName),
    (DnsEvents | where TimeGenerated > ago(90d)
        | where Name has_any (Domains)
        | project TimeGenerated, Source="DnsEvents", Indicator=Name, Detail=ClientIP)
| join kind=leftouter (IOC) on $left.Indicator == $right.value
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Details=make_set(Detail, 10)
    by Source, Indicator, actor, confidence
| order by LastSeen desc

// Cairn server, dispatcher and worker containers on a host you monitor
// Agentic attack detections by ThreatDefence (Cairn). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1588.002 (Obtain Capabilities: Tool), T1071.001 (Application Layer Protocol: Web Protocols)
// Example hunt for Defender XDR advanced hunting. Test before alerting.
// From the Cairn source code. Someone running Cairn on your own hosts is an authorized tester, an insider or an intruder.
//  - Server: "cairn serve" (uvicorn, FastAPI) on port 8000, bound to 0.0.0.0 by docker-compose, with no authentication
//    on any route (cli.py:17-18, docker-compose.yaml, server/app.py). Data in ~/.local/share/cairn/cairn.db.
//  - Dispatcher: "cairn dispatch --config dispatch.yaml", with the Docker socket mounted.
//  - Workers: one container per project named cairn-dispatch-<project>, started as "sleep infinity" with host networking
//    from ghcr.io/oritera/cairn-worker-container (dispatcher/runtime/containers.py:20-60).
//  - Files: task prompts as /tmp/cairn-prompts/<phase>-<12 hex>/graph.yaml (dispatcher/tasks/common.py:17), Pi
//    provider keys in /tmp/cairn-pi/<worker>/models.json, and the Tencent competition skill tsec-actions in the workspace.
// Container names, paths and flags need a code change to remove. The port and the compose file are easy to change.

let Window = 30d;
union isfuzzy=true
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine has_any ("cairn serve", "cairn dispatch", "cairn-dispatch-", "cairn-worker-container",
                "--startup-healthcheck-only", "dispatch.local.example.yaml")
            or (ProcessCommandLine contains "uv run" and ProcessCommandLine contains "--project cairn")
            or ProcessCommandLine contains "/tmp/cairn-pi/" or ProcessCommandLine contains "/tmp/cairn-prompts/"
            or ProcessCommandLine contains "TSEC_AGENT_TOKEN"
        | project Timestamp, DeviceName, Signal="process", Detail=substring(ProcessCommandLine, 0, 300),
            Actor=InitiatingProcessFileName, Account=AccountName),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FolderPath contains "/tmp/cairn-prompts/" or FolderPath contains "/tmp/cairn-pi/"
            or FolderPath contains "/skills/tsec-actions/" or (FileName == "cairn.db" and FolderPath contains "/share/cairn/")
        | project Timestamp, DeviceName, Signal="file", Detail=FolderPath, Actor=InitiatingProcessFileName,
            Account=InitiatingProcessAccountName),
    (DeviceNetworkEvents
        | where Timestamp > ago(Window)
        | where ActionType == "ListeningConnectionCreated" and LocalPort == 8000
            and (InitiatingProcessCommandLine has "cairn" or InitiatingProcessCommandLine has "uvicorn")
        | project Timestamp, DeviceName, Signal="server listening on 8000", Detail=InitiatingProcessCommandLine,
            Actor=InitiatingProcessFileName, Account=InitiatingProcessAccountName)
| order by Timestamp desc

// The Cairn worker toolchain seen from one source
// Agentic attack detections by ThreatDefence (Cairn). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1595.002 (Active Scanning: Vulnerability Scanning)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the Cairn source code. The worker image is Kali with kali-linux-headless plus pinned extras: nuclei 3.7.1,
// katana 1.5.0, dalfox 2.12.0, kerbrute 1.0.3, cloudfox 2.0.1, naabu, nikto, dirsearch, netexec, sqlmap from Kali,
// Playwright with headless Chromium, the AWS, Tencent Cloud and Alibaba Cloud CLIs, and the Claude Code, Codex and Pi
// agents (container/Dockerfile). Kali's ffuf identifies as "Fuzz Faster U Fool v2.1.0-dev", the string Scutum saw in
// AI-agent attacks in the Japanese breach wave, mixed with curl, Chrome and Googlebot strings.
// Workers share the host's network (network_mode: host), so every tool leaves from the same address unless the operator
// sends it through a proxy. Three or more of these clients from one address in an hour is a lead; each user agent can
// be changed with a flag, and nuclei and katana randomize theirs by default.

let Window = 14d;
let Clients = (ua:string) { case(
    ua contains "Claude-User (claude-code/", "Claude Code page reader",
    ua contains "Fuzz Faster U Fool v2.1.0-dev", "Kali ffuf",
    ua contains "Fuzz Faster U Fool", "ffuf",
    ua startswith "sqlmap/", "sqlmap",
    ua contains "Nikto", "nikto",
    ua contains "WPScan", "wpscan",
    ua contains "Nmap Scripting Engine", "nmap NSE",
    ua contains "HeadlessChrome", "headless Chromium",
    ua startswith "aws-cli/", "AWS CLI",
    ua contains "TencentCloud" or ua contains "tccli", "Tencent Cloud CLI",
    ua contains "aliyun", "Alibaba Cloud CLI",
    ua startswith "curl/", "curl",
    ua startswith "python-requests/" or ua startswith "Python-urllib/", "Python clients",
    ua contains "Googlebot" and ua !contains "+http://www.google.com/bot.html", "fake Googlebot",
    "") };
union isfuzzy=true
    (CommonSecurityLog | where TimeGenerated > ago(Window) and isnotempty(RequestClientApplication)
        | project TimeGenerated, Src=SourceIP, Host=DestinationHostName, UA=RequestClientApplication),
    (W3CIISLog | where TimeGenerated > ago(Window)
        | project TimeGenerated, Src=cIP, Host=csHost, UA=replace_string(csUserAgent, "+", " "))
| where not(ipv4_is_private(Src))
| extend Client = Clients(UA)
| where isnotempty(Client)
| summarize Requests=count(), Clients=dcount(Client), ClientList=make_set(Client), Hosts=make_set(Host, 10),
    SampleUAs=make_set(UA, 10) by Src, Hour=bin(TimeGenerated, 1h)
| where Clients >= 3
| extend Specific = set_intersect(ClientList, dynamic(["Claude Code page reader", "Kali ffuf", "fake Googlebot"]))
| summarize Hours=count(), TotalRequests=sum(Requests), MaxClients=max(Clients), ClientList=make_set(ClientList),
    Specific=make_set(Specific), Hosts=make_set(Hosts, 20), SampleUAs=make_set(SampleUAs, 20),
    FirstSeen=min(Hour), LastSeen=max(Hour) by Src
| order by array_length(Specific) desc, MaxClients desc

// Uploader web shells and skimmer loaders written by the web server
// Agentic attack detections by ThreatDefence (Cairn). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1505.003 (Server Software Component: Web Shell), T1059.007 (Command and Scripting Interpreter: JavaScript)
// Example hunt for Defender XDR advanced hunting. Test and baseline before alerting.
// From public research on Cairn operations. NorForge's AIA0001 cluster set its goal as an uploader shell: an HTML upload
// form plus move_uploaded_file, explicitly not a command shell. AIA0002 asked for a shell "in a hidden directory deep
// inside" named "something normal like confirm.php". Gambit's operator, using Cairn for exploitation, appended a skimmer
// loader, new Function(atob('<7 junk chars><base64>'.slice(7)))(), to the end of jQuery and Bootstrap files the site
// already served and restored the original timestamps, and at one retailer left a cron job in the JBoss log folder that
// re-appended the skimmer every two minutes after each redeploy.
// File events cannot see content, so this hunt looks for the shape: a web or database process writing a script or a
// library file into the web root, an innocuous name in a deep folder, and crontab entries written by the web user.

let Window = 30d;
let WebProcs = dynamic(["php-fpm", "php", "php-cgi", "php-cgi.exe", "httpd", "apache2", "nginx", "w3wp.exe", "java", "java.exe",
    "tomcat9", "node", "node.exe", "python3", "mysqld", "sqlservr.exe"]);
let WebRoots = dynamic(["/var/www/", "/usr/share/nginx/", "/srv/", "/home/", "/opt/", @"\inetpub\", @"\htdocs\", "/webapps/", "/htdocs/", "/public_html/"]);
union isfuzzy=true
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where ActionType in ("FileCreated", "FileModified", "FileRenamed")
        | where tolower(InitiatingProcessFileName) in (WebProcs) and FolderPath has_any (WebRoots)
        | extend Kind = case(
            FileName matches regex @"(?i)^(confirm|confirmation|checkout_confirm|config\.inc|wp-conf|cache|upload)\w*\.(php|phtml|jsp|aspx)$", "innocuous script name",
            FileName endswith ".php" or FileName endswith ".phtml" or FileName endswith ".jsp" or FileName endswith ".aspx", "script written by the web process",
            FileName matches regex @"(?i)(jquery|bootstrap|require|vendor|bundle|app|main)[\w.-]*\.js$", "served JavaScript library modified",
            "")
        | where isnotempty(Kind)
        | extend Depth = array_length(split(FolderPath, "/")) + array_length(split(FolderPath, @"\")) - 1
        | project Timestamp, DeviceName, Kind, Path=FolderPath, Depth, Actor=InitiatingProcessFileName,
            Detail=InitiatingProcessCommandLine),
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where FileName in~ ("crontab", "bash", "sh") and ProcessCommandLine has "crontab"
        | where InitiatingProcessAccountName in~ ("www-data", "apache", "nginx", "jboss", "tomcat", "wildfly", "nobody")
            or InitiatingProcessFileName in~ ("php-fpm", "php", "java", "httpd", "apache2", "nginx")
        | project Timestamp, DeviceName, Kind="crontab changed by the web user", Path=ProcessCommandLine, Depth=0,
            Actor=InitiatingProcessFileName, Detail=InitiatingProcessCommandLine)
| order by Timestamp desc

// Card data staged, dumped and wiped in e-commerce databases
// Agentic attack detections by ThreatDefence (Cairn). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1213 (Data from Information Repositories), T1485 (Data Destruction)
// Example hunt for Microsoft Sentinel with Azure Database for MySQL audit logs. Adapt to your database audit source.
// From public research. Gambit's operator, using Cairn for exploitation, decrypted Magento card data (cc_number_enc),
// dumped sales_flat_order_payment and sales_flat_quote_payment, then emptied their serialized payment columns in batches,
// following a skill section titled "Database Wipe After Extraction". At a second victim the agent created ZQ-prefixed
// staging tables inside the database, and its cleanup dropped 180 tables whose names matched ZQ or Backup, including
// backups the victim's own administrators had made.
// Any read of the encrypted card column outside the application user, any bulk UPDATE of payment tables, and any CREATE
// or DROP of ZQ-prefixed tables deserves a look. The table names are Magento 1 names; add your own platform's tables.

let Window = 30d;
let PaymentTables = dynamic(["sales_flat_order_payment", "sales_flat_quote_payment", "sales_order_payment", "quote_payment"]);
AzureDiagnostics
| where TimeGenerated > ago(Window)
| where Category in ("MySqlAuditLogs", "MySqlSlowLogs") and isnotempty(column_ifexists("sql_text_s", ""))
| extend Sql = tostring(column_ifexists("sql_text_s", ""))
| extend Kind = case(
    Sql matches regex @"(?i)\b(create|drop)\s+table\s+(if\s+(not\s+)?exists\s+)?`?zq", "ZQ staging table created or dropped",
    Sql matches regex @"(?i)\bdrop\s+table\b" and Sql matches regex @"(?i)(zq|backup)", "bulk drop of ZQ or backup tables",
    Sql has "cc_number_enc", "encrypted card column read",
    Sql matches regex @"(?i)\bupdate\b" and Sql has_any (PaymentTables), "payment table updated",
    Sql matches regex @"(?i)\b(select|into\s+outfile)\b" and Sql has_any (PaymentTables) and Sql matches regex @"(?i)(additional_information|additional_data|cc_)", "payment data selected",
    "")
| where isnotempty(Kind)
| summarize Statements=count(), Kinds=make_set(Kind), Samples=make_set(substring(Sql, 0, 200), 10),
    FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated) by Resource, User=tostring(column_ifexists("user_s", "")), Host=tostring(column_ifexists("host_s", ""))
| order by array_length(Kinds) desc, Statements desc

// Cyber-AutoAgent running on a host you monitor
// Agentic attack detections by ThreatDefence (Cyber-AutoAgent). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1588.002 (Obtain Capabilities: Tool), T1595.002 (Active Scanning: Vulnerability Scanning)
// Example hunt for Defender XDR advanced hunting. Test and baseline before alerting.
// From the Cyber-AutoAgent source code (westonbrown/Cyber-AutoAgent at 54897ff9, archived). It is a Python agent on the
// Strands SDK with a Node terminal front end, usually run in a Kali container built as cyber-autoagent:latest:
//  - The front end starts python /app/src/cyberautoagent.py --module <m> --objective via environment --target <t>
//    --iterations 100 --provider bedrock --output-dir /app/outputs --keep-memory (the objective goes in CYBER_OBJECTIVE).
//    By hand it is cyberautoagent.py --target ... --objective ...; the idle compose container runs --service-mode.
//  - Its general module runs dalfox -b https://dalfox-xss-test.com and feroxbuster -w /tmp/auth_wordlist.txt.
//  - It writes outputs/<target>/OP_<YYYYMMDD_HHMMSS>/cyber_operations.log, security_assessment_report.md,
//    execution_prompt_optimized.txt and ~/.cyber-autoagent/config.json.
// Names need a code change, apart from the output folder (--output-dir) and the image tag.

let Window = 30d;
union isfuzzy=true
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where (ProcessCommandLine has "cyberautoagent.py" and ProcessCommandLine has_any ("--target", "--service-mode"))
            or ProcessCommandLine has "--objective via environment"
            or ProcessCommandLine has "/interfaces/react/dist/index.js"
            or ProcessCommandLine has "cyber-autoagent:latest"
            or (ProcessCommandLine has "dalfox" and ProcessCommandLine has "dalfox-xss-test.com")
            or (ProcessCommandLine has "feroxbuster" and ProcessCommandLine has "/tmp/auth_wordlist.txt")
        | project Timestamp, DeviceName, Signal="Cyber-AutoAgent command, front end, image or module tool",
            Detail=substring(ProcessCommandLine, 0, 300), Parent=strcat(InitiatingProcessFileName, " ", substring(InitiatingProcessCommandLine, 0, 150))),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where (FolderPath matches regex @"[/\\]OP_\d{8}_\d{6}[/\\]"
                and FileName in~ ("cyber_operations.log", "security_assessment_report.md", "execution_prompt_optimized.txt"))
            or FolderPath has ".cyber-autoagent"
        | summarize Files=make_set(FolderPath, 10), Timestamp=min(Timestamp) by DeviceName
        | project Timestamp, DeviceName, Signal="Cyber-AutoAgent operation folder or settings", Detail=tostring(Files), Parent="")
| order by Timestamp desc

// Cyber-AutoAgent in web and proxy logs: its dalfox callback, its Langfuse prompts and its seeded Langfuse project
// Agentic attack detections by ThreatDefence (Cyber-AutoAgent). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1595.002 (Active Scanning: Vulnerability Scanning), T1190 (Exploit Public-Facing Application), T1071.001 (Application Layer Protocol: Web Protocols)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the Cyber-AutoAgent source code (westonbrown/Cyber-AutoAgent at 54897ff9):
//  - Its general module runs dalfox with -b https://dalfox-xss-test.com against up to 10 parameters, so the name
//    shows up in the query strings your web servers log (advanced_payload_coordinator.py:319-330).
//  - It fetches its prompts from Langfuse at /api/public/v2/prompts/cyber/system/... and /cyber/report/...
//    (prompts/factory.py:41-47, :105). Seen in a proxy when its Langfuse is on another machine.
//  - Its compose file seeds a Langfuse project with the id cyber-project-id and publishes Langfuse on 0.0.0.0:3000 with
//    the login admin@cyber-autoagent.com / changeme. Requests to /project/cyber-project-id are someone reading its traces.
// Everything else it sends to a target is stock Kali tools and curl with their own user agents.

let Markers = @"dalfox-xss-test\.com|/api/public/v2/prompts/cyber/(system|report)/|/project/cyber-project-id";
union isfuzzy=true
    (W3CIISLog
        | where TimeGenerated > ago(90d)
        | where csUriStem matches regex Markers or csUriQuery matches regex Markers
        | project TimeGenerated, Source="W3CIISLog", Src=cIP, Target=csHost, Detail=strcat(csUriStem, "?", csUriQuery),
            UA=replace_string(csUserAgent, "+", " ")),
    (CommonSecurityLog
        | where TimeGenerated > ago(90d)
        | where RequestURL matches regex Markers
        | project TimeGenerated, Source="CommonSecurityLog", Src=SourceIP, Target=DestinationHostName, Detail=RequestURL, UA=RequestClientApplication)
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Samples=make_set(Detail, 10),
    UAs=make_set(UA, 5) by Source, Src, Target
| order by FirstSeen asc

// Cyber-AutoAgent threat emulation markers on hosts it reached
// Agentic attack detections by ThreatDefence (Cyber-AutoAgent). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1059 (Command and Scripting Interpreter), T1112 (Modify Registry)
// Example hunt for Defender XDR advanced hunting. Test before alerting.
// Cyber-AutoAgent's threat_emulation module (operation_plugins/threat_emulation/execution_prompt.md:49-55) tells the
// model to leave a marker for every technique it runs: a file .emulation_marker_<TTP_ID>, processes named
// emulation_<name>, registry keys under HKLM\SOFTWARE\EmulationMarkers\ and accounts named emu_<username>. These come
// from the prompt, so the model may vary them, and an operator can edit the prompt. A marker on a host you did not
// schedule an emulation for means the agent ran commands there.

let Window = 30d;
union isfuzzy=true
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FileName startswith ".emulation_marker_"
        | project Timestamp, DeviceName, Signal="Emulation marker file", Detail=FolderPath,
            Parent=strcat(InitiatingProcessFileName, " ", substring(InitiatingProcessCommandLine, 0, 150))),
    (DeviceRegistryEvents
        | where Timestamp > ago(Window)
        | where RegistryKey has @"\SOFTWARE\EmulationMarkers"
        | project Timestamp, DeviceName, Signal="Emulation marker registry key", Detail=strcat(RegistryKey, " ", RegistryValueName),
            Parent=strcat(InitiatingProcessFileName, " ", substring(InitiatingProcessCommandLine, 0, 150))),
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where FileName startswith "emulation_" or ProcessCommandLine has_any ("EmulationMarkers", ".emulation_marker_")
            or (FileName in~ ("net.exe", "net1.exe") and ProcessCommandLine has " /add" and ProcessCommandLine matches regex @"(?i)\semu_\w+")
        | project Timestamp, DeviceName, Signal="Emulation marker process or account", Detail=substring(ProcessCommandLine, 0, 300),
            Parent=strcat(InitiatingProcessFileName, " ", substring(InitiatingProcessCommandLine, 0, 150)))
| order by Timestamp desc

// CyberStrikeAI webshell manager driving a webshell on your servers
// Agentic attack detections by ThreatDefence (CyberStrikeAI). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1505.003 (Server Software Component: Web Shell), T1082 (System Information Discovery)
// Example hunt for Defender XDR advanced hunting with web and proxy logs in Microsoft Sentinel. Test before alerting.
// From the CyberStrikeAI source code (AIPentest/CyberStrikeAI at af6cf750). Once its agent plants a webshell, the console's
// webshell manager talks to it directly:
//  - Every request carries the user agent "Mozilla/5.0 (compatible; CyberStrikeAI-WebShell/1.0)" (internal/handler/webshell.go:799).
//  - Commands go in a "cmd" parameter next to a "pass" parameter, POSTed as a form or, in GET mode, in the query string.
//  - The first thing it runs on a new shell is "echo :OSPROBE_%OS%:END" to tell Windows from Linux (webshell_probe.go:13).
//    On Windows the web server's shell prints :OSPROBE_Windows_NT:END; on Linux the variable stays unexpanded.
// The user agent and parameter names are code; the OS probe needs a code change. Elastic lists the user agent and the probe.

let Window = 30d;
let WebServers = dynamic(["w3wp.exe", "httpd.exe", "httpd", "nginx", "nginx.exe", "php-cgi.exe", "php-cgi", "php-fpm", "php.exe", "java.exe", "java", "tomcat9.exe", "node", "node.exe", "apache2", "sqlservr.exe"]);
union isfuzzy=true
    (W3CIISLog
        | where TimeGenerated > ago(Window)
        | extend UA = replace_string(csUserAgent, "+", " ")
        | where UA has "CyberStrikeAI" or csUriQuery contains "OSPROBE_" or (csUriQuery matches regex @"(^|&)pass=" and csUriQuery matches regex @"(^|&)cmd=")
        | summarize Requests=count(), Paths=make_set(csUriStem, 10), Timestamp=min(TimeGenerated) by Src=cIP, Target=Computer, UA
        | project Timestamp, Src, Target, Signal="CyberStrikeAI webshell request in IIS logs (or pass and cmd parameters in the query)", Detail=strcat(UA, " ", tostring(Paths), " x", Requests)),
    (CommonSecurityLog
        | where TimeGenerated > ago(Window)
        | where RequestClientApplication has "CyberStrikeAI" or RequestURL contains "OSPROBE_"
        | summarize Requests=count(), URLs=make_set(RequestURL, 10), Timestamp=min(TimeGenerated) by Src=SourceIP, Target=DestinationHostName, UA=RequestClientApplication
        | project Timestamp, Src, Target, Signal="CyberStrikeAI user agent or OS probe through the proxy or WAF", Detail=strcat(UA, " ", tostring(URLs))),
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine contains "OSPROBE_"
        | project Timestamp, Src="", Target=DeviceName,
            Signal=iff(InitiatingProcessFileName in~ (WebServers), "Web server ran the CyberStrikeAI OS probe", "CyberStrikeAI OS probe"),
            Detail=strcat(InitiatingProcessFileName, " -> ", substring(ProcessCommandLine, 0, 200)))
| order by Timestamp desc

// CyberStrikeAI implant persistence and the file names seen in real attacks
// Agentic attack detections by ThreatDefence (CyberStrikeAI). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1547.001 (Boot or Logon Autostart Execution: Registry Run Keys / Startup Folder), T1053.005 (Scheduled Task/Job: Scheduled Task), T1053.003 (Scheduled Task/Job: Cron), T1546.004 (Event Triggered Execution: Unix Shell Configuration Modification), T1543.001 (Create or Modify System Process: Launch Agent), T1036.005 (Masquerading: Match Legitimate Resource Name or Location)
// Example hunt for Defender XDR advanced hunting. Test before alerting.
// From the CyberStrikeAI implant template (internal/c2/payload_templates/beacon.go.tmpl:1262-1340). When the operator asks
// the implant to persist, it uses fixed names on every operating system:
//  - Windows: reg add HKCU\Software\Microsoft\Windows\CurrentVersion\Run /v SystemUpdate, then
//    schtasks /create /tn "SystemUpdate" /tr <implant> /sc onlogon /rl highest /f, both through cmd /c.
//  - Linux: (crontab -l 2>/dev/null; echo '@reboot <implant> &') | sort -u | crontab -, then a line
//    "(nohup <implant> &>/dev/null &) # cs" appended to ~/.bashrc.
//  - macOS: ~/Library/LaunchAgents/com.apple.systemupdate.plist with RunAtLoad and KeepAlive.
// Kaspersky saw the SystemUpdate task (as SYSTEM, also created remotely with schtasks /s) and Run value in attacks on
// education organizations, with the beacon named svchosts.exe in C:\Windows\Temp, svcmon32.exe next to it and
// mimikatz renamed wdiag2.exe. The names are code defaults; the operator can change the file names.

let Window = 30d;
union isfuzzy=true
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where (ProcessCommandLine contains @"CurrentVersion\Run" and ProcessCommandLine matches regex @'(?i)/v\s+"?SystemUpdate\b')
            or (ProcessCommandLine has "schtasks" and ProcessCommandLine matches regex @'(?i)/tn\s+"?\\?SystemUpdate\b')
            or (ProcessCommandLine contains "@reboot" and ProcessCommandLine contains "sort -u | crontab -")
        | project Timestamp, DeviceName, Signal="CyberStrikeAI persistence command", Detail=substring(ProcessCommandLine, 0, 300),
            Parent=strcat(InitiatingProcessFileName, " ", InitiatingProcessFolderPath)),
    (DeviceRegistryEvents
        | where Timestamp > ago(Window)
        | where RegistryKey endswith @"\CurrentVersion\Run" and RegistryValueName =~ "SystemUpdate"
        | project Timestamp, DeviceName, Signal="Run value SystemUpdate", Detail=RegistryValueData,
            Parent=strcat(InitiatingProcessFileName, " ", InitiatingProcessFolderPath)),
    (DeviceEvents
        | where Timestamp > ago(Window)
        | where ActionType == "ScheduledTaskCreated" and tostring(parse_json(AdditionalFields).TaskName) =~ @"\SystemUpdate"
        | project Timestamp, DeviceName, Signal="Scheduled task SystemUpdate created", Detail=tostring(parse_json(AdditionalFields).TaskContent),
            Parent=InitiatingProcessFileName),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FileName =~ "com.apple.systemupdate.plist" and FolderPath has "/Library/LaunchAgents/"
            or (FileName =~ ".bashrc" and ActionType in ("FileModified", "FileCreated") and InitiatingProcessFileName !in~ ("bash", "zsh", "sh", "vim", "vi", "nano", "emacs", "code", "dpkg", "rpm", "apt", "yum", "dnf"))
            or (FileName in~ ("svchosts.exe", "svcmon32.exe", "wdiag2.exe") and FolderPath has_any (@"\Windows\Temp\", @"\ProgramData\"))
        | project Timestamp, DeviceName, Signal=strcat("File ", FileName), Detail=FolderPath,
            Parent=strcat(InitiatingProcessFileName, " ", InitiatingProcessCommandLine))
| order by Timestamp desc

// CyberStrikeAI implant check-ins: five seconds, no jitter, fixed headers
// Agentic attack detections by ThreatDefence (CyberStrikeAI). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1071.001 (Application Layer Protocol: Web Protocols), T1095 (Non-Application Layer Protocol)
// Example hunt for Defender XDR advanced hunting with proxy logs in Microsoft Sentinel. Test and baseline before alerting.
// From the CyberStrikeAI source code (internal/c2). The implant is a Go binary the console builds for each listener:
//  - HTTP and HTTPS implants POST to /check_in, then GET /tasks?session_id=<id>, and send results to /result. Every
//    request has X-Implant-Token (fixed per listener) and X-Session-Token headers and, by default, the user agent
//    "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36", a Chrome string cut short that no browser sends.
//  - The default sleep is 5 seconds with 0 percent jitter (internal/c2/types.go:165-169), which Elastic also notes.
//  - The curl_beacon one-liner is a bash loop: curl -fsSk -H "X-Implant-Token: ..." POST $URL/check_in, sleep 5.
//  - The TCP implant opens with the 4 bytes CSB1 and has the same timing.
// Paths, sleep and user agent are configuration; the headers, the CSB1 magic and the loop shape need a code change.
// The regular-interval branch needs tuning: software updaters and monitoring agents also poll on a fixed timer.

let Window = 3d;
let ImplantUA = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36";
union isfuzzy=true
    (CommonSecurityLog
        | where TimeGenerated > ago(Window)
        | where RequestClientApplication == ImplantUA
            or RequestURL contains "/tasks?session_id=" or (RequestURL endswith "/check_in" and RequestMethod == "POST")
        | summarize Requests=count(), URLs=make_set(RequestURL, 5), UAs=make_set(RequestClientApplication, 3), Timestamp=min(TimeGenerated)
            by Src=SourceIP, Dest=coalesce(DestinationHostName, DestinationIP)
        | project Timestamp, Device=Src, Signal="CyberStrikeAI implant paths or user agent through the proxy",
            Detail=strcat(Dest, " ", tostring(URLs), " ", tostring(UAs), " x", Requests)),
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine contains "X-Implant-Token" or (ProcessCommandLine contains "od -An -N32 -tx1 /dev/urandom" and ProcessCommandLine contains "check_in")
        | project Timestamp, Device=DeviceName, Signal="CyberStrikeAI curl_beacon one-liner", Detail=substring(ProcessCommandLine, 0, 300)),
    (DeviceNetworkEvents
        | where Timestamp > ago(Window)
        | where ActionType == "ConnectionSuccess" and RemoteIPType == "Public"
        | where InitiatingProcessFileName !in~ ("svchost.exe", "MsMpEng.exe", "MsSense.exe", "SenseNdr.exe", "chrome.exe", "msedge.exe", "firefox.exe", "Teams.exe", "OneDrive.exe")
        | project Timestamp, DeviceName, RemoteIP, RemotePort, InitiatingProcessFileName, InitiatingProcessFolderPath
        | sort by DeviceName asc, InitiatingProcessFileName asc, RemoteIP asc, Timestamp asc
        | extend Gap = datetime_diff("millisecond", Timestamp, prev(Timestamp)) / 1000.0
        | where DeviceName == prev(DeviceName) and InitiatingProcessFileName == prev(InitiatingProcessFileName) and RemoteIP == prev(RemoteIP)
        | summarize Connections=count(), MeanGap=avg(Gap), StdGap=stdev(Gap), Timestamp=min(Timestamp), Ports=make_set(RemotePort, 5),
            Path=any(InitiatingProcessFolderPath) by DeviceName, InitiatingProcessFileName, RemoteIP
        // A new TCP connection every 4 to 7 seconds with almost no spread, for at least 10 minutes
        | where Connections >= 120 and MeanGap between (4.0 .. 7.0) and StdGap < 1.0
        | project Timestamp, Device=DeviceName, Signal="Connection every ~5 seconds without jitter",
            Detail=strcat(InitiatingProcessFileName, " (", Path, ") -> ", RemoteIP, " ", tostring(Ports), " mean ", round(MeanGap, 2), "s sd ", round(StdGap, 2), "s x", Connections))
| order by Timestamp desc

// A CyberStrikeAI console on a host you monitor, or behind your proxy
// Agentic attack detections by ThreatDefence (CyberStrikeAI). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1588.002 (Obtain Capabilities: Tool), T1071.001 (Application Layer Protocol: Web Protocols)
// Example hunt for Defender XDR advanced hunting with proxy logs in Microsoft Sentinel. Test before alerting.
// From the CyberStrikeAI source code. The console is one Go binary, cyberstrike-ai (run.sh:93), that:
//  - listens on 0.0.0.0:8080 with a self-signed certificate CN=CyberStrikeAI made at every start (config.example.yaml,
//    internal/app/main_server_tls.go:114), and starts C2 listeners on ports the operator picks;
//  - keeps everything in data/conversations.db and data/knowledge.db, implants in tmp/c2/payloads and logs in log/;
//  - builds implants by running "go build -ldflags -s -w -buildid= -trimpath" in tmp/c2/payloads/build-<8 hex>;
//  - calls FOFA, ZoomEye, Quake and Shodan with the user agent CyberStrikeAI/1.7.4, and chat platforms (Telegram, Slack,
//    Discord, DingTalk, Lark, WeCom, QQ, WeChat iLink with CyberStrikeAI/1.0) when bots are configured.
// Approval of tool calls (hitl.default_mode) is off by default. Huntback found a workspace exposed by a file server on
// port 8010 that served /CyberStrikeAI/data/conversations.db, the full record of an operator's session.

let Window = 30d;
union isfuzzy=true
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where FileName in~ ("cyberstrike-ai", "cyberstrike-ai.exe")
            or (FileName in~ ("go", "go.exe") and ProcessCommandLine has "build" and InitiatingProcessFileName in~ ("cyberstrike-ai", "cyberstrike-ai.exe"))
            or InitiatingProcessFileName in~ ("cyberstrike-ai", "cyberstrike-ai.exe")
        | summarize Events=count(), Children=make_set(FileName, 30), Commands=make_set(substring(ProcessCommandLine, 0, 200), 10), Timestamp=min(Timestamp)
            by DeviceName, Parent=InitiatingProcessFileName
        | project Timestamp, Device=DeviceName, Signal="CyberStrikeAI console or implant build", Detail=strcat(tostring(Children), " ", tostring(Commands)), Parent),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FolderPath matches regex @"[/\\]tmp[/\\]c2[/\\]payloads[/\\]"
            or (FileName startswith "beacon_" and FileName matches regex @"_p_[0-9a-f]{14}")
            or (FileName in~ ("conversations.db", "knowledge.db") and InitiatingProcessFileName in~ ("cyberstrike-ai", "cyberstrike-ai.exe"))
        | project Timestamp, Device=DeviceName, Signal="CyberStrikeAI files", Detail=FolderPath, Parent=InitiatingProcessFileName),
    (DeviceNetworkEvents
        | where Timestamp > ago(Window)
        | where ActionType == "ListeningConnectionCreated" and InitiatingProcessFileName in~ ("cyberstrike-ai", "cyberstrike-ai.exe")
        | summarize Ports=make_set(LocalPort, 20), Timestamp=min(Timestamp) by DeviceName
        | project Timestamp, Device=DeviceName, Signal="CyberStrikeAI listeners (console and C2)", Detail=tostring(Ports), Parent="cyberstrike-ai"),
    (CommonSecurityLog
        | where TimeGenerated > ago(Window)
        | where RequestClientApplication startswith "CyberStrikeAI/" or RequestClientApplication == "CyberStrikeAI-Docker-build"
            or RequestURL contains "/CyberStrikeAI/data/conversations.db"
        | summarize Requests=count(), Destinations=make_set(DestinationHostName, 10), Timestamp=min(TimeGenerated) by SourceIP, RequestClientApplication
        | project Timestamp, Device=SourceIP, Signal="CyberStrikeAI console traffic through the proxy",
            Detail=strcat(RequestClientApplication, " -> ", tostring(Destinations), " x", Requests), Parent="")
| order by Timestamp desc

// DarkMoon running on a host you monitor
// Agentic attack detections by ThreatDefence (DarkMoon). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1588.002 (Obtain Capabilities: Tool), T1595.002 (Active Scanning: Vulnerability Scanning)
// Example hunt for Defender XDR advanced hunting. Test before alerting.
// From the DarkMoon source code (ASCIT31/Dark-Moon at bb1b70ce). DarkMoon is a Docker Compose stack (project
// darkmoon-stack) with two containers that both mount the host's Docker socket:
//  - darkmoon (image ascit/darkmoon, root, host network, NET_RAW and NET_ADMIN): the toolbox. Every agent command
//    arrives as docker exec ... timeout --kill-after=5 <n> bash -c <command>.
//  - opencode (image ascit/opencode-darkmoon): an OpenCode fork, the DarkMoon MCP server (python -m src.server from
//    /opt/darkmoon/mcp/server, on 127.0.0.1:8181) and the live log console darkmoon-cli (python -m src.mcp_monitoring).
//  - The operator runs ./darkmoon.sh "TARGET: <host>", which runs opencode run --agent pentest TARGET: ... in the
//    opencode container, and ./darkmoon.sh --log <session_id> to watch the commands.
//  - Files on the host, next to the compose file: .opencode.env (model provider and key), darkmoon-settings/
//    (opencode.json, campaigns/camp_<date>_<id>.json, vulnerabilities/, infrastructure/), reports/pentest_report_<host>_<date>-<time>.md.
// Names and paths need a code change, apart from the image names and the folder the operator cloned into.

let Window = 30d;
union isfuzzy=true
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where (ProcessCommandLine has "opencode" and ProcessCommandLine contains "--agent pentest" and ProcessCommandLine contains "TARGET:")
            or ProcessCommandLine matches regex @"(^|[/\s])darkmoon\.sh(\s|$)"
            or ProcessCommandLine contains "ascit/darkmoon" or ProcessCommandLine contains "ascit/opencode-darkmoon"
            or ProcessCommandLine has_any ("darkmoon-mcp", "darkmoon-cli")
        | project Timestamp, DeviceName, Signal="DarkMoon launcher, image or MCP server", Detail=substring(ProcessCommandLine, 0, 300),
            Parent=strcat(InitiatingProcessFileName, " ", substring(InitiatingProcessCommandLine, 0, 150))),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FolderPath in ("/run/darkmoon-gpu.env", "/tmp/darkmoon-mcp-boot.log")
            or FolderPath startswith "/opt/darkmoon/out/"
            or FolderPath has "/darkmoon-settings/campaigns/camp_"
            or (FolderPath has "/reports/" and FileName startswith "pentest_report_" and FileName endswith ".md")
        | summarize Files=make_set(FileName, 10), Timestamp=min(Timestamp) by DeviceName, Folder=tostring(split(FolderPath, FileName)[0])
        | project Timestamp, DeviceName, Signal="DarkMoon files", Detail=strcat(Folder, " ", tostring(Files)), Parent="")
| order by Timestamp desc

// Indicator sweep with the agentic watchlist
// Agentic attack detections by ThreatDefence (DarkMoon). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1595 (Active Scanning), T1588.002 (Obtain Capabilities: Tool)
// Upload feeds/sentinel-watchlist.csv as a Microsoft Sentinel watchlist with the alias AGENTIC_IOCs and the search key
// "value". A match needs investigation. DarkMoon has no published addresses or domains and sends no telemetry; its rows
// are the user agent dm-edge, the probe strings from its agent prompts, its image names and its file paths.

let IOC = _GetWatchlist('AGENTIC_IOCs') | where framework has "darkmoon" | project value=tostring(SearchKey), type, confidence, actor, source;
let UAs = toscalar(IOC | where type == "user_agent" and confidence in ("high", "medium") | summarize make_list(value));
let UriStrings = toscalar(IOC | where type in ("uri_string", "string") and confidence in ("high", "medium") | summarize make_list(value));
let HostStrings = toscalar(IOC | where type in ("docker_image", "file_path", "string") and confidence in ("high", "medium") | summarize make_list(value));
union isfuzzy=true
    (W3CIISLog | where TimeGenerated > ago(90d)
        | extend UA=replace_string(csUserAgent, "+", " ")
        | where UA in (UAs) or csUriStem has_any (UriStrings) or csUriQuery has_any (UriStrings)
        | project TimeGenerated, Source="W3CIISLog", Indicator=iff(UA in (UAs), UA, strcat(csUriStem, "?", csUriQuery)), Detail=strcat(cIP, " ", csHost)),
    (CommonSecurityLog | where TimeGenerated > ago(90d)
        | where RequestClientApplication in (UAs) or RequestURL has_any (UriStrings)
        | project TimeGenerated, Source="CommonSecurityLog", Indicator=iff(RequestClientApplication in (UAs), RequestClientApplication, RequestURL),
            Detail=strcat(SourceIP, " -> ", DestinationHostName)),
    (DeviceProcessEvents | where Timestamp > ago(30d)
        | where ProcessCommandLine has_any (HostStrings)
        | project TimeGenerated=Timestamp, Source="DeviceProcessEvents", Indicator=substring(ProcessCommandLine, 0, 200), Detail=DeviceName),
    (DeviceFileEvents | where Timestamp > ago(30d)
        | where FolderPath has_any (HostStrings)
        | project TimeGenerated=Timestamp, Source="DeviceFileEvents", Indicator=FolderPath, Detail=strcat(DeviceName, " ", InitiatingProcessFileName))
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Details=make_set(Detail, 10) by Source, Indicator
| order by LastSeen desc

// DarkMoon testing you: its probe strings in web and proxy logs
// Agentic attack detections by ThreatDefence (DarkMoon). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1595.002 (Active Scanning: Vulnerability Scanning), T1190 (Exploit Public-Facing Application), T1525 (Implant Internal Image)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the DarkMoon agent prompts (ASCIT31/Dark-Moon at bb1b70ce, conf/agents/). The model usually copies these commands:
//  - edge-proxy.md:374: the first request to a target is curl -sSI -A dm-edge <target> (a HEAD with user agent dm-edge).
//  - edge-proxy.md:475: cache poisoning test on /?dmcb=DM1 with X-Forwarded-Host: dm-poison.invalid, then the same URL
//    without the header. Most web logs do not record X-Forwarded-Host; the query string is enough.
//  - container-registry.md:452-455: a pushed proof image tagged darkmoon-proof-<random>, then GET /v2/<repo>/manifests/<tag>.
//  - sso-idp.md:492: POST /scim/v2/Users creating a darkmoon-test user (in the body, so usually not in these logs).
// The rest of what DarkMoon sends is its toolbox with defaults (naabu, httpx, nuclei, katana, ffuf, sqlmap): look at what
// the same source sent around a match.

let Markers = @"dmcb=DM1|/manifests/darkmoon-proof-";
union isfuzzy=true
    (W3CIISLog | extend UA=replace_string(csUserAgent, "+", " ")
        | where strcat(csUriStem, "?", csUriQuery) matches regex Markers or UA == "dm-edge"
        | project TimeGenerated, Source="W3CIISLog", Src=cIP, Target=csHost, Detail=strcat(csMethod, " ", csUriStem, "?", csUriQuery), UA),
    (CommonSecurityLog | where RequestURL matches regex Markers or RequestClientApplication == "dm-edge"
        | project TimeGenerated, Source="CommonSecurityLog", Src=SourceIP, Target=DestinationHostName, Detail=RequestURL, UA=RequestClientApplication)
| where TimeGenerated > ago(90d)
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Samples=make_set(Detail, 10),
    UAs=make_set(UA, 5) by Source, Src, Target
| order by FirstSeen asc

// DarkMoon's proof file /tmp/.dm_proof on your database and cache servers
// Agentic attack detections by ThreatDefence (DarkMoon). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1190 (Exploit Public-Facing Application), T1059.004 (Command and Scripting Interpreter: Unix Shell)
// Example hunt for Defender XDR advanced hunting. Test before alerting.
// From the DarkMoon agent prompts (ASCIT31/Dark-Moon at bb1b70ce). To prove command execution or file write, its
// database and cache agents make the server write /tmp/.dm_proof:
//  - sql-databases.md:424,433,459,467: PostgreSQL COPY (select 1) TO PROGRAM 'id > /tmp/.dm_proof 2>&1', COPY ... TO
//    '/tmp/.dm_proof', MySQL SELECT 'proof' INTO OUTFILE '/tmp/.dm_proof', sys_exec('id > /tmp/.dm_proof').
//  - messaging-cache.md:443: a Redis cron line * * * * * id > /tmp/.dm_proof.
// A database or cache process (postgres, mysqld, mariadbd, redis-server, cron) writing it means the attack worked.

let Window = 30d;
union isfuzzy=true
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FolderPath == "/tmp/.dm_proof"
        | project Timestamp, DeviceName, Signal="/tmp/.dm_proof written", Detail=strcat(ActionType, " by ", InitiatingProcessFileName),
            Parent=substring(InitiatingProcessCommandLine, 0, 200)),
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine has "/tmp/.dm_proof"
        | project Timestamp, DeviceName, Signal="command naming /tmp/.dm_proof", Detail=substring(ProcessCommandLine, 0, 300),
            Parent=strcat(InitiatingProcessFileName, " ", substring(InitiatingProcessCommandLine, 0, 150)))
| order by Timestamp asc

// Decepticon running on a host you monitor
// Agentic attack detections by ThreatDefence (Decepticon). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1588.002 (Obtain Capabilities: Tool), T1059.004 (Command and Scripting Interpreter: Unix Shell), T1071.001 (Application Layer Protocol: Web Protocols)
// Example hunt for Defender XDR advanced hunting. Test before alerting.
// From the Decepticon source code (BitterSecurity/Decepticon at 6b15092d, November 20, 2026). Decepticon is a Go
// launcher (decepticon) that runs a Docker Compose stack of LangGraph agents, a LiteLLM gateway, Neo4j, PostgreSQL and a
// Kali sandbox:
//  - Install: curl -fsSL https://decepticon.red/install | bash (or irm https://decepticon.red/install.ps1 | iex) puts
//    the launcher in ~/.local/bin/decepticon and docker-compose.yml, .env and config/litellm.yaml in ~/.decepticon/.
//  - Images: ghcr.io/bittersecurity/decepticon-litellm, -sandbox, -langgraph, -cli, -skillogy, -rea, -c2-sliver,
//    -c2-havoc; containers are named decepticon-<service> (decepticon-<stack>-<service> with DECEPTICON_STACK_NAME).
//  - Inside the sandbox: python3 -m decepticon_sandbox.server on port 9999, every command runs in tmux with the prompt
//    [DCPTN:<status>:<cwd>] and a hook that calls tmux set-option ... @dcptn_completion after each command.
//  - On demand: the c2-sliver container creates the Sliver operator decepticon (/workspace/.sliver-configs/decepticon.cfg).
//  - Telemetry: the setup wizard defaults to sharing, sent to decepticon-telemetry-gateway.purpleailab.workers.dev.
// Processes inside containers are only visible where the EDR sees container processes (Linux hosts, not Docker Desktop).

let Window = 30d;
union isfuzzy=true
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine matches regex @"decepticon\.red/install|ghcr\.io/bittersecurity/decepticon-|decepticon_sandbox\.(server|web|browser)|@dcptn_completion|decepticon\.cli time-window-resume"
            or (ProcessCommandLine contains "sliver-server operator" and ProcessCommandLine contains "--name decepticon")
            or ProcessCommandLine matches regex @"(^|[/\\\s])decepticon(\.exe)?[""']?\s+(onboard|start|update|doctor|mcp\s+serve)(\s|$)"
        | project Timestamp, DeviceName, Signal="Decepticon install, launcher, container or sandbox process", Detail=substring(ProcessCommandLine, 0, 300),
            Parent=strcat(InitiatingProcessFileName, " ", substring(InitiatingProcessCommandLine, 0, 150))),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where (FolderPath matches regex @"[/\\]\.decepticon([/\\]|$)" and FileName in~ (".env", "docker-compose.yml", "install_id", "litellm.yaml", "roe.json", "opplan.json"))
            or (FileName =~ "decepticon.cfg" and FolderPath contains ".sliver-configs")
        | summarize Files=make_set(FileName, 10), Timestamp=min(Timestamp) by DeviceName, FolderPath
        | project Timestamp, DeviceName, Signal="Decepticon files", Detail=strcat(FolderPath, " ", tostring(Files)), Parent=""),
    (DeviceNetworkEvents
        | where Timestamp > ago(Window)
        | where RemoteUrl has "decepticon-telemetry-gateway.purpleailab.workers.dev" or RemoteUrl endswith "decepticon.red"
        | project Timestamp, DeviceName, Signal="Decepticon telemetry or installer site", Detail=RemoteUrl, Parent=InitiatingProcessCommandLine)
| order by Timestamp desc

// Decepticon in web and proxy logs: its own user agents, unfilled user agent templates and its API routes
// Agentic attack detections by ThreatDefence (Decepticon). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1595.002 (Active Scanning: Vulnerability Scanning), T1071.001 (Application Layer Protocol: Web Protocols), T1596.003 (Search Open Technical Databases: Digital Certificates)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the Decepticon source code (BitterSecurity/Decepticon, reviewed at 6b15092d):
//  - Proxy logs from the host that runs it (TLS inspection needed): decepticon-telemetry/1.0 to its telemetry gateway,
//    decepticon-roe/1 to crt.sh when an engagement is created, decepticon-http-sandbox/1 to a remote sandbox daemon,
//    and codex_cli_rs/0.0.0 (Unknown 0; unknown) unknown when it uses a ChatGPT subscription.
//  - Web logs of a target: the Decepticon/ token (helper code and one model gateway entry, not bound to an agent at
//    6b15092d), user agent templates from its opsec skill sent with <CHROME_VER>, <FIREFOX_VER> or <CURRENT_VER> unfilled,
//    and requests to /_decepticon/ on an exposed LangGraph server.
// Most of what Decepticon sends to a target comes from Kali tools and impersonated browsers, so this hunt finds little
// target traffic; the proxy rows are the stronger part.

let OwnUAs = dynamic(["decepticon-telemetry/1.0", "decepticon-roe/1", "decepticon-http-sandbox/1", "codex_cli_rs/0.0.0 (Unknown 0; unknown) unknown"]);
let Markers = @"Decepticon/|<CHROME_VER>|<FIREFOX_VER>|<CURRENT_VER>";
union isfuzzy=true
    (W3CIISLog | extend UA=replace_string(csUserAgent, "+", " ")
        | where UA in (OwnUAs) or UA matches regex Markers or csUriStem startswith "/_decepticon/"
        | project TimeGenerated, Source="W3CIISLog", Src=cIP, Target=csHost, Detail=strcat(csUriStem, "?", csUriQuery), UA),
    (CommonSecurityLog | where RequestClientApplication in (OwnUAs) or RequestClientApplication matches regex Markers
            or RequestURL has "/_decepticon/" or DestinationHostName has "decepticon-telemetry-gateway.purpleailab.workers.dev"
        | project TimeGenerated, Source="CommonSecurityLog", Src=SourceIP, Target=DestinationHostName, Detail=RequestURL, UA=RequestClientApplication)
| where TimeGenerated > ago(90d)
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Samples=make_set(Detail, 10),
    UAs=make_set(UA, 5) by Source, Src, Target
| order by FirstSeen asc

// PentestAgent (GH05TCREW) running on a host you monitor
// Agentic attack detections by ThreatDefence (PentestAgent, GH05TCREW/pentestagent). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1059.006 (Command and Scripting Interpreter: Python), T1588.002 (Obtain Capabilities: Tool)
// Example hunt for Defender XDR advanced hunting. Test before alerting.
// From the source code (GH05TCREW/pentestagent at 5bcf8721). Not the nbshenxm/pentest-agent paper code, which has its own folder.
//  - The operator runs pentestagent [tui|run|mcp_server ...] or python -m pentestagent. The agent runs the model's commands
//    with /bin/sh -c from the python process (TERM=dumb, NO_COLOR=1), or bash -c inside the container pentestagent-sandbox.
//  - Child agents: <python> -m pentestagent mcp_server --type stdio ... --tui --mcp-fifo-in /tmp/pa_mcp_<random>/mcp_in.fifo.
//  - Images ghcr.io/gh05tcrew/pentestagent:latest, :kali, :kali-arm64; files loot/notes.json, loot/token_usage.json,
//    loot/reports/report_<timestamp>.md, ~/.pentestagent/mcp.pid.

let Window = 30d;
let PaCmd = @"(\s-m\s+pentestagent(\s|$)|/bin/pentestagent(\s|$)|pentestagent\s+(mcp_server|tui|run)\s|gh05tcrew/pentestagent|pentestagent-sandbox|--mcp-fifo-in\s+\S*/pa_mcp_)";
union isfuzzy=true
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine matches regex PaCmd
        | project Timestamp, DeviceName, Signal="PentestAgent command, child agent or image", Detail=substring(ProcessCommandLine, 0, 300),
            Parent=strcat(InitiatingProcessFileName, " ", substring(InitiatingProcessCommandLine, 0, 150))),
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where InitiatingProcessCommandLine matches regex PaCmd and FileName in~ ("sh", "dash", "bash")
        | summarize Commands=count(), Samples=make_set(substring(ProcessCommandLine, 0, 200), 10), Timestamp=min(Timestamp) by DeviceName, InitiatingProcessCommandLine
        | project Timestamp, DeviceName, Signal="Commands run by a PentestAgent agent", Detail=strcat(Commands, " ", tostring(Samples)),
            Parent=substring(InitiatingProcessCommandLine, 0, 150)),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where (FileName == "token_usage.json" and FolderPath has "/loot/")
            or (FolderPath has "/loot/reports/" and FileName startswith "report_" and FileName endswith ".md")
            or (FolderPath has "/pa_mcp_" and FileName in ("mcp_in.fifo", "mcp_out.fifo"))
            or (FolderPath has "/.pentestagent/" and FileName in ("mcp.pid", "mcp_servers.json"))
        | summarize Files=make_set(FileName, 10), Timestamp=min(Timestamp) by DeviceName, FolderPath
        | project Timestamp, DeviceName, Signal="PentestAgent files", Detail=strcat(FolderPath, " ", tostring(Files)), Parent="")
| order by Timestamp desc

// PentestAgent (GH05TCREW) MCP server listening on your network, and its browser user agent on your sites
// Agentic attack detections by ThreatDefence (PentestAgent, GH05TCREW/pentestagent). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1071.001 (Application Layer Protocol: Web Protocols), T1595.002 (Active Scanning: Vulnerability Scanning)
// Example hunt for Microsoft Sentinel and Defender XDR. Test and baseline before alerting.
// From the source code (GH05TCREW/pentestagent at 5bcf8721). Not the nbshenxm/pentest-agent paper code.
//  - pentestagent mcp_server --type sse listens on 0.0.0.0:8080 by default (aiohttp, plain HTTP) and serves POST /mcp
//    with no authentication: whoever reaches it can call run_task and get an agent with a shell. The Defender part finds
//    the listener and who connected to it.
//  - Its headless Chromium sends exactly "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36" (truncated,
//    no real browser sends it). The CyberStrikeAI implant and an Xalgorix curl example send the same string: compare the
//    whole value, never a substring, and look at the rest of the source's traffic.

let Window = 30d;
let TruncatedUA = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36";
let McpServers = DeviceProcessEvents
    | where Timestamp > ago(Window)
    | where ProcessCommandLine matches regex @"pentestagent\s+mcp_server\s.*--type\s+sse"
    | distinct DeviceId, DeviceName, ProcessId, ProcessCommandLine;
union isfuzzy=true
    (DeviceNetworkEvents
        | where Timestamp > ago(Window)
        | where ActionType in ("ListeningConnectionCreated", "InboundConnectionAccepted")
        | join kind=inner (McpServers) on DeviceId, $left.InitiatingProcessId == $right.ProcessId
        | summarize Events=count(), Peers=make_set(RemoteIP, 20), Ports=make_set(LocalPort, 5), TimeGenerated=min(Timestamp)
            by DeviceName, ProcessCommandLine
        | project TimeGenerated, Source="DeviceNetworkEvents", Who=DeviceName, Signal="PentestAgent MCP server listening or accepting",
            Detail=strcat("ports ", tostring(Ports), " peers ", tostring(Peers), " ", substring(ProcessCommandLine, 0, 200))),
    (W3CIISLog
        | where TimeGenerated > ago(Window)
        | where replace_string(csUserAgent, "+", " ") == TruncatedUA
        | summarize Events=count(), Paths=make_set(csUriStem, 10), TimeGenerated=min(TimeGenerated) by cIP, csHost
        | project TimeGenerated, Source="W3CIISLog", Who=cIP, Signal="Truncated Chrome user agent (PentestAgent browser, shared)",
            Detail=strcat(csHost, " ", Events, " ", tostring(Paths))),
    (CommonSecurityLog
        | where TimeGenerated > ago(Window)
        | where RequestClientApplication == TruncatedUA or (RequestURL endswith "/mcp" and RequestMethod == "POST")
        | summarize Events=count(), URLs=make_set(RequestURL, 10), TimeGenerated=min(TimeGenerated) by SourceIP, RequestClientApplication
        | project TimeGenerated, Source="CommonSecurityLog", Who=SourceIP, Signal="Truncated Chrome user agent or POST /mcp",
            Detail=strcat(RequestClientApplication, " ", tostring(URLs)))
| order by TimeGenerated desc

// HackSynth running on a host you monitor
// Agentic attack detections by ThreatDefence (HackSynth). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1059.004 (Command and Scripting Interpreter: Unix Shell), T1610 (Deploy Container), T1588.002 (Obtain Capabilities: Tool)
// Example hunt for Defender XDR advanced hunting. Test before alerting.
// From the HackSynth source code (aielte-research/HackSynth at 48a41f79). HackSynth is a Python research agent with no
// web UI. It runs:
//  - python run_bench.py -b <benchmark>.json -c <config>.json [-k] (run_bench.py:132-134)
//  - a kalilinux/kali-rolling container named attackbox_kali_pico, attackbox_kali_overthewire or attackbox, created
//    through the Docker API with NET_ADMIN, SYS_PTRACE and /dev/net/tun (docker_setup.py:20-32)
//  - once per new container: apt -y install kali-linux-headless sshpass curl, then ssh-keyscan -p 2220
//    bandit.labs.overthewire.org, -p 2231 krypton..., -p 2223 leviathan... (docker_setup.py:34-40)
//  - every model command as timeout 10s /bin/bash -c <command> through docker exec (pentest_agent.py:81)
// It writes no report or log file; the clone itself (pentest_agent.py, run_bench.py, docker_setup.py) is the file signal.
// Container processes show up only where the EDR sensor sees inside containers (Defender for Endpoint on the Linux host).

let Window = 30d;
let WrapperBurst = 10;   // wrapper processes from one device in an hour before it is worth a look
union isfuzzy=true
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine has "kali-linux-headless sshpass curl"
            or ProcessCommandLine has_any ("ssh-keyscan -p 2220 bandit.labs.overthewire.org", "ssh-keyscan -p 2231 krypton.labs.overthewire.org",
                "ssh-keyscan -p 2223 leviathan.labs.overthewire.org")
        | project Timestamp, DeviceName, Signal="HackSynth attackbox setup", Detail=substring(ProcessCommandLine, 0, 300),
            Parent=strcat(InitiatingProcessFileName, " ", substring(InitiatingProcessCommandLine, 0, 150))),
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine has "run_bench.py" and ProcessCommandLine matches regex @"\s(-b|--benchmark)\s"
            and ProcessCommandLine has_any ("benchmark_solved.json", "combined_solved.json", "bandit_solved.json", "natas_solved.json",
                "configs/pico_bench/", "configs/overthewire_bench/")
        | project Timestamp, DeviceName, Signal="HackSynth launcher", Detail=substring(ProcessCommandLine, 0, 300),
            Parent=strcat(InitiatingProcessFileName, " ", substring(InitiatingProcessCommandLine, 0, 150))),
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where FileName == "timeout" and ProcessCommandLine matches regex @"^(\S*/)?timeout \d+s /bin/bash -c "
            and InitiatingProcessFileName in~ ("containerd-shim", "containerd-shim-runc-v2", "runc")
        | summarize Commands=count(), Examples=make_set(substring(ProcessCommandLine, 0, 200), 10), Timestamp=min(Timestamp)
            by DeviceName, Hour=bin(Timestamp, 1h)
        | where Commands >= WrapperBurst
        | project Timestamp, DeviceName, Signal="HackSynth command wrapper burst", Detail=strcat(Commands, " commands: ", tostring(Examples)), Parent=""),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FileName in~ ("pentest_agent.py", "run_bench.py", "docker_setup.py")
        | extend Folder=tostring(parse_path(FolderPath).DirectoryPath)
        | summarize Files=make_set(FileName, 5), Timestamp=min(Timestamp) by DeviceName, Folder
        | where array_length(Files) == 3
        | project Timestamp, DeviceName, Signal="HackSynth clone on disk", Detail=strcat(Folder, " ", tostring(Files)), Parent="")
| order by Timestamp desc

// HackSynth attackbox download in proxy logs, and its one-login-per-command SSH pattern on targets
// Agentic attack detections by ThreatDefence (HackSynth). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1588.002 (Obtain Capabilities: Tool), T1021.004 (Remote Services: SSH)
// Example hunt for Microsoft Sentinel. Test before alerting.
// From the HackSynth source code (aielte-research/HackSynth at 48a41f79). HackSynth sends no fixed user agent or marker
// to a target, so this hunt looks at two shapes instead:
//  - Proxy: the attackbox setup installs kali-linux-headless (docker_setup.py:36). The kalilinux/kali-rolling image
//    fetches packages over plain HTTP from http.kali.org, so the package name is in the URL. Any Kali build that
//    installs the same metapackage matches; look at which host did it.
//  - Target: the OverTheWire prompt makes every command start with sshpass -p <password> ssh <user>@<host> -p <port>
//    (configs/overthewire_bench/benchmarks/*.json:19), and every command is killed after 10 seconds
//    (pentest_agent.py:81). An SSH server sees one password login per step, each session over within about 10 seconds,
//    up to 20 in a row. Scripted checks and other tools look the same: this finds the shape, not HackSynth.

let Window = 14d;
let MinLogins = 5;      // short password logins from one source in an hour
let MaxSeconds = 12;    // 10 second timeout plus logging slack
let Accepted = Syslog
    | where TimeGenerated > ago(Window)
    | where ProcessName == "sshd" and SyslogMessage startswith "Accepted password for "
    | parse SyslogMessage with "Accepted password for " User " from " SrcIP " port " SrcPort " " *
    | project Start=TimeGenerated, Computer, User, SrcIP, SrcPort;
let Closed = Syslog
    | where TimeGenerated > ago(Window)
    | where ProcessName == "sshd" and SyslogMessage startswith "Disconnected from user "
    | parse SyslogMessage with "Disconnected from user " * " " SrcIP " port " SrcPort
    | project End=TimeGenerated, Computer, SrcIP, SrcPort;
union isfuzzy=true
    (CommonSecurityLog
        | where TimeGenerated > ago(Window)
        | where RequestURL has "kali-linux-headless"
        | summarize Requests=count(), URLs=make_set(substring(RequestURL, 0, 200), 5), TimeGenerated=min(TimeGenerated) by SourceIP
        | project TimeGenerated, Source="CommonSecurityLog", Signal="kali-linux-headless download (HackSynth attackbox setup)",
            Host=SourceIP, Detail=strcat(Requests, " requests: ", tostring(URLs))),
    (Accepted
        | join kind=inner Closed on Computer, SrcIP, SrcPort
        | extend Seconds=datetime_diff('second', End, Start)
        | where Seconds between (0 .. MaxSeconds)
        | summarize Logins=count(), Users=make_set(User, 10), TimeGenerated=min(Start) by Computer, SrcIP, Hour=bin(Start, 1h)
        | where Logins >= MinLogins
        | project TimeGenerated, Source="Syslog", Signal="Short SSH password logins in a row (HackSynth OverTheWire prompt shape)",
            Host=Computer, Detail=strcat(SrcIP, ": ", Logins, " logins under ", MaxSeconds, " s, users ", tostring(Users)))
| order by TimeGenerated desc

// Indicator sweep with the agentic watchlist
// Agentic attack detections by ThreatDefence (HackSynth). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1059.004 (Command and Scripting Interpreter: Unix Shell), T1588.002 (Obtain Capabilities: Tool)
// Upload feeds/sentinel-watchlist.csv as a Microsoft Sentinel watchlist with the alias AGENTIC_IOCs and the search key
// "value". HackSynth has no addresses, domains or user agents of its own: its rows are command strings, container and
// folder names and prompt text, so this sweep looks in process command lines, file paths and proxy URLs.

let IOC = _GetWatchlist('AGENTIC_IOCs') | where framework has "hacksynth" | project value=tostring(SearchKey), type, confidence, actor, source;
let Strings = toscalar(IOC | where type in ("string", "docker_image") and confidence in ("high", "medium") | summarize make_list(value));
let Paths = toscalar(IOC | where type in ("file_path", "file_name") and confidence in ("high", "medium") | summarize make_list(value));
union isfuzzy=true
    (DeviceProcessEvents | where Timestamp > ago(30d)
        | where ProcessCommandLine has_any (Strings)
        | mv-apply s=Strings to typeof(string) on (where ProcessCommandLine has s | take 1 | project Indicator=s)
        | project TimeGenerated=Timestamp, Source="DeviceProcessEvents", Indicator, Detail=strcat(DeviceName, " ", substring(ProcessCommandLine, 0, 200))),
    (DeviceFileEvents | where Timestamp > ago(30d)
        | where FolderPath has_any (Paths)
        | mv-apply p=Paths to typeof(string) on (where FolderPath has p | take 1 | project Indicator=p)
        | project TimeGenerated=Timestamp, Source="DeviceFileEvents", Indicator, Detail=strcat(DeviceName, " ", FolderPath)),
    (CommonSecurityLog | where TimeGenerated > ago(90d)
        | where RequestURL has_any (Strings)
        | mv-apply s=Strings to typeof(string) on (where RequestURL has s | take 1 | project Indicator=s)
        | project TimeGenerated, Source="CommonSecurityLog", Indicator, Detail=strcat(SourceIP, " ", RequestURL))
| join kind=leftouter (IOC) on $left.Indicator == $right.value
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Details=make_set(Detail, 10)
    by Source, Indicator, actor, confidence
| order by LastSeen desc

// Hermes Agent set up for attack on a host you monitor: yolo mode, jailbreak skill, red-team persona, attack tools
// Agentic attack detections by ThreatDefence (Hermes Agent). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1699 (Direct Prompt Injection), T1059 (Command and Scripting Interpreter)
// Example hunt for Defender XDR advanced hunting. Test and baseline before alerting.
// Hermes Agent (NousResearch/hermes-agent) is a legitimate general-purpose agent, so its presence is not the finding.
// Attackers change it in ways ordinary users rarely do:
//  - Approvals off: hermes --yolo, HERMES_YOLO_MODE, or approvals.mode: off in ~/.hermes/config.yaml. Hunt.io's operator
//    ran it unattended this way inside Thailand's Ministry of Finance network (LinPEAS, SUID search, web root search).
//  - The bundled godmode jailbreak skill (optional-skills/security/godmode): ~/.hermes/skills/security/godmode/scripts/
//    load_godmode.py, auto_jailbreak.py, parseltongue.py, and ~/.hermes/prefill.json with prefill_messages_file set and
//    agent.system_prompt replaced in config.yaml. Unit 42's knaithe/KnYuan actor ran Hermes on DeepSeek with godmode.
//  - A replaced SOUL.md persona: "SOUL - Red Team Operator" (Gambit) or the GH0ST persona Carbonato writes to
//    /root/.hermes/SOUL.md, with loot kept in /root/.hermes/loot/. File events show the write; YARA reads the text.
//  - Attack tools started under Hermes, and python3 -m http.server started from the agent's home folder (Unit 42).

let Window = 30d;
let AttackTools = dynamic(["nmap", "masscan", "naabu", "nuclei", "sqlmap", "ffuf", "gobuster", "hydra", "netexec", "nxc", "kerbrute",
    "linpeas.sh", "msfconsole", "chisel", "frp", "frpc", "socat", "ncat", "nc", "suo5"]);
let HermesProc = @"(^|[/\\\s])hermes(\.exe)?(\s|$)|hermes_cli|run_agent\.py|/\.hermes/|hermes-agent";
union isfuzzy=true
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine matches regex HermesProc
            and (ProcessCommandLine contains "--yolo" or ProcessCommandLine contains "HERMES_YOLO_MODE" or ProcessCommandLine contains "approvals.mode")
        | project Timestamp, DeviceName, Signal="Hermes with approvals off", Detail=substring(ProcessCommandLine, 0, 300), Account=AccountName),
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine matches regex @"(load_godmode|auto_jailbreak|parseltongue|godmode_race)\.py"
        | project Timestamp, DeviceName, Signal="Hermes godmode jailbreak skill ran", Detail=substring(ProcessCommandLine, 0, 300), Account=AccountName),
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where InitiatingProcessCommandLine matches regex HermesProc or InitiatingProcessParentFileName =~ "hermes"
        | where tolower(FileName) in (AttackTools) or ProcessCommandLine matches regex @"linpeas|pspy|http\.server|hive_rce|suo5"
        | summarize Tools=make_set(FileName, 20), Commands=make_set(substring(ProcessCommandLine, 0, 200), 15), Timestamp=min(Timestamp)
            by DeviceName, Account=AccountName
        | project Timestamp, DeviceName, Signal="Attack tools or a file server under Hermes", Detail=strcat(tostring(Tools), " ", tostring(Commands)), Account),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FolderPath matches regex @"[/\\]\.hermes[/\\]"
        | where (FileName =~ "SOUL.md" and ActionType in ("FileCreated", "FileModified"))
            or FileName =~ "prefill.json"
            or FolderPath matches regex @"[/\\]\.hermes[/\\](loot|skills[/\\]security[/\\]godmode)[/\\]"
        | summarize Files=make_set(FolderPath, 10), Writers=make_set(InitiatingProcessFileName, 5), Timestamp=min(Timestamp) by DeviceName, Account=InitiatingProcessAccountName
        | project Timestamp, DeviceName, Signal="Hermes persona, jailbreak or loot files", Detail=strcat(tostring(Files), " written by ", tostring(Writers)), Account)
| order by Timestamp desc

// Carbonato: a Docker worm that turns exposed Docker hosts into Telegram-controlled Hermes agents
// Agentic attack detections by ThreatDefence (Hermes Agent). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1610 (Deploy Container), T1611 (Escape to Host), T1102.002 (Web Service: Bidirectional Communication)
// Example hunt for Defender XDR advanced hunting with proxy or firewall logs. Test before alerting.
// ThreatDown (September 22, 2026). Carbonato finds Docker APIs open on 2375, then:
//  - POST /containers/create?name=netns-probe with alpine, Privileged true, Binds /:/host, PidMode and NetworkMode host,
//    and execs nsenter -t 1 -m -u -n -i sh -c ... to run on the host. Worm copies are named net-setup and pull
//    system/resolved; it rescans every /24 it can reach for 2375 every five minutes.
//  - Installs Hermes Agent unchanged, overwrites /root/.hermes/SOUL.md with the GH0ST persona (take orders on Telegram,
//    loot AI API keys first into /root/.hermes/loot/), drops a .env with CARBONATO_API_KEY.
//  - Persists through cron, systemd timers, rc.local and OpenRC with immutable files: /opt/gh0st/entry.sh,
//    /opt/gh0st/auto-persist-host.sh, /usr/local/bin/.docker-network-monitor, a miner at /usr/sbin/systemd-logind,
//    processes named [kworker/u2:0], and a reverse SSH tunnel to AS262145 (Costa Rica).

let Window = 30d;
union isfuzzy=true
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where (ProcessCommandLine contains "nsenter" and ProcessCommandLine matches regex @"-t\s+1\s" and ProcessCommandLine contains "-m"
            and ProcessCommandLine has_any ("curl", "wget", "crontab", "chattr", "authorized_keys", "systemctl", "rc.local", ".hermes"))
            or ProcessCommandLine matches regex @"netns-probe|net-setup|system/resolved|docker-network-monitor|/opt/gh0st/|CARBONATO_API_KEY"
            or (FileName startswith "kworker" and isnotempty(FolderPath))
            or (FolderPath =~ "/usr/sbin/systemd-logind")
        | project Timestamp, DeviceName, Signal="Carbonato host escape, worm or persistence", Detail=substring(ProcessCommandLine, 0, 300),
            Parent=strcat(InitiatingProcessFileName, " ", InitiatingProcessFolderPath)),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FolderPath in~ ("/usr/local/bin/.docker-network-monitor", "/usr/sbin/systemd-logind")
            or FolderPath startswith "/opt/gh0st/" or FolderPath startswith "/root/.hermes/loot/"
            or (FolderPath =~ "/root/.hermes/SOUL.md" and InitiatingProcessFileName !in~ ("hermes", "python3", "python"))
        | project Timestamp, DeviceName, Signal="Carbonato files", Detail=FolderPath, Parent=InitiatingProcessCommandLine),
    (DeviceNetworkEvents
        | where Timestamp > ago(Window)
        | where (ActionType == "InboundConnectionAccepted" and LocalPort == 2375 and RemoteIPType == "Public")
            or (RemotePort == 2375 and ActionType in ("ConnectionSuccess", "ConnectionAttempt"))
        | summarize Peers=dcount(RemoteIP), Sample=make_set(RemoteIP, 10), Timestamp=min(Timestamp) by DeviceName, ActionType, Process=InitiatingProcessFileName
        | where ActionType == "InboundConnectionAccepted" or Peers >= 20
        | project Timestamp, DeviceName, Signal=iff(ActionType == "InboundConnectionAccepted", "Docker API reached from the internet", "Scanning for Docker APIs on 2375"),
            Detail=strcat(Peers, " peers ", tostring(Sample)), Parent=Process),
    (CommonSecurityLog
        | where TimeGenerated > ago(Window)
        | where DestinationPort == 2375 and RequestURL contains "/containers/create"
        | project Timestamp=TimeGenerated, DeviceName=DestinationIP, Signal="Docker API container create through the firewall or proxy", Detail=RequestURL, Parent=SourceIP)
| order by Timestamp desc

// Hermes consoles, Telegram control from servers, and Hermes results left on web servers
// Agentic attack detections by ThreatDefence (Hermes Agent). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1102.002 (Web Service: Bidirectional Communication), T1071.001 (Application Layer Protocol: Web Protocols)
// Example hunt for Defender XDR advanced hunting with web and proxy logs in Microsoft Sentinel. Test before alerting.
// Every Hermes abuse case so far was controlled over Telegram (Unit 42, Carbonato) or a web console (Gambit's operator
// console, the Hermes WebUI on 8878 Hunt.io found, the Hermes dashboard on 9119), and two were found because the agent's
// own output was served on the web: Hermes started python3 -m http.server 8888 in the actor's home folder (Unit 42), and
// Hunt.io's operator left a hermes-results folder of call_00_<id>.txt tool outputs in an open directory.
//  - A server whose agent process talks to api.telegram.org is being driven from Telegram.
//  - Requests for /hermes-results/ or call_00_*.txt, or for a home folder's .hermes, .bash_history or .env on your web
//    servers, mean someone's agent output is being served from your estate.

let Window = 30d;
union isfuzzy=true
    (DeviceNetworkEvents
        | where Timestamp > ago(Window)
        | where RemoteUrl has "api.telegram.org"
        | where InitiatingProcessCommandLine matches regex @"hermes|/\.hermes/|run_agent\.py|gateway"
            or InitiatingProcessFolderPath contains "/.hermes/"
        | summarize Connections=count(), Timestamp=min(Timestamp) by DeviceName, Process=substring(InitiatingProcessCommandLine, 0, 200)
        | project Timestamp, DeviceName, Signal="Hermes gateway talking to Telegram", Detail=strcat(Process, " x", Connections)),
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine matches regex @"python3?\s+-m\s+http\.server"
            and (InitiatingProcessCommandLine matches regex @"hermes|/\.hermes/" or ProcessCommandLine contains "8888")
        | project Timestamp, DeviceName, Signal="File server started by or next to Hermes", Detail=strcat(ProcessCommandLine, " in ", InitiatingProcessCommandLine)),
    (DeviceNetworkEvents
        | where Timestamp > ago(Window)
        | where ActionType == "ListeningConnectionCreated" and LocalPort in (8878, 9119)
            and InitiatingProcessCommandLine matches regex @"hermes|/\.hermes/"
        | project Timestamp, DeviceName, Signal="Hermes web UI or dashboard listening", Detail=strcat(LocalIP, ":", LocalPort, " ", InitiatingProcessCommandLine)),
    (union isfuzzy=true
        (W3CIISLog | where TimeGenerated > ago(Window) | project TimeGenerated, Src=cIP, Host=csHost, Url=csUriStem),
        (CommonSecurityLog | where TimeGenerated > ago(Window) | project TimeGenerated, Src=SourceIP, Host=DestinationHostName, Url=RequestURL)
        | where Url contains "/hermes-results/" or Url matches regex @"call_00_[A-Za-z0-9]{8,}\.txt" or Url contains "/.hermes/"
        | summarize Requests=count(), Urls=make_set(Url, 10), Timestamp=min(TimeGenerated) by Src, Host
        | project Timestamp, DeviceName=Host, Signal="Hermes output requested from a web server", Detail=strcat(Src, " ", tostring(Urls)))
| order by Timestamp desc

// HexStrike user agents and its cross-site scripting probe
// Agentic attack detections by ThreatDefence (HexStrike). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1595.002 (Active Scanning: Vulnerability Scanning), T1190 (Exploit Public-Facing Application)
// Example hunt for Microsoft Sentinel and Defender XDR advanced hunting. Test and baseline before alerting.
// From the HexStrike source code. Its HTTP testing framework sends "HexStrike-HTTP-Framework/1.0 (Advanced Security
// Testing)" (hexstrike_server.py:13287), its Selenium browser agent sends "HexStrike-BrowserAgent/1.0 (Security Testing)"
// (:13644) and, during active tests, submits <hexstrikeXSSTest123> into every text field of GET forms (:13819). The CVE
// exploit scripts it generates send "Mozilla/5.0 (Compatible Exploit)" (:7098). Elastic lists the first three as what to
// watch for. The user agents are code defaults; an operator who edits them removes them, but most run it as published.
// No address has been published for HexStrike operations, so this hunt looks for the strings instead.

let UAs = dynamic(["HexStrike-HTTP-Framework/", "HexStrike-BrowserAgent/", "Mozilla/5.0 (Compatible Exploit)"]);
union isfuzzy=true
    (SigninLogs | where UserAgent has_any (UAs)
        | project TimeGenerated, Source="SigninLogs", Src=IPAddress, Target=AppDisplayName, Detail=UserPrincipalName, UA=UserAgent),
    (CommonSecurityLog | where RequestClientApplication has_any (UAs) or RequestURL contains "hexstrikeXSSTest123"
        | project TimeGenerated, Source="CommonSecurityLog", Src=SourceIP, Target=DestinationHostName, Detail=RequestURL, UA=RequestClientApplication),
    (W3CIISLog | extend UA=replace_string(csUserAgent, "+", " ")
        | where UA has_any (UAs) or csUriQuery contains "hexstrikeXSSTest123"
        | project TimeGenerated, Source="W3CIISLog", Src=cIP, Target=csHost, Detail=strcat(csUriStem, "?", csUriQuery), UA),
    (AWSCloudTrail | where UserAgent has_any (UAs)
        | project TimeGenerated, Source="AWSCloudTrail", Src=SourceIpAddress, Target=EventSource, Detail=EventName, UA=UserAgent)
| where TimeGenerated > ago(90d)
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Samples=make_set(Detail, 10),
    UAs=make_set(UA, 5) by Source, Src, Target
| order by FirstSeen asc

// Indicator sweep with the agentic watchlist
// Agentic attack detections by ThreatDefence (HexStrike). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1595 (Active Scanning), T1071 (Application Layer Protocol)
// Upload feeds/sentinel-watchlist.csv as a Microsoft Sentinel watchlist with the alias AGENTIC_IOCs and the search key
// "value". A match needs investigation. Addresses are reassigned, so check the reported date and review_by.

let IOC = _GetWatchlist('AGENTIC_IOCs') | where framework has "hexstrike" | project value=tostring(SearchKey), type, confidence, actor, source;
let IPList = toscalar(IOC | where type == "ipv4" | summarize make_list(value));
let UAs = toscalar(IOC | where type == "user_agent" and confidence in ("high", "medium") | summarize make_list(value));
let Domains = toscalar(IOC | where type == "domain" | summarize make_list(value));
union isfuzzy=true
    (SigninLogs | where TimeGenerated > ago(90d)
        | where IPAddress in (IPList) or UserAgent has_any (UAs)
        | project TimeGenerated, Source="SigninLogs", Indicator=coalesce(IPAddress, UserAgent), Detail=UserPrincipalName),
    (CommonSecurityLog | where TimeGenerated > ago(90d)
        | where SourceIP in (IPList) or DestinationIP in (IPList) or RequestClientApplication has_any (UAs) or DestinationHostName has_any (Domains)
        | project TimeGenerated, Source="CommonSecurityLog", Detail=RequestURL,
            Indicator=case(SourceIP in (IPList), SourceIP, DestinationIP in (IPList), DestinationIP, DestinationHostName)),
    (W3CIISLog | where TimeGenerated > ago(90d)
        | where cIP in (IPList) or replace_string(csUserAgent, "+", " ") has_any (UAs)
        | project TimeGenerated, Source="W3CIISLog", Indicator=cIP, Detail=csUriStem),
    (DeviceNetworkEvents | where Timestamp > ago(30d)
        | where RemoteIP in (IPList) or RemoteUrl has_any (Domains)
        | project TimeGenerated=Timestamp, Source="DeviceNetworkEvents", Indicator=coalesce(RemoteUrl, RemoteIP), Detail=DeviceName),
    (DnsEvents | where TimeGenerated > ago(90d)
        | where Name has_any (Domains)
        | project TimeGenerated, Source="DnsEvents", Indicator=Name, Detail=ClientIP)
| join kind=leftouter (IOC) on $left.Indicator == $right.value
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Details=make_set(Detail, 10)
    by Source, Indicator, actor, confidence
| order by LastSeen desc

// HexStrike tool server on a host you monitor
// Agentic attack detections by ThreatDefence (HexStrike). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1588.002 (Obtain Capabilities: Tool), T1059 (Command and Scripting Interpreter)
// Example hunt for Defender XDR advanced hunting. Test before alerting.
// From the HexStrike source code. The server is one Python script, hexstrike_server.py, with no installer or container.
//  - It listens on 0.0.0.0:8888 whatever HEXSTRIKE_HOST says (hexstrike_server.py:98-99, 17289), with no authentication.
//    /api/command runs any shell command, so an exposed HexStrike server is remote code execution for anyone who finds it.
//  - Every tool runs through /bin/sh -c with the Python server as parent (subprocess shell=True, :5272, :6876).
//  - Each /health call runs "which <tool>" for about 100 tools in a row (:9098-9100), cached for 30 minutes.
//  - Files: hexstrike.log in its working folder, /tmp/hexstrike_files, /tmp/hexstrike_envs,
//    /tmp/hexstrike_screenshot_<epoch>.png, /tmp/mcp_msf_resource.rc and /tmp/pacu_commands.txt.
// Script and file names can be changed by renaming; the which burst and the shell parentage need a code change.

let Window = 30d;
union isfuzzy=true
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine has_any ("hexstrike_server.py", "hexstrike_mcp.py")
            or InitiatingProcessCommandLine has "hexstrike_server.py"
        | summarize Events=count(), Children=make_set(FileName, 30), Commands=make_set(substring(ProcessCommandLine, 0, 200), 15),
            Timestamp=min(Timestamp) by DeviceName, Parent=InitiatingProcessCommandLine
        | project Timestamp, DeviceName, Signal="HexStrike process or child", Detail=strcat(tostring(Children), " ", tostring(Commands)), Parent),
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where FileName in~ ("sh", "dash", "bash") and ProcessCommandLine matches regex @"^(/bin/)?(sh|dash|bash) -c which [\w.+-]+$"
            and InitiatingProcessFileName startswith "python"
        | summarize Lookups=dcount(ProcessCommandLine), Sample=make_set(ProcessCommandLine, 10), Timestamp=min(Timestamp)
            by DeviceName, Parent=InitiatingProcessCommandLine, Minute=bin(Timestamp, 1m)
        | where Lookups >= 40
        | project Timestamp, DeviceName, Signal="which burst from a Python server (HexStrike /health)", Detail=strcat(Lookups, " tools: ", tostring(Sample)), Parent),
    (DeviceNetworkEvents
        | where Timestamp > ago(Window)
        | where ActionType == "ListeningConnectionCreated" and LocalPort == 8888 and InitiatingProcessFileName startswith "python"
        // Jupyter and TensorBoard use 8888 too
        | where not(InitiatingProcessCommandLine has_any ("jupyter", "ipykernel", "notebook", "jupyterlab", "voila", "tensorboard"))
        | project Timestamp, DeviceName, Signal="Python listening on 8888", Detail=LocalIP, Parent=InitiatingProcessCommandLine),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FolderPath contains "/tmp/hexstrike_" or FileName == "hexstrike.log" or FolderPath endswith "/tmp/mcp_msf_resource.rc"
        | project Timestamp, DeviceName, Signal="HexStrike file", Detail=FolderPath, Parent=InitiatingProcessCommandLine)
| order by Timestamp desc

// AI assistants wired to a HexStrike server, and its tool API in proxy logs
// Agentic attack detections by ThreatDefence (HexStrike). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1588.007 (Obtain Capabilities: Artificial Intelligence), T1059 (Command and Scripting Interpreter), T1071.001 (Application Layer Protocol: Web Protocols)
// Example hunt for Defender XDR advanced hunting and Microsoft Sentinel. Test before alerting.
// From the HexStrike source code. HexStrike has no model of its own. An AI assistant (Claude Desktop, Claude Code,
// Cursor, VS Code or any MCP client) starts its MCP client, "python3 hexstrike_mcp.py --server http://<host>:8888"
// (hexstrike-ai-mcp.json), which forwards each tool call to the server as POST /api/tools/<tool> or /api/command with
// python-requests, after retrying GET /health. So a workstation running an assistant with HexStrike attached shows the
// client process under the assistant, and its traffic shows calls to a remote :8888 tool API.
// The MCP client can be renamed; the /api/tools/ and /api/command paths and the /health retry need a code change.

let Window = 30d;
union isfuzzy=true
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine has "hexstrike_mcp.py" or (ProcessCommandLine has "--server" and ProcessCommandLine contains ":8888" and ProcessCommandLine has_any ("hexstrike", "mcp"))
        | project Timestamp, DeviceName, Account=AccountName, Signal="HexStrike MCP client",
            Detail=substring(ProcessCommandLine, 0, 300), Parent=InitiatingProcessFileName),
    (CommonSecurityLog
        | where TimeGenerated > ago(Window)
        | where (RequestURL contains "/api/tools/" or RequestURL contains "/api/command")
            and (DestinationPort == 8888 or RequestURL contains ":8888/")
        | summarize Requests=count(), Tools=make_set(extract(@"/api/tools/([\w-]+)", 1, RequestURL), 20), Timestamp=min(TimeGenerated)
            by SourceIP, SourceUserName, DestinationIP, DestinationHostName
        | project Timestamp, DeviceName=SourceIP, Account=SourceUserName, Signal="HexStrike tool API through the proxy",
            Detail=strcat(DestinationHostName, " ", DestinationIP, " tools: ", tostring(Tools), " x", Requests), Parent="")
| order by Timestamp desc

// NeuroSploit on a host you monitor
// Agentic attack detections by ThreatDefence (NeuroSploit). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1588.002 (Obtain Capabilities: Tool), T1059.004 (Command and Scripting Interpreter: Unix Shell)
// Example hunt for Defender XDR advanced hunting. Test and baseline before alerting.
// NeuroSploit (JoasASantos/NeuroSploit, reviewed at 54d8e860) is a Rust harness with a Node.js web console on port 4173
// that has no login. No report of its use in a real intrusion was found on November 26, 2026, so this hunt looks for
// the software itself, from its source code:
//  - The binary neurosploit (neurosploit.exe), its C2 daemon "neurosploit c2 daemon --port 0 --dir <...>/.neurosploit/c2",
//    the containers neurosploit-kali and neurosploit-neo4j, and node running /tmp/ns_browser_prefetch.js.
//  - Coding agent CLIs started by neurosploit with approvals off: claude -p ... --dangerously-skip-permissions,
//    codex exec ... --dangerously-bypass-approvals-and-sandbox.
//  - Files: <cwd>/.neurosploit/ (keys.json, vault/, c2/), runs/ns-<unix time>-<target>/.
//  - The web console listening on 4173 (node), and the out-of-band listener on 8080 (neurosploit).
// What each signal relies on in the source is in ../../source-code-signals.md.

let Window = 30d;
let Markers = dynamic(["c2 daemon --port 0 --dir", "neurosploit-kali", "neurosploit-neo4j", "ns_browser_prefetch.js", "neurosploit-mcp"]);
let NsProcesses = DeviceProcessEvents
    | where Timestamp > ago(Window)
    | where FileName in~ ("neurosploit", "neurosploit.exe") or ProcessCommandLine has_any (Markers)
        or (InitiatingProcessFileName in~ ("neurosploit", "neurosploit.exe")
            and ProcessCommandLine has_any ("--dangerously-skip-permissions", "--dangerously-bypass-approvals-and-sandbox"));
let NsDevices = NsProcesses | distinct DeviceName;
union isfuzzy=true
    (NsProcesses
        | summarize Commands=make_set(substring(ProcessCommandLine, 0, 200), 10), Timestamp=min(Timestamp) by DeviceName
        | project Timestamp, DeviceName, Signal="NeuroSploit binary, C2 daemon, container or agent CLI child", Detail=tostring(Commands)),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FolderPath has_any ("/.neurosploit/c2/", @"\.neurosploit\c2\", "/.neurosploit/vault/", @"\.neurosploit\vault\")
            or FolderPath endswith "/.neurosploit/keys.json" or FolderPath endswith @"\.neurosploit\keys.json"
            or FolderPath =~ "/tmp/ns_browser_prefetch.js" or FolderPath matches regex @"[/\\]runs[/\\]ns-\d{10}-"
        | summarize Files=make_set(FolderPath, 10), Timestamp=min(Timestamp) by DeviceName
        | project Timestamp, DeviceName, Signal="NeuroSploit project store, vault, C2 state or run folder", Detail=tostring(Files)),
    (DeviceNetworkEvents
        | where Timestamp > ago(Window)
        | where ActionType == "ListeningConnectionCreated"
        | where (LocalPort == 4173 and InitiatingProcessFileName in~ ("node", "node.exe") and InitiatingProcessCommandLine has "server.js")
            or (InitiatingProcessFileName in~ ("neurosploit", "neurosploit.exe"))
        | summarize Ports=make_set(LocalPort, 10), Timestamp=min(Timestamp) by DeviceName, InitiatingProcessFileName
        | project Timestamp, DeviceName, Signal="NeuroSploit console (4173) or listener opened by neurosploit", Detail=strcat(InitiatingProcessFileName, " ", tostring(Ports)))
| extend KnownNeuroSploitDevice = DeviceName in (NsDevices)
| order by Timestamp desc

// NeuroSploit testing you: its user agent, probe path, canaries and out-of-band callbacks in web, proxy and DNS logs
// Agentic attack detections by ThreatDefence (NeuroSploit). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1595.002 (Active Scanning: Vulnerability Scanning), T1190 (Exploit Public-Facing Application)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the NeuroSploit source code (JoasASantos/NeuroSploit, reviewed at 54d8e860):
//  - The harness's own requests carry User-Agent NeuroSploit/<version> and the header X-NeuroSploit-Scan (headers are
//    rarely logged; the user agent is). Its first probe requests /nrsplt_baseline_404_check_9x7.
//  - Canaries are NEUROSPLOIT<kind><12 hex> with the sigil in upper case: /NEUROSPLOITsub<hex> soft-404 checks and
//    NEUROSPLOITnsxss<hex> in XSS payloads. Open redirect tests use neurosploit.example; SSRF tests without an
//    out-of-band domain use http://oob.invalid/. Sign-ups use nrsplt_<rand>@example.test (an example in the prompt).
//  - Out-of-band payloads make your servers look up or fetch <token>.<operator domain>, where the token starts with
//    neurosploit. neurosploitai.github.io is the project's documentation site and is left out.
// The browser fallback user agent (Chrome 125 on Windows) is a real browser string, so it is not used here.

let Window = 30d;
let PathMarkers = dynamic(["nrsplt_baseline_404_check_9x7", "neurosploit.example", "oob.invalid", "nrsplt_"]);
let IsOob = (h:string) { tolower(h) startswith "neurosploit" and not(tolower(h) startswith "neurosploitai.") };
union isfuzzy=true
    (W3CIISLog | where TimeGenerated > ago(Window)
        | extend UA=replace_string(csUserAgent, "+", " ")
        | where UA startswith "NeuroSploit/" or UA has "NeuroSploit-WebShell/" or csUriStem has_any (PathMarkers) or csUriQuery has_any (PathMarkers)
            or csUriStem has_cs "NEUROSPLOIT" or csUriQuery has_cs "NEUROSPLOIT"
        | project TimeGenerated, Source="W3CIISLog", Src=cIP, Target=csHost, Detail=strcat(csMethod, " ", csUriStem, "?", csUriQuery), UA),
    (CommonSecurityLog | where TimeGenerated > ago(Window)
        | where RequestClientApplication startswith "NeuroSploit" or RequestClientApplication has "NeuroSploit-WebShell/"
            or RequestURL has_any (PathMarkers) or RequestURL has_cs "NEUROSPLOIT" or IsOob(DestinationHostName)
        | project TimeGenerated, Source="CommonSecurityLog", Src=SourceIP, Target=DestinationHostName, Detail=RequestURL, UA=RequestClientApplication),
    (DnsEvents | where TimeGenerated > ago(Window)
        | where IsOob(Name)
        | project TimeGenerated, Source="DnsEvents (out-of-band lookup)", Src=ClientIP, Target=Name, Detail=Name, UA=""),
    (DeviceNetworkEvents | where Timestamp > ago(Window)
        | where IsOob(RemoteUrl)
        | project TimeGenerated=Timestamp, Source="DeviceNetworkEvents (out-of-band callback)", Src=DeviceName, Target=RemoteUrl,
            Detail=InitiatingProcessCommandLine, UA="")
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Samples=make_set(Detail, 10),
    UAs=make_set(UA, 5) by Source, Src, Target
| order by FirstSeen asc

// NeuroSploit C2 beacons, NSUpdate persistence and web shells on hosts it compromised
// Agentic attack detections by ThreatDefence (NeuroSploit). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1071.001 (Application Layer Protocol: Web Protocols), T1053.005 (Scheduled Task/Job: Scheduled Task), T1547.001 (Boot or Logon Autostart Execution: Registry Run Keys / Startup Folder), T1053.003 (Scheduled Task/Job: Cron), T1543.002 (Create or Modify System Process: Systemd Service), T1505.003 (Server Software Component: Web Shell)
// Example hunt for Defender XDR advanced hunting. Test and baseline before alerting.
// From the NeuroSploit C2 code (harness/src/c2/templates.rs at 54d8e860), which is off until the operator enables it:
//  - Beacons POST to http://<callback>:<port>/api/beacon (bash adds ?format=sh) with the header X-Implant-Token.
//    CyberStrikeAI's implant uses the same header name, with /check_in and /tasks instead of /api/beacon.
//  - Windows persistence: schtasks /Create /F /SC ONLOGON /TN "NSUpdate" or a Run value NSUpdate, both starting
//    powershell -NoProfile -ExecutionPolicy Bypass -EncodedCommand <beacon>.
//  - Linux persistence: @reboot crontab entry, "# NSUpdate" in ~/.bashrc, or ~/.config/systemd/user/nsupdate.service.
//  - Web shells start with the comment "NeuroSploit WebShell"; generated names are webshell-<ms>.<php|aspx|asp|jsp>;
//    the manager sends User-Agent "Mozilla/5.0 (compatible; NeuroSploit-WebShell/1.0)".

let Window = 30d;
union isfuzzy=true
    (DeviceProcessEvents | where Timestamp > ago(Window)
        | where (ProcessCommandLine has "X-Implant-Token" and ProcessCommandLine has "/api/beacon")
            or (ProcessCommandLine has "schtasks" and ProcessCommandLine has "NSUpdate")
            or (ProcessCommandLine has @"CurrentVersion\Run" and ProcessCommandLine has "NSUpdate")
            or ProcessCommandLine has "nsupdate.service" or ProcessCommandLine has "# NSUpdate"
        | project TimeGenerated=Timestamp, DeviceName, Signal="NeuroSploit beacon or persistence command", Detail=substring(ProcessCommandLine, 0, 300)),
    (DeviceRegistryEvents | where Timestamp > ago(Window)
        | where RegistryKey endswith @"\CurrentVersion\Run" and RegistryValueName =~ "NSUpdate"
        | project TimeGenerated=Timestamp, DeviceName, Signal="Run value NSUpdate", Detail=RegistryValueData),
    (DeviceFileEvents | where Timestamp > ago(Window)
        | where FileName =~ "nsupdate.service" or FileName matches regex @"^webshell-\d{13}\.(php|aspx|asp|jsp)$"
            or FileName matches regex @"^beacon-\d{13}\.(sh|py|ps1|php)$"
        | project TimeGenerated=Timestamp, DeviceName, Signal="NeuroSploit unit, web shell or beacon file name", Detail=FolderPath),
    (W3CIISLog | where TimeGenerated > ago(Window)
        | where replace_string(csUserAgent, "+", " ") has "NeuroSploit-WebShell/" or csUriQuery has "pass=ns_pass"
        | project TimeGenerated, DeviceName=csHost, Signal="Web shell manager request", Detail=strcat(csMethod, " ", csUriStem, " from ", cIP))
| order by TimeGenerated desc

// NyxStrike server, MCP client or local model on a host you monitor
// Agentic attack detections by ThreatDefence (NyxStrike). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1588.002 (Obtain Capabilities: Tool), T1059.004 (Command and Scripting Interpreter: Unix Shell)
// Example hunt for Defender XDR advanced hunting. Test and baseline before alerting.
// From the NyxStrike source code (CommonHuman-Lab/nyxstrike, reviewed at 3ac7449, version 1.9.0):
//  - The server is nyxstrike_server.py, run from the virtual environment nyxstrike-env by nyxstrike.sh, on
//    127.0.0.1:8888 by default (NYXSTRIKE_HOST, NYXSTRIKE_PORT). Since 1.8.0 it refuses any other address unless
//    NYXSTRIKE_API_TOKEN is set. The Docker image runs it from /opt/nyxstrike in a container named nyxstrike.
//  - Every tool runs through /bin/sh -c with the Python server as parent, prefixed with "nice -n 10" when CPU is above 85%.
//  - When its tool list is older than an hour, /health or /web-dashboard runs "which <tool>" (no shell) for about 150
//    tools, 20 at a time.
//  - At start-up it fetches raw.githubusercontent.com/CommonHuman-Lab/nyxstrike/master/config.py (version check).
//  - With -ai or -ai-small, nyxstrike.sh pulls huihui_ai/gemma-4-abliterated:e4b or huihui_ai/qwen3.5-abliterated:2B into
//    Ollama and creates the model nyxstrike-ai.
//  - Files: .nyxstrike_data/ (nyxstrike.db, sessions/, run_history.json, config/cred_key, config/config_local.json),
//    nyxstrike.log, /tmp/security_screenshot_<epoch>.png.
// HexStrike hunt 03 looks for "sh -c which"; NyxStrike runs which directly, so use this hunt for NyxStrike.

let Window = 30d;
let Names = dynamic(["nyxstrike_server.py", "nyxstrike_mcp.py", "nyxstrike.sh", "/nyxstrike-env/"]);
union isfuzzy=true
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine has_any (Names) or InitiatingProcessCommandLine has "nyxstrike_server.py"
        | summarize Events=count(), Children=make_set(FileName, 30), Commands=make_set(substring(ProcessCommandLine, 0, 200), 15),
            Timestamp=min(Timestamp) by DeviceName, Parent=InitiatingProcessCommandLine
        | project Timestamp, DeviceName, Signal="NyxStrike process or a tool it started", Detail=strcat(tostring(Children), " ", tostring(Commands)), Parent),
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where FileName == "which" and InitiatingProcessFileName startswith "python"
        | summarize Lookups=dcount(ProcessCommandLine), Sample=make_set(ProcessCommandLine, 10), Timestamp=min(Timestamp)
            by DeviceName, Parent=InitiatingProcessCommandLine, Minute=bin(Timestamp, 1m)
        | where Lookups >= 40
        | project Timestamp, DeviceName, Signal="which burst from a Python server (NyxStrike tool availability check)", Detail=strcat(Lookups, " tools: ", tostring(Sample)), Parent),
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine has "ollama" and ProcessCommandLine has_any ("nyxstrike-ai", "gemma-4-abliterated", "qwen3.5-abliterated")
        | project Timestamp, DeviceName, Signal="Ollama model used by NyxStrike", Detail=substring(ProcessCommandLine, 0, 300), Parent=InitiatingProcessCommandLine),
    (DeviceNetworkEvents
        | where Timestamp > ago(Window)
        | where ActionType == "ListeningConnectionCreated" and LocalPort == 8888 and InitiatingProcessCommandLine has "nyxstrike_server.py"
        | project Timestamp, DeviceName, Signal="NyxStrike server listening", Detail=LocalIP, Parent=InitiatingProcessCommandLine),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FolderPath has "/.nyxstrike_data/" or FileName == "nyxstrike.log" or FolderPath startswith "/tmp/security_screenshot_"
        | summarize Files=make_set(FolderPath, 10), Timestamp=min(Timestamp) by DeviceName, Parent=InitiatingProcessCommandLine
        | project Timestamp, DeviceName, Signal="NyxStrike data, log or screenshot", Detail=tostring(Files), Parent)
| order by Timestamp desc

// Indicator sweep with the agentic watchlist
// Agentic attack detections by ThreatDefence (NyxStrike). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1595 (Active Scanning), T1071 (Application Layer Protocol)
// Upload feeds/sentinel-watchlist.csv as a Microsoft Sentinel watchlist with the alias AGENTIC_IOCs and the search key
// "value". A match needs investigation. Addresses are reassigned, so check the reported date and review_by.
// No NyxStrike infrastructure has been published, so these rows are fingerprints of the software: its user agents,
// strings and file names. Rows shared with HexStrike carry both framework names.

let IOC = _GetWatchlist('AGENTIC_IOCs') | where framework has "nyxstrike" | project value=tostring(SearchKey), type, confidence, actor, source;
let IPList = toscalar(IOC | where type in ("ipv4", "ipv6") | summarize make_list(value));
let UAs = toscalar(IOC | where type == "user_agent" and confidence in ("high", "medium") | summarize make_list(value));
let Domains = toscalar(IOC | where type == "domain" | summarize make_list(value));
let MD5s = toscalar(IOC | where type == "md5" | summarize make_list(value));
union isfuzzy=true
    (SigninLogs | where TimeGenerated > ago(90d)
        | where IPAddress in (IPList) or UserAgent has_any (UAs)
        | project TimeGenerated, Source="SigninLogs", Indicator=coalesce(IPAddress, UserAgent), Detail=UserPrincipalName),
    (AWSCloudTrail | where TimeGenerated > ago(90d)
        | where SourceIpAddress in (IPList) or UserAgent has_any (UAs)
        | project TimeGenerated, Source="AWSCloudTrail", Indicator=SourceIpAddress, Detail=strcat(EventName, " ", UserIdentityArn)),
    (CommonSecurityLog | where TimeGenerated > ago(90d)
        | where SourceIP in (IPList) or DestinationIP in (IPList) or RequestClientApplication has_any (UAs) or DestinationHostName has_any (Domains)
        | project TimeGenerated, Source="CommonSecurityLog", Detail=RequestURL,
            Indicator=case(SourceIP in (IPList), SourceIP, DestinationIP in (IPList), DestinationIP, RequestClientApplication has_any (UAs), RequestClientApplication, DestinationHostName)),
    (W3CIISLog | where TimeGenerated > ago(90d)
        | where cIP in (IPList) or replace_string(csUserAgent, "+", " ") has_any (UAs)
        | project TimeGenerated, Source="W3CIISLog", Indicator=iff(cIP in (IPList), cIP, replace_string(csUserAgent, "+", " ")), Detail=csUriStem),
    (DeviceNetworkEvents | where Timestamp > ago(30d)
        | where RemoteIP in (IPList) or RemoteUrl has_any (Domains)
        | project TimeGenerated=Timestamp, Source="DeviceNetworkEvents", Indicator=iff(RemoteIP in (IPList), RemoteIP, RemoteUrl),
            Detail=strcat(DeviceName, " ", InitiatingProcessFileName)),
    (DeviceFileEvents | where Timestamp > ago(30d)
        | where MD5 in~ (MD5s)
        | project TimeGenerated=Timestamp, Source="DeviceFileEvents", Indicator=tolower(MD5), Detail=strcat(DeviceName, " ", FolderPath)),
    (DnsEvents | where TimeGenerated > ago(90d)
        | where Name has_any (Domains)
        | project TimeGenerated, Source="DnsEvents", Indicator=Name, Detail=ClientIP)
| join kind=leftouter (IOC) on $left.Indicator == $right.value
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Details=make_set(Detail, 10)
    by Source, Indicator, actor, confidence
| order by LastSeen desc

// NyxStrike testing you, or a NyxStrike server used through your proxy: user agents, probe markers and server paths
// Agentic attack detections by ThreatDefence (NyxStrike). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1595.002 (Active Scanning: Vulnerability Scanning), T1190 (Exploit Public-Facing Application), T1071.001 (Application Layer Protocol: Web Protocols)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the NyxStrike source code (CommonHuman-Lab/nyxstrike, reviewed at 3ac7449):
//  - User agents hard-coded in NyxStrike: NyxStrike/1.0 (decision engine, a HEAD then GET of the target),
//    Security-HTTP-Framework/1.0 (Advanced Security Testing) and Security-BrowserAgent/1.0 (Security Testing).
//    HexStrike's were HexStrike-HTTP-Framework/ and HexStrike-BrowserAgent/, so the HexStrike hunts miss these.
//  - commonhuman-core/openapi-discover: its OpenAPI discovery requests /openapi.json, /swagger.json, /api-docs, /docs ...
//  - <xssTest123>: the reflection probe its browser agent puts into GET forms, sent with python-requests.
//  - StingXSS_<6> and BreachSQL_<6>: markers of the StingXSS and BreachSQL scanners NyxStrike installs. They also run on
//    their own, so a hit on those alone means the scanner, not necessarily NyxStrike.
//  - From the operator side: the version check to raw.githubusercontent.com/CommonHuman-Lab/nyxstrike/ and requests to
//    a NyxStrike server's /web-dashboard and /api/intelligence/ai-*-session.
// Mozilla/5.0 (Compatible Exploit) in NyxStrike's generated exploits is shared with HexStrike and is in its hunts.

let UAs = dynamic(["NyxStrike/", "Security-HTTP-Framework/", "Security-BrowserAgent/", "commonhuman-core/openapi-discover"]);
let Markers = @"xssTest123|StingXSS_|BreachSQL_|stingxss_redir_marker|stingxss_jsonp_probe|stingxss-crlf-detected";
let ServerPaths = @"raw\.githubusercontent\.com/CommonHuman-Lab/nyxstrike/|:8888/web-dashboard|:8888/api/intelligence/ai-(recon|profiling|vuln|osint|followup)-session";
union isfuzzy=true
    (W3CIISLog | where TimeGenerated > ago(90d)
        | extend UA=replace_string(csUserAgent, "+", " ")
        | where UA has_any (UAs) or csUriQuery matches regex Markers or csUriStem matches regex Markers
        | project TimeGenerated, Source="W3CIISLog", Src=cIP, Target=csHost, Detail=strcat(csUriStem, "?", csUriQuery), UA),
    (CommonSecurityLog | where TimeGenerated > ago(90d)
        | where RequestClientApplication has_any (UAs) or RequestURL matches regex Markers or RequestURL matches regex ServerPaths
        | project TimeGenerated, Source="CommonSecurityLog", Src=SourceIP, Target=DestinationHostName, Detail=RequestURL, UA=RequestClientApplication),
    (SigninLogs | where TimeGenerated > ago(90d)
        | where UserAgent has_any (UAs)
        | project TimeGenerated, Source="SigninLogs", Src=IPAddress, Target=AppDisplayName, Detail=UserPrincipalName, UA=UserAgent),
    (AWSCloudTrail | where TimeGenerated > ago(90d)
        | where UserAgent has_any (UAs)
        | project TimeGenerated, Source="AWSCloudTrail", Src=SourceIpAddress, Target=EventSource, Detail=EventName, UA=UserAgent)
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Samples=make_set(Detail, 10),
    UAs=make_set(UA, 5) by Source, Src, Target
| order by FirstSeen asc

