// PentAGI server and worker containers on a host you monitor
// Agentic attack detections by ThreatDefence (PentAGI). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1588.002 (Obtain Capabilities: Tool), T1059.004 (Command and Scripting Interpreter: Unix Shell)
// Example hunt for Defender XDR advanced hunting. Test before alerting.
// From the PentAGI source code. Someone running PentAGI on your own hosts is an authorized tester, an insider or an
// intruder staging from your network.
//  - Every agent command runs in the flow's Kali container through a wrapper that ignores hangups and marks the process by
//    raising its oom_score_adj: sh -c 'trap "" HUP; read -r adj 2>/dev/null </proc/self/oom_score_adj && echo $((adj + 1))
//    2>/dev/null >/proc/self/oom_score_adj; exec sh -c "$0"' <command> (backend/pkg/docker/flow_commands.go:9-19).
//  - Worker containers are named pentagi-terminal-<flow id>, use /work as working folder and a pentagi-terminal-<id>-data
//    volume, and run vxcontrol/kali-linux by default (backend/pkg/tools/terminal.go:27, backend/pkg/docker/client.go:33-34,
//    backend/pkg/config/config.go:67).
//  - Each flow publishes two ports from 28000 on every interface (backend/pkg/docker/client.go:35-44, 121-131).
//  - The server runs as root with the Docker socket mounted, listens on 8443, and calls update.pentagi.com every three hours
//    (docker-compose.yml, backend/pkg/server/update/update.go).
// The wrapper, container prefix and update check need a code change to remove; ports and images are configuration.

let Window = 30d;
let PortsBase = 28000;
union isfuzzy=true
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where (ProcessCommandLine contains "/proc/self/oom_score_adj" and ProcessCommandLine contains "exec sh -c")
            or ProcessCommandLine has_any ("pentagi-terminal-", "vxcontrol/kali-linux", "vxcontrol/pentagi", "vxcontrol/scraper")
        | project Timestamp, DeviceName, Signal="process", Detail=substring(ProcessCommandLine, 0, 300),
            Actor=InitiatingProcessFileName, Account=AccountName),
    (DeviceNetworkEvents
        | where Timestamp > ago(Window)
        | where ActionType == "ListeningConnectionCreated" and LocalPort between (PortsBase .. PortsBase + 1999)
            and InitiatingProcessFileName in~ ("docker-proxy", "dockerd", "containerd")
        | summarize Ports=make_set(LocalPort, 20), Listeners=dcount(LocalPort), Timestamp=min(Timestamp) by DeviceName
        | where Listeners >= 2
        | project Timestamp, DeviceName, Signal="worker ports published in 28000-29999", Detail=tostring(Ports),
            Actor="docker", Account=""),
    (DeviceNetworkEvents
        | where Timestamp > ago(Window)
        | where RemoteUrl has_any ("update.pentagi.com", "support.pentagi.com")
        | summarize Calls=count(), Timestamp=min(Timestamp), Actor=take_any(InitiatingProcessFileName) by DeviceName, RemoteUrl
        | project Timestamp, DeviceName, Signal="PentAGI update check", Detail=strcat(RemoteUrl, " x", Calls), Actor, Account="")
| order by Timestamp desc

// Every page fetched twice at once: PentAGI's browser tool reading your application
// Agentic attack detections by ThreatDefence (PentAGI). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1594 (Search Victim-Owned Websites)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the PentAGI source code. The browser tool hands each page to the scraper service twice in parallel: once for the
// content (/html, /markdown or /links) and once for a full-page screenshot (/screenshot?fullPage=true), started together
// in two goroutines (backend/pkg/tools/browser.go). The scraper is a headless browser, so your logs see the same URL
// requested twice within a second or two from the same address, page after page, often followed by the assets a
// full-page render loads. Elastic noted the same pattern. Browsers and crawlers rarely request one HTML page twice at
// the same moment.
// Exclude your uptime monitors and link-preview services, which can produce the same pairs.

let Window = 7d;
let Static = @"(?i)\.(js|css|png|jpe?g|gif|svg|ico|woff2?|ttf|map|webp)(\?|$)";
union isfuzzy=true
    (CommonSecurityLog | where TimeGenerated > ago(Window) and RequestMethod == "GET" and isnotempty(RequestURL)
        | project TimeGenerated, Src=SourceIP, Host=DestinationHostName, Url=RequestURL, UA=RequestClientApplication),
    (W3CIISLog | where TimeGenerated > ago(Window) and csMethod == "GET"
        | project TimeGenerated, Src=cIP, Host=csHost, Url=strcat(csUriStem, "?", csUriQuery), UA=csUserAgent)
| where not(Url matches regex Static)
| summarize Hits=count(), First=min(TimeGenerated), Last=max(TimeGenerated), UAs=make_set(UA, 3) by Src, Host, Url, Second2=bin(TimeGenerated, 2s)
// The same page twice inside two seconds
| where Hits == 2
| summarize Pairs=count(), Pages=dcount(Url), SampleURLs=make_set(Url, 10), UAs=make_set(UAs, 5),
    FirstSeen=min(First), LastSeen=max(Last) by Src, Host, Hour=bin(First, 1h)
// Several different pages read the same way within an hour
| where Pages >= 5
| order by Pages desc

// PentAGI console and update traffic in your outbound proxy logs
// Agentic attack detections by ThreatDefence (PentAGI). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1071.001 (Application Layer Protocol: Web Protocols)
// Example hunt for Microsoft Sentinel. Needs a proxy that records full URLs (TLS inspection). Test before alerting.
// From the PentAGI source code. People on your network driving a remote PentAGI console, or a PentAGI host behind your
// proxy, leave requests a proxy can name:
//  - The console API under /api/v1: /api/v1/info answers without a session and reports the configured model providers,
//    /api/v1/graphql carries the flows, /api/v1/graphql/playground and the Swagger UI ("PentAGI Swagger API") exist in
//    developer builds (backend/pkg/server/router.go:72, 297-301, 522). Default port 8443, HTTPS with a PentAGI CA certificate.
//  - The update check: POST https://update.pentagi.com/api/v1/proxy/updates/pentagi/check every 3 hours, with a
//    proof-of-work ticket fetched first (backend/pkg/server/update/update.go:52).
// Ports and the update interval are configuration. The API paths and the update endpoint need a code change.

let Window = 30d;
CommonSecurityLog
| where TimeGenerated > ago(Window) and isnotempty(RequestURL)
| extend Signal = case(
    RequestURL contains "update.pentagi.com" or DestinationHostName =~ "update.pentagi.com", "PentAGI update check",
    RequestURL contains "/api/v1/proxy/updates/pentagi/check", "PentAGI update check through a custom host",
    RequestURL contains "/api/v1/graphql/playground", "PentAGI GraphQL playground",
    RequestURL contains "/api/v1/info" and (DestinationPort in (8443, 8666, 8765) or RequestURL contains ":8443/"), "PentAGI console info endpoint",
    RequestURL contains "/api/v1/graphql" and (DestinationPort in (8443, 8666, 8765) or RequestURL contains ":8443/"), "PentAGI console GraphQL",
    "")
| where isnotempty(Signal)
| summarize Requests=count(), Signals=make_set(Signal), Destinations=make_set(DestinationHostName, 10),
    SampleURLs=make_set(RequestURL, 10), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated) by SourceIP, SourceUserName
| order by array_length(Signals) desc, Requests desc

// PentestAgent (nbshenxm paper code) running on a host you monitor
// Agentic attack detections by ThreatDefence (PentestAgent, nbshenxm/pentest-agent). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1059.006 (Command and Scripting Interpreter: Python), T1588.005 (Obtain Capabilities: Exploits)
// Example hunt for Defender XDR advanced hunting. Test before alerting.
// From the source code (nbshenxm/pentest-agent at 97ac5be7), the research code of arXiv 2411.05185. Not the
// GH05TCREW/pentestagent tool, which has its own folder.
//  - The operator runs python agents/recon_agent.py, agents/planning_agent.py and agents/execution_agent.py.
//    The recon and execution agents run every command the model returns with /bin/sh -c (nmap, curl, the exploit).
//  - The planning agent runs cvemap -q <product> -l 50 -offset <n> -j, echo CVE-<id> | cvemap -json > .../info/cvemap.json
//    and searchsploit CVE-<id> -j > resources/CVE-<id>/exploitdb.json, and clones public exploit repositories.
//  - Files: exeuction_agent.log (misspelled), recon_memory/<topic>.json, <keyword>/CVEMAP/cvemap.json, plan.json,
//    <CVE>/Trend_Score.json and conf_score_from_code_<repo>.json.

let Window = 30d;
union isfuzzy=true
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine has_any ("agents/recon_agent.py", "agents/planning_agent.py", "agents/execution_agent.py")
            or (ProcessCommandLine has "cvemap" and ProcessCommandLine has " -offset " and ProcessCommandLine has " -l 50 ")
            or (ProcessCommandLine has "| cvemap -json > " and ProcessCommandLine has "/info/cvemap.json")
            or (ProcessCommandLine has "searchsploit " and ProcessCommandLine has " -j > resources/")
        | project Timestamp, DeviceName, Signal="PentestAgent script, cvemap or searchsploit", Detail=substring(ProcessCommandLine, 0, 300),
            Parent=strcat(InitiatingProcessFileName, " ", substring(InitiatingProcessCommandLine, 0, 150))),
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where InitiatingProcessCommandLine has_any ("agents/recon_agent.py", "agents/execution_agent.py")
            and FileName in~ ("sh", "dash", "bash")
        | project Timestamp, DeviceName, Signal="Command run by a PentestAgent agent", Detail=substring(ProcessCommandLine, 0, 300),
            Parent=substring(InitiatingProcessCommandLine, 0, 150)),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FileName == "exeuction_agent.log" or FileName == "Trend_Score.json"
            or FolderPath has "/CVEMAP/" or FileName startswith "conf_score_from_code_" or FileName startswith "otpt_from_code_"
            or FolderPath has "/recon_memory/"
        | summarize Files=make_set(FileName, 10), Timestamp=min(Timestamp) by DeviceName, FolderPath
        | project Timestamp, DeviceName, Signal="PentestAgent log, memory or planning file", Detail=strcat(FolderPath, " ", tostring(Files)), Parent="")
| order by Timestamp desc

// PentestAgent (nbshenxm paper code) testing you: its default proof command in web and proxy logs
// Agentic attack detections by ThreatDefence (PentestAgent, nbshenxm/pentest-agent). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1190 (Exploit Public-Facing Application), T1059.004 (Command and Scripting Interpreter: Unix Shell)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the source code (nbshenxm/pentest-agent at 97ac5be7). The execution agent is told to prove code execution with
// command_to_execute, default "touch /tmp/success" (configs/config.yaml:129), so the command lands in whatever exploit
// request the model builds. The agent adds no user agent or marker of its own; before the exploit the same source
// usually runs nmap with http-enum, http-title, http-server-header and http-headers (Nmap Scripting Engine user agent).
// Vulhub uses the same proof command in its examples, so a match is an attempt to prove code execution, by this agent
// or by someone following Vulhub. Not the GH05TCREW/pentestagent tool, which has its own folder.

let Marker = @"touch(\s|\+|%20|\$\{IFS\})+(/|%2[fF])tmp(/|%2[fF])success";
union isfuzzy=true
    (W3CIISLog | extend UA=replace_string(csUserAgent, "+", " ")
        | where csUriQuery matches regex Marker or csUriStem matches regex Marker
        | project TimeGenerated, Source="W3CIISLog", Src=cIP, Target=csHost, Detail=strcat(csUriStem, "?", csUriQuery), UA),
    (CommonSecurityLog | where RequestURL matches regex Marker
        | project TimeGenerated, Source="CommonSecurityLog", Src=SourceIP, Target=DestinationHostName, Detail=RequestURL, UA=RequestClientApplication),
    (AzureDiagnostics | where Category in ("ApplicationGatewayFirewallLog", "FrontDoorWebApplicationFirewallLog")
        | where requestUri_s matches regex Marker or details_data_s matches regex Marker
        | project TimeGenerated, Source="WAF", Src=clientIp_s, Target=hostname_s, Detail=strcat(requestUri_s, " ", details_data_s), UA="")
| where TimeGenerated > ago(90d)
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Samples=make_set(Detail, 10),
    UAs=make_set(UA, 5) by Source, Src, Target
| order by FirstSeen asc

// PentestGPT running on a host you monitor
// Agentic attack detections by ThreatDefence (PentestGPT). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1059.006 (Command and Scripting Interpreter: Python), T1059.004 (Command and Scripting Interpreter: Unix Shell)
// Example hunt for Defender XDR advanced hunting. Test before alerting.
// From the PentestGPT source code (GreyDGL/PentestGPT at e8b1bb77, main, and 83ae3647, v1.0.0):
//  - Main: pentestgpt-agent --goal <text> --target <target> [--backend claude|codex]. It starts the Claude Code CLI
//    with --permission-mode bypassPermissions and --append-system-prompt "You are the Supervisor for an authorized
//    penetration test. ..." or "You are the Executor for an authorized penetration test. ...". Codex gets the same
//    instructions over its app-server protocol, so they are not on its command line.
//  - Main writes runs/<run>/trial-config.json, state.sqlite3, summary.json and traces/supervisor-r<n>/ and
//    traces/executor-<id>/ (input.json, events.jsonl, output.json); the model sessions work in
//    agent-workspaces/<run>/supervisor and executor.
//  - v1.0.0: pentestgpt --target <target>, Claude Code with --system-prompt "You are PentestGPT, an AI-powered CTF
//    challenge solver ...", files ~/.pentestgpt/user_id, ~/.pentestgpt/sessions/<id>.json, pentestgpt-debug.log, and
//    Langfuse telemetry to us.cloud.langfuse.com unless --no-telemetry or LANGFUSE_ENABLED=false.
//  - Legacy (the paper's interactive version): pentestgpt-legacy, logs/pentestGPT.log, logs/pentestGPT_log_<time>.txt.
// The prompt strings need a code change to remove. File locations follow --runs-root, --workspace-root and --log-dir.

let Window = 30d;
union isfuzzy=true
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine contains "You are the Supervisor for an authorized penetration test."
            or ProcessCommandLine contains "You are the Executor for an authorized penetration test."
            or ProcessCommandLine contains "You are PentestGPT, an AI-powered CTF challenge solver"
        | project Timestamp, DeviceName, Signal="Model CLI started with a PentestGPT prompt",
            Detail=substring(ProcessCommandLine, 0, 300), Parent=strcat(InitiatingProcessFileName, " ", substring(InitiatingProcessCommandLine, 0, 150))),
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine matches regex @"(^|[/\\\s""'])pentestgpt-agent(-audit)?(\.exe)?[""']?\s(.*\s)?--(goal|target|run-dir|expected-flag|resume|backend)[\s=]"
            or ProcessCommandLine contains "-m pentestgpt_agent.trial" or ProcessCommandLine contains "-m pentestgpt_agent.audit"
            or ProcessCommandLine matches regex @"(^|[/\\\s""'])pentestgpt(\.exe)?[""']?\s(.*\s)?(--target|-t|--non-interactive|--no-telemetry|--list-sessions|--session-id)[\s=]"
            or ProcessCommandLine matches regex @"(^|[/\\\s""'])pentestgpt-(benchmark|legacy|legacy-connection)(\.exe)?([""']|\s|$)"
        | project Timestamp, DeviceName, Signal="PentestGPT command", Detail=substring(ProcessCommandLine, 0, 300),
            Parent=strcat(InitiatingProcessFileName, " ", substring(InitiatingProcessCommandLine, 0, 150))),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FolderPath matches regex @"[/\\]\.pentestgpt[/\\](sessions[/\\]|user_id$)"
            or FileName in~ ("pentestgpt-debug.log", "pentestGPT.log") or FileName startswith "pentestGPT_log_"
            or FolderPath matches regex @"[/\\]traces[/\\](supervisor-r\d+(-a\d+)?|executor-[0-9a-f]{32})[/\\](input|output)\.json$"
            or FileName =~ "trial-config.json"
        | summarize Files=make_set(FolderPath, 10), Timestamp=min(Timestamp) by DeviceName, InitiatingProcessFileName
        | project Timestamp, DeviceName, Signal="PentestGPT run, session or log files", Detail=tostring(Files), Parent=InitiatingProcessFileName),
    (DeviceNetworkEvents
        | where Timestamp > ago(Window)
        | where RemoteUrl has "us.cloud.langfuse.com" and InitiatingProcessCommandLine has "pentestgpt"
        | project Timestamp, DeviceName, Signal="PentestGPT v1.0.0 telemetry", Detail=RemoteUrl, Parent=InitiatingProcessCommandLine)
| order by Timestamp desc

// Indicator sweep with the agentic watchlist
// Agentic attack detections by ThreatDefence (PentestGPT). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1071.001 (Application Layer Protocol: Web Protocols), T1059.006 (Command and Scripting Interpreter: Python)
// Upload feeds/sentinel-watchlist.csv as a Microsoft Sentinel watchlist with the alias AGENTIC_IOCs and the search key
// "value". A match needs investigation. PentestGPT has no addresses or C2 of its own: its rows are the v1.0.0 telemetry
// host (shared with every Langfuse user, so a lead only), file names and paths, and prompt strings.

let IOC = _GetWatchlist('AGENTIC_IOCs') | where framework has "pentestgpt" | project value=tostring(SearchKey), type, confidence, actor, source;
let Domains = toscalar(IOC | where type == "domain" | summarize make_list(value));
let Files = toscalar(IOC | where type == "file_name" | summarize make_list(value));
let Paths = toscalar(IOC | where type == "file_path" | summarize make_list(value));
let Strings = toscalar(IOC | where type == "string" and confidence == "high" | summarize make_list(value));
union isfuzzy=true
    (DeviceNetworkEvents | where Timestamp > ago(30d)
        | where RemoteUrl has_any (Domains)
        | project TimeGenerated=Timestamp, Source="DeviceNetworkEvents", Indicator=RemoteUrl,
            Detail=strcat(DeviceName, " ", InitiatingProcessFileName, " ", substring(InitiatingProcessCommandLine, 0, 150))),
    (DnsEvents | where TimeGenerated > ago(90d)
        | where Name has_any (Domains)
        | project TimeGenerated, Source="DnsEvents", Indicator=Name, Detail=ClientIP),
    (CommonSecurityLog | where TimeGenerated > ago(90d)
        | where DestinationHostName has_any (Domains)
        | project TimeGenerated, Source="CommonSecurityLog", Indicator=DestinationHostName, Detail=strcat(SourceIP, " ", RequestURL)),
    (DeviceFileEvents | where Timestamp > ago(30d)
        | where FileName in~ (Files) or FolderPath has_any (Paths)
        | project TimeGenerated=Timestamp, Source="DeviceFileEvents", Indicator=FileName, Detail=strcat(DeviceName, " ", FolderPath)),
    (DeviceProcessEvents | where Timestamp > ago(30d)
        | where ProcessCommandLine has_any (Strings)
        | project TimeGenerated=Timestamp, Source="DeviceProcessEvents", Indicator="PentestGPT string in command line",
            Detail=strcat(DeviceName, " ", substring(ProcessCommandLine, 0, 200)))
| join kind=leftouter (IOC) on $left.Indicator == $right.value
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Details=make_set(Detail, 10)
    by Source, Indicator, actor, confidence
| order by LastSeen desc

// PentestGPT telemetry and the UnifiedAgent Inspector in network and proxy logs
// Agentic attack detections by ThreatDefence (PentestGPT). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1071.001 (Application Layer Protocol: Web Protocols)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the PentestGPT source code (GreyDGL/PentestGPT at 83ae3647, v1.0.0, and e8b1bb77, main):
//  - PentestGPT does not mark its traffic to targets: no user agent, canary, callback domain or path list. Its target
//    side looks like curl, nmap and whatever else the model runs, which the behaviors/ hunts cover.
//  - v1.0.0 sends Langfuse telemetry by default: POST https://us.cloud.langfuse.com/api/public/otel/v1/traces with the
//    header x_langfuse_public_key: pk-lf-49d66e88-3a92-478e-92a6-09bae920d69a. It carries the target, the agent's
//    messages, each tool call's arguments and each flag found. Many LLM applications use the same Langfuse host, so a
//    host match is a lead; the key, where a TLS-inspecting proxy logs request headers, is not.
//  - The unified-agent dependency can serve a run viewer, "UnifiedAgent Inspector", on 127.0.0.1:8765 with /api/runs,
//    /api/runs/<id>/events and /api/runs/<id>/stream. It refuses non-loopback addresses, so seeing it through a proxy
//    or a load balancer means someone published it on purpose. Run ids from PentestGPT look like
//    trial-<12 hex>--supervisor-r<n> or trial-<12 hex>--executor-<id>.

let Window = 30d;
union isfuzzy=true
    (CommonSecurityLog | where TimeGenerated > ago(Window)
        | where DestinationHostName =~ "us.cloud.langfuse.com" or RequestURL has "us.cloud.langfuse.com/api/public/otel"
        | extend Key=extract(@"pk-lf-[0-9a-f-]{36}", 0, AdditionalExtensions)
        | project TimeGenerated, Source="CommonSecurityLog", Src=SourceIP,
            Signal=iff(Key == "pk-lf-49d66e88-3a92-478e-92a6-09bae920d69a", "PentestGPT v1.0.0 telemetry key", "Langfuse US cloud (lead)"),
            Detail=strcat(RequestURL, " ", Key)),
    (DeviceNetworkEvents | where Timestamp > ago(Window)
        | where RemoteUrl has "us.cloud.langfuse.com"
        | project TimeGenerated=Timestamp, Source="DeviceNetworkEvents", Src=DeviceName,
            Signal=iff(InitiatingProcessCommandLine has "pentestgpt", "PentestGPT v1.0.0 telemetry", "Langfuse US cloud (lead)"),
            Detail=strcat(InitiatingProcessFileName, " ", substring(InitiatingProcessCommandLine, 0, 200))),
    (CommonSecurityLog | where TimeGenerated > ago(Window)
        | where RequestURL matches regex @"/api/runs/trial-[0-9a-f]{12}--(supervisor-r\d+|executor-)"
        | project TimeGenerated, Source="CommonSecurityLog", Src=SourceIP, Signal="UnifiedAgent Inspector showing PentestGPT runs",
            Detail=strcat(DestinationHostName, " ", RequestURL)),
    (W3CIISLog | where TimeGenerated > ago(Window)
        | where csUriStem matches regex @"^/api/runs/trial-[0-9a-f]{12}--(supervisor-r\d+|executor-)"
        | project TimeGenerated, Source="W3CIISLog", Src=cIP, Signal="UnifiedAgent Inspector showing PentestGPT runs",
            Detail=strcat(csHost, " ", csUriStem))
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Details=make_set(Detail, 10) by Source, Src, Signal
| order by Signal asc, LastSeen desc

// Pentest Swarm AI on a host you monitor
// Agentic attack detections by ThreatDefence (Pentest Swarm AI). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1588.002 (Obtain Capabilities: Tool)
// Example hunt for Defender XDR advanced hunting. Test and baseline before alerting.
// Pentest Swarm AI (Armur-Ai/Pentest-Swarm-AI, binary pentestswarm) runs recon, exploit and report agents against a
// target. No report of its use in a real intrusion was found on November 23, 2026, so this hunt looks for the
// software itself, from its source code:
//  - The binary pentestswarm (scan, serve, lab) or the image ghcr.io/armur-ai/pentestswarm.
//  - The consent switches PENTESTSWARM_AUTHORIZED=1 and --authorized, which skip the typed "I AGREE".
//  - ~/.pentestswarm/authorization.json and authorization.log: the log has one JSON line per real target.
//  - The tools it starts: nmap -sV -T4 -Pn --top-ports 1000 -oX -, nuclei -jsonl -silent, ffuf, dalfox, and
//    interactsh-client -json -poll-interval 1 for callbacks.
// What each signal relies on in the source is in ../../source-code-signals.md.

let Window = 30d;
let Tools = dynamic(["nmap", "nuclei", "ffuf", "dalfox", "sqlmap", "httpx", "subfinder", "katana", "naabu", "interactsh-client"]);
let SwarmProcesses = DeviceProcessEvents
    | where Timestamp > ago(Window)
    | where FileName in~ ("pentestswarm", "pentestswarm.exe")
        or ProcessCommandLine has_any ("armur-ai/pentestswarm", "PENTESTSWARM_AUTHORIZED", "pentestswarm-lab-");
let SwarmDevices = SwarmProcesses | distinct DeviceName;
union isfuzzy=true
    (SwarmProcesses
        | summarize Commands=make_set(substring(ProcessCommandLine, 0, 200), 10), Timestamp=min(Timestamp) by DeviceName, AccountName
        | project Timestamp, DeviceName, Signal="Pentest Swarm AI binary or image", Detail=strcat(AccountName, " ", tostring(Commands))),
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where DeviceName in (SwarmDevices)
        | where InitiatingProcessFileName in~ ("pentestswarm", "pentestswarm.exe") and tolower(FileName) in (Tools)
        | summarize Started=make_set(FileName, 20), Commands=make_set(substring(ProcessCommandLine, 0, 200), 10), Timestamp=min(Timestamp) by DeviceName
        | project Timestamp, DeviceName, Signal="Security tools started by Pentest Swarm AI", Detail=strcat(tostring(Started), " ", tostring(Commands))),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FolderPath has "/.pentestswarm/" or FolderPath has @"\.pentestswarm\"
        | summarize Files=make_set(FileName, 10), Timestamp=min(Timestamp) by DeviceName
        | project Timestamp, DeviceName, Signal="Pentest Swarm AI consent file or target log", Detail=tostring(Files))
| order by Timestamp desc

// Pentest Swarm AI testing you: its negative-control probe and verification markers in web and proxy logs
// Agentic attack detections by ThreatDefence (Pentest Swarm AI). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1595.002 (Active Scanning: Vulnerability Scanning), T1190 (Exploit Public-Facing Application)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the Pentest Swarm AI source code (Armur-Ai/Pentest-Swarm-AI, reviewed at 1f7c3902):
//  - API discovery starts with GET /nx-<16 hex> and GET /api/nx-<16 hex> to learn what a missing path looks like.
//  - With verification on it sends https://evil.pentestswarm.invalid/pstest in redirect parameters and the template
//    check 191*193 (expecting 36863).
//  - Toward targets it sends a Chrome 141 user agent on macOS, so there is no user agent to match. Its own user
//    agents (pentestswarm-cli, pentestswarm-npm, pentestswarm-webhook/1.0) go to GitHub, npm and webhooks.
// The negative-control path alone is a weak signal; the Paths column shows what the same source asked for next.

let Control = @"^/(api/)?nx-[0-9a-f]{16}$";
union isfuzzy=true
    (W3CIISLog | extend UA=replace_string(csUserAgent, "+", " ")
        | where csUriStem matches regex Control or csUriQuery contains "evil.pentestswarm.invalid" or csUriQuery contains "191*193" or csUriQuery contains "191%2A193" or UA startswith "pentestswarm-"
        | project TimeGenerated, Source="W3CIISLog", Src=cIP, Target=csHost, Detail=strcat(csUriStem, "?", csUriQuery), UA),
    (CommonSecurityLog | where RequestURL contains "evil.pentestswarm.invalid" or RequestURL contains "191*193" or RequestURL contains "191%2A193" or RequestURL matches regex @"/(api/)?nx-[0-9a-f]{16}$" or RequestClientApplication startswith "pentestswarm-"
        | project TimeGenerated, Source="CommonSecurityLog", Src=SourceIP, Target=DestinationHostName, Detail=RequestURL, UA=RequestClientApplication)
| where TimeGenerated > ago(90d)
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Paths=make_set(Detail, 10),
    UAs=make_set(UA, 5) by Source, Src, Target
| order by FirstSeen asc

// RedAmon on a host you monitor, and the reverse shell tunnel it opens
// Agentic attack detections by ThreatDefence (RedAmon). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1588.002 (Obtain Capabilities: Tool), T1572 (Protocol Tunneling)
// Example hunt for Defender XDR advanced hunting. Test and baseline before alerting.
// RedAmon (samugit83/redamon) is a self-hosted penetration testing platform. No report of its use in a real intrusion
// was found on November 23, 2026, so this hunt looks for the software itself, from its source code:
//  - The Docker Compose stack: containers redamon-webapp, redamon-agent, redamon-kali, redamon-recon-<id>,
//    redamon-docker-broker, the control script redamon.sh, and the sandbox servers under /opt/mcp_servers.
//  - Per-scan tool containers (redamon-httpx-<id>, redamon-nuclei-detection-<id>) and the scratch folder /tmp/redamon.
//  - Reverse shells: a Metasploit handler on port 4444 in the sandbox, reached through ngrok tcp 4444 or
//    chisel client <url> R:4444:localhost:4444, and interactsh-client -server oast.fun for callbacks.
// What each signal relies on in the source is in ../../source-code-signals.md.

let Window = 30d;
let Stack = dynamic(["redamon-kali", "redamon-agent", "redamon-webapp", "redamon-recon-", "redamon-docker-broker", "redamon-httpx-",
    "redamon-nuclei-", "/opt/mcp_servers/run_servers.py", "/opt/mcp_servers/tunnel_manager.py", "redamon.sh "]);
union isfuzzy=true
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine has_any (Stack)
        | summarize Commands=make_set(substring(ProcessCommandLine, 0, 200), 10), Timestamp=min(Timestamp) by DeviceName
        | project Timestamp, DeviceName, Signal="RedAmon stack or sandbox process", Detail=tostring(Commands)),
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine has "ngrok tcp 4444"
            or (ProcessCommandLine has "chisel client" and ProcessCommandLine has "R:4444:localhost:4444")
            or (ProcessCommandLine has "interactsh-client" and ProcessCommandLine has "oast.fun")
        | project Timestamp, DeviceName, Signal="Reverse shell tunnel or callback client the RedAmon sandbox starts", Detail=substring(ProcessCommandLine, 0, 300)),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FolderPath startswith "/tmp/redamon/" or FileName =~ "redamon.sh" or FolderPath has "/.redamon-deploy/"
        | summarize Files=make_set(FileName, 10), Timestamp=min(Timestamp) by DeviceName
        | project Timestamp, DeviceName, Signal="RedAmon files", Detail=tostring(Files))
| order by Timestamp desc

// RedAmon scanning you: its user agents, canaries and ownership lookup in web, proxy and DNS logs
// Agentic attack detections by ThreatDefence (RedAmon). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1595.002 (Active Scanning: Vulnerability Scanning), T1190 (Exploit Public-Facing Application)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the RedAmon source code (samugit83/redamon, reviewed at 73ca9d38):
//  - User agents that name it: RedAmon-AISurfaceRecon/1.0 (on by default, probes model API and MCP paths),
//    "Mozilla/5.0 (compatible; RedAmon/4.7)", RedAmon-JsRecon/1.0 and RedAmon-CachePoison/1.0 (modules off by default).
//  - The XSS canary rEdAm0n1337XsS, which the agent's prompt says to put in every parameter, in User-Agent and in Referer.
//  - The cache buster rdmncb=cb<12 hex> of its cache poisoning tests.
//  - A TXT lookup for _redamon-verify.<domain>, when a project turns on ownership verification.
// These are code defaults. Penetration testers run RedAmon too, so check whether the test was agreed.

let Canaries = @"rEdAm0n1337XsS|rdmncb=cb";
union isfuzzy=true
    (W3CIISLog | extend UA=replace_string(csUserAgent, "+", " ")
        | where UA has "RedAmon" or csUriQuery matches regex Canaries or csReferer contains "rEdAm0n1337XsS"
        | project TimeGenerated, Source="W3CIISLog", Src=cIP, Target=csHost, Detail=strcat(csUriStem, "?", csUriQuery), UA),
    (CommonSecurityLog | where RequestClientApplication has "RedAmon" or RequestURL matches regex Canaries
        | project TimeGenerated, Source="CommonSecurityLog", Src=SourceIP, Target=DestinationHostName, Detail=RequestURL, UA=RequestClientApplication),
    (DnsEvents | where Name startswith "_redamon-verify."
        | project TimeGenerated, Source="DnsEvents", Src=ClientIP, Target=Name, Detail="ownership check lookup", UA="")
| where TimeGenerated > ago(90d)
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Samples=make_set(Detail, 10),
    UAs=make_set(UA, 5) by Source, Src, Target
| order by FirstSeen asc

// sapper-v2 running on a host you monitor
// Agentic attack detections by ThreatDefence (sapper-v2). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1059.004 (Command and Scripting Interpreter: Unix Shell), T1595.002 (Active Scanning: Vulnerability Scanning)
// Example hunt for Defender XDR advanced hunting. Test before alerting.
// From the sapper-v2 source code (N1nEmAn/sapper-v2 at 7b75e6f1). sapper-v2 starts Claude Code (and Codex) sessions in
// tmux, types missions into them and keeps a shared engagement graph on disk:
//  - Every agent window runs "cd <dir> && claude ... --dangerously-skip-permissions 2>&1; echo DRIVE_PANE_EXITED; exec
//    sleep infinity" in tmux session sapper-cmd, sapper-tui or sapper-fleet.
//  - Missions are typed with tmux send-keys, so their text is in the command line ("You are the autonomous field commander
//    of a pentest campaign (TSecBench)", "You are an autonomous pentest operator in a CTF benchmark").
//  - Executor steps run claude -p with --append-system-prompt "You are an autonomous executor in a penetration-testing
//    fact-graph agent system".
//  - The graph lives in .sapper/ (project.json, facts/, intents/); the contest image uses /work/runs and /opt/sapper.
//  - sapper view --serve opens a board on TCP 8765 (loopback by default).
// The names need a code change; the run folder (SAPPER_ROOT) and the board port are settings.

let Window = 30d;
let Prompts = dynamic(["You are an autonomous executor in a penetration-testing fact-graph agent system",
    "You are the autonomous field commander of a pentest campaign (TSecBench)",
    "You are an autonomous pentest operator in a CTF benchmark", "You are a GENERAL (senior operator) on challenge",
    "/opt/sapper/docker/commander/"]);
union isfuzzy=true
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine has "DRIVE_PANE_EXITED"
            or (ProcessCommandLine has "tmux" and ProcessCommandLine matches regex @"\s-[st]\s+['""]?sapper-(cmd|tui|fleet)\b")
            or ProcessCommandLine has_any (Prompts)
            or ProcessCommandLine matches regex @"(^|[/\s])sapper(\.py)?\s(.*\s)?(auto\s(.*\s)?--(minutes|skip-permissions)|bench\s(.*\s)?--(root|minutes)|view\s(.*\s)?--serve)\b"
        | project Timestamp, DeviceName, Signal="sapper-v2 agent window, tmux session, mission or CLI", Detail=substring(ProcessCommandLine, 0, 300),
            Parent=strcat(InitiatingProcessFileName, " ", substring(InitiatingProcessCommandLine, 0, 150))),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FolderPath matches regex @"/\.sapper/(facts|intents|hints)/" or FolderPath has "/opt/sapper/docker/commander/"
            or FolderPath has "/work/runs/pane-env/"
            or (FolderPath has "/.sapper/" and FileName in~ ("project.json", "arena.json", "ai-channel.txt", "ai-peers.json"))
            or FileName =~ "sapper-graph.html"
            or (FolderPath has "/work/runs/" and FileName in~ ("commander-state.md", "rotated.env"))
        | summarize Files=make_set(FileName, 10), Timestamp=min(Timestamp) by DeviceName, Folder=tostring(split(FolderPath, ".sapper")[0])
        | project Timestamp, DeviceName, Signal="sapper-v2 graph or run files", Detail=strcat(Folder, " ", tostring(Files)), Parent=""),
    (DeviceNetworkEvents
        | where Timestamp > ago(Window)
        | where ActionType == "ListeningConnectionCreated"
        | where InitiatingProcessCommandLine matches regex @"(^|[/\s])sapper(\.py)?\s(.*\s)?view\s(.*\s)?--serve"
        | project Timestamp, DeviceName, Signal="sapper-v2 board listening", Detail=strcat(LocalIP, ":", LocalPort),
            Parent=InitiatingProcessCommandLine)
| order by Timestamp desc

// Indicator sweep with the agentic watchlist
// Agentic attack detections by ThreatDefence (sapper-v2). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1059.004 (Command and Scripting Interpreter: Unix Shell), T1071.001 (Application Layer Protocol: Web Protocols)
// Upload feeds/sentinel-watchlist.csv as a Microsoft Sentinel watchlist with the alias AGENTIC_IOCs and the search key
// "value". A match needs investigation. sapper-v2 has no operator addresses, domains or user agents of its own: its rows
// are the board title and poll path, file names and paths, tmux session names and prompt strings from the code.

let IOC = _GetWatchlist('AGENTIC_IOCs') | where framework matches regex @"(^|\s)sapper-v2(\s|$)" | project value=tostring(SearchKey), type, confidence, actor, source;
let Strings = toscalar(IOC | where type == "string" and confidence in ("high", "medium") | summarize make_list(value));
let Paths = toscalar(IOC | where type in ("file_path", "file_name") and confidence in ("high", "medium") | summarize make_list(value));
let Uris = toscalar(IOC | where type == "uri_string" and confidence in ("high", "medium") | summarize make_list(value));
union isfuzzy=true
    (DeviceProcessEvents | where Timestamp > ago(30d)
        | where ProcessCommandLine has_any (Strings)
        | mv-apply s=Strings to typeof(string) on (where ProcessCommandLine has s | take 1 | project Indicator=s)
        | project TimeGenerated=Timestamp, Source="DeviceProcessEvents", Indicator, Detail=strcat(DeviceName, " ", substring(ProcessCommandLine, 0, 200))),
    (DeviceFileEvents | where Timestamp > ago(30d)
        | where FolderPath has_any (Paths)
        | mv-apply p=Paths to typeof(string) on (where FolderPath has p | take 1 | project Indicator=p)
        | project TimeGenerated=Timestamp, Source="DeviceFileEvents", Indicator, Detail=strcat(DeviceName, " ", FolderPath)),
    (CommonSecurityLog | where TimeGenerated > ago(90d)
        | where RequestURL has_any (Uris)
        | mv-apply u=Uris to typeof(string) on (where RequestURL has u | take 1 | project Indicator=u)
        | project TimeGenerated, Source="CommonSecurityLog", Indicator, Detail=strcat(SourceIP, " -> ", RequestURL)),
    (W3CIISLog | where TimeGenerated > ago(90d)
        | where csUriStem has_any (Uris)
        | mv-apply u=Uris to typeof(string) on (where csUriStem has u | take 1 | project Indicator=u)
        | project TimeGenerated, Source="W3CIISLog", Indicator, Detail=strcat(cIP, " ", csUriStem))
| join kind=leftouter (IOC) on $left.Indicator == $right.value
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Details=make_set(Detail, 10)
    by Source, Indicator, actor, confidence
| order by LastSeen desc

// sapper-v2 board and contest client in web and proxy logs
// Agentic attack detections by ThreatDefence (sapper-v2). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1071.001 (Application Layer Protocol: Web Protocols)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the sapper-v2 source code (N1nEmAn/sapper-v2 at 7b75e6f1). sapper-v2 sends nothing of its own to a target: its
// agents run stock Kali tools, which the behaviors hunts cover. What it does put on the wire:
//  - Its board (sapper view --serve) polls GET /__sapper_graph__/<24 hex>.json every 2 seconds while open. The board has
//    no login: a hit through your proxy is someone in your network watching an engagement, often on an exposed board.
//  - Its contest client sends the header BENCHMARK_TOKEN to /openapi/v1/challenges (start, submit, close, hint). Any
//    TSecBench contest agent does the same, so treat it as context: an autonomous contest agent runs in your network.
//    Header values are rarely logged; the path is shown for context and needs the BENCHMARK_TOKEN header to mean much.

union isfuzzy=true
    (CommonSecurityLog | where TimeGenerated > ago(90d)
        | where RequestURL has "/__sapper_graph__/" or RequestURL has "/openapi/v1/challenges"
        | project TimeGenerated, Source="CommonSecurityLog", Src=SourceIP, Target=coalesce(DestinationHostName, DestinationIP),
            Signal=iff(RequestURL has "/__sapper_graph__/", "sapper-v2 board poll", "TSecBench API path (context)"), Detail=RequestURL),
    (W3CIISLog | where TimeGenerated > ago(90d)
        | where csUriStem startswith "/__sapper_graph__/"
        | project TimeGenerated, Source="W3CIISLog", Src=cIP, Target=csHost, Signal="sapper-v2 board poll", Detail=csUriStem),
    (DeviceNetworkEvents | where Timestamp > ago(30d)
        | where RemoteUrl has "/__sapper_graph__/"
        | project TimeGenerated=Timestamp, Source="DeviceNetworkEvents", Src=DeviceName, Target=RemoteIP, Signal="sapper-v2 board poll",
            Detail=RemoteUrl)
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Samples=make_set(Detail, 10)
    by Source, Src, Target, Signal
| order by FirstSeen asc

// Shannon running on a host you monitor
// Agentic attack detections by ThreatDefence (Shannon). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1588.002 (Obtain Capabilities: Tool), T1595.002 (Active Scanning: Vulnerability Scanning)
// Example hunt for Defender XDR advanced hunting. Test and baseline before alerting.
// From the Shannon source code (KeygraphHQ/shannon at 3760d2f9). Shannon is a Node.js CLI (npm @keygraph/shannon, or
// ./shannon in a clone) that reads an application's source code and attacks the running application with model-driven
// agents in a Docker worker container. It has no telemetry, so the host is where it shows:
//  - The operator runs npx @keygraph/shannon start -u <url> -r <repo> (or ./shannon start ...).
//  - The CLI starts Temporal (container shannon-temporal, image temporalio/temporal, ports 7233 and 8233 on 127.0.0.1)
//    and one worker per scan: docker run --name shannon-worker-<8 hex> --network shannon-net with the labels
//    shannon.workspace, shannon.task-queue and shannon.workflow-id, image keygraph/shannon:<version> (or shannon-worker),
//    running node apps/worker/dist/temporal/worker.js <url> <repo> --task-queue shannon-<hex> --workflow-id ...
//  - Inside it the agents drive Chromium with playwright-cli -s=agent1 to agent5, and the report is rendered with
//    typst compile ... --input brand=Shannon | AI Pentester by Keygraph.
//  - Files: <workspaces>/<host>_shannon-<ms>/.shannon/ (session.json, workflow.log, agents/*.log, deliverables/),
//    Security-Assessment-Report.pdf and .md at the run root, and ~/.shannon/config.toml in npx mode.
//  - --exp-php2shell runs a PHP crash probe from the CLI alone, without Docker.
// Container processes show on a Linux Docker host with Defender for Endpoint; on macOS and Windows only the CLI and
// docker commands do. What each signal relies on in the source is in ../../source-code-signals.md.

let Window = 30d;
let Markers = dynamic(["@keygraph/shannon", "keygraph/shannon:", "--name shannon-worker-", "shannon.workspace=", "shannon.workflow-id=",
    "TEMPORAL_ADDRESS=shannon-temporal:7233", "brand=Shannon | AI Pentester by Keygraph"]);
union isfuzzy=true
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine has_any (Markers)
            or ProcessCommandLine matches regex @"(^|[/\\\s])shannon[""']?\s+start\s(.*\s)?(-u|--url)[\s=]"
            or (ProcessCommandLine has "temporal/worker.js" and ProcessCommandLine has "--task-queue" and ProcessCommandLine has "--workflow-id")
            or ProcessCommandLine matches regex @"playwright-cli\s+(.*\s)?-s=agent[1-6](\s|$)"
        | extend Signal = iff(ProcessCommandLine has "--exp-php2shell", "Shannon php2shell crash probe", "Shannon CLI, worker container, browser or report renderer")
        | summarize Commands=make_set(substring(ProcessCommandLine, 0, 300), 10), Timestamp=min(Timestamp) by DeviceName, Signal
        | project Timestamp, DeviceName, Signal, Detail=tostring(Commands)),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FolderPath matches regex @"[/\\]\.shannon[/\\]"
        | where FileName in~ ("session.json", "workflow.log", "startup-error.json", "cli.config.json", "stealth.js", "config.toml")
            or FileName matches regex @"^[a-z_]+_(deliverable\.md|exploitation_queue\.json|exploitation_evidence\.md)$"
        | summarize Files=make_set(FileName, 15), Timestamp=min(Timestamp) by DeviceName, Folder=tostring(split(FolderPath, ".shannon")[0])
        | project Timestamp, DeviceName, Signal="Shannon workspace files", Detail=strcat(Folder, ".shannon ", tostring(Files))),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FileName in~ ("Security-Assessment-Report.pdf", "Security-Assessment-Report.md", "php2shell-report.json")
        | where FolderPath matches regex @"_shannon-\d+" or FileName =~ "php2shell-report.json"
        | project Timestamp, DeviceName, Signal="Shannon report", Detail=FolderPath)
| order by Timestamp desc

// Indicator sweep with the agentic watchlist
// Agentic attack detections by ThreatDefence (Shannon). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1595 (Active Scanning), T1588.002 (Obtain Capabilities: Tool)
// Upload feeds/sentinel-watchlist.csv as a Microsoft Sentinel watchlist with the alias AGENTIC_IOCs and the search key
// "value". Shannon has no infrastructure of its own: its rows are user agents, docker images, file names, strings and
// the console port, so a match needs the context in the row. Low-confidence user agents are left out here.

let IOC = _GetWatchlist('AGENTIC_IOCs') | where framework has "shannon" | project value=tostring(SearchKey), type, confidence, actor, source;
let UAs = toscalar(IOC | where type == "user_agent" and confidence in ("high", "medium") | summarize make_list(value));
let Images = toscalar(IOC | where type == "docker_image" | summarize make_list(value));
let Strings = toscalar(IOC | where type == "string" and confidence in ("high", "medium") | summarize make_list(value));
let Files = toscalar(IOC | where type == "file_name" and confidence in ("high", "medium") | summarize make_list(value));
union isfuzzy=true
    (CommonSecurityLog | where TimeGenerated > ago(90d)
        | where RequestClientApplication has_any (UAs) or RequestURL has_any (Strings)
        | project TimeGenerated, Source="CommonSecurityLog", Indicator=coalesce(RequestClientApplication, RequestURL), Detail=strcat(SourceIP, " ", RequestURL)),
    (W3CIISLog | where TimeGenerated > ago(90d)
        | where replace_string(csUserAgent, "+", " ") has_any (UAs)
        | project TimeGenerated, Source="W3CIISLog", Indicator=replace_string(csUserAgent, "+", " "), Detail=strcat(cIP, " ", csUriStem)),
    (DeviceProcessEvents | where Timestamp > ago(30d)
        | where ProcessCommandLine has_any (Images) or ProcessCommandLine has_any (Strings)
        | project TimeGenerated=Timestamp, Source="DeviceProcessEvents", Indicator=substring(ProcessCommandLine, 0, 200), Detail=DeviceName),
    (DeviceFileEvents | where Timestamp > ago(30d)
        | where FileName in~ (Files)
        | project TimeGenerated=Timestamp, Source="DeviceFileEvents", Indicator=FileName, Detail=strcat(DeviceName, " ", FolderPath))
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Details=make_set(Detail, 10) by Source, Indicator
| order by LastSeen desc

// Shannon testing you: the php2shell probe sizes and its browser user agent in web and proxy logs
// Agentic attack detections by ThreatDefence (Shannon). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1499.004 (Endpoint Denial of Service: Application or System Exploitation), T1595.002 (Active Scanning: Vulnerability Scanning)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the Shannon source code (KeygraphHQ/shannon at 3760d2f9):
//  - shannon start --exp-php2shell -u <url> sends three POSTs to the same URL: a 181-byte multipart control, a
//    1,029,023-byte probe and, unless that one already crashed the worker, a 7,449,023-byte probe. Both probes are one
//    multipart part with 80,000 or 540,000 headers X-h0: a, X-h1: a, ... and the boundary ----shannonPhp2shellProbe<32 hex>.
//    The body sizes are exact; logged byte counts add the request line and headers (a few hundred bytes).
//  - Its agents browse with a fixed user agent, Chrome 124 on Linux. Real Chrome 124 sends the same string, so it only
//    counts next to other signs of testing from the same address.
// A probe pair against a PHP site means someone checked it for the php2shell crash; the Suricata rules see the boundary.

let Window = 30d;
let ShannonUA = "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36";
union isfuzzy=true
    (W3CIISLog | where TimeGenerated > ago(Window)
        | where csMethod == "POST" and (csBytes between (1029023 .. 1031023) or csBytes between (7449023 .. 7451023))
        | summarize Probes=count(), Sizes=make_set(csBytes, 5), Statuses=make_set(scStatus, 5), Timestamp=min(TimeGenerated) by Src=cIP, Target=csHost, Path=csUriStem
        | project Timestamp, Source="W3CIISLog", Src, Target, Signal="php2shell probe sizes", Detail=strcat(Path, " sizes ", tostring(Sizes), " status ", tostring(Statuses))),
    (CommonSecurityLog | where TimeGenerated > ago(Window)
        | where RequestMethod == "POST" and (ReceivedBytes between (1029023 .. 1031023) or ReceivedBytes between (7449023 .. 7451023))
        | summarize Probes=count(), Sizes=make_set(ReceivedBytes, 5), Timestamp=min(TimeGenerated) by Src=SourceIP, Target=DestinationHostName, Path=RequestURL
        | project Timestamp, Source="CommonSecurityLog", Src, Target, Signal="php2shell probe sizes", Detail=strcat(Path, " sizes ", tostring(Sizes))),
    (W3CIISLog | where TimeGenerated > ago(Window)
        | where replace_string(csUserAgent, "+", " ") == ShannonUA
        | summarize Requests=count(), Paths=dcount(csUriStem), Samples=make_set(csUriStem, 10), Timestamp=min(TimeGenerated) by Src=cIP, Target=csHost
        | project Timestamp, Source="W3CIISLog", Src, Target, Signal="Shannon browser user agent (context)", Detail=strcat(Requests, " requests, ", Paths, " paths ", tostring(Samples))),
    (CommonSecurityLog | where TimeGenerated > ago(Window)
        | where RequestClientApplication == ShannonUA
        | summarize Requests=count(), Samples=make_set(RequestURL, 10), Timestamp=min(TimeGenerated) by Src=SourceIP, Target=DestinationHostName
        | project Timestamp, Source="CommonSecurityLog", Src, Target, Signal="Shannon browser user agent (context)", Detail=strcat(Requests, " requests ", tostring(Samples)))
| order by Timestamp desc

// Strix running on a host you monitor
// Agentic attack detections by ThreatDefence (Strix). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1588.002 (Obtain Capabilities: Tool)
// Example hunt for Defender XDR advanced hunting. Test before alerting.
// From the Strix source code (usestrix/strix at a1ccf777). Strix is a Python CLI, pip package strix-agent, that runs its
// agents' commands in a Docker sandbox:
//  - The operator runs: strix --target <url> [--scan-mode quick|standard|deep] [--non-interactive] (deep is the default;
//    Gambit saw 146 deep-mode runs against 138 hosts in the retail card-theft campaign).
//  - It pulls ghcr.io/usestrix/strix-sandbox (Kali with nmap, nuclei, sqlmap, ffuf, katana, httpx, interactsh-client)
//    and labels the container strix-run-id. Inside, caido-cli --listen 0.0.0.0:48080 --allow-guests proxies every tool.
//  - Results land in ./strix_runs/<run>/: run.json, agents.json, vulnerabilities.json, vulnerabilities.csv, coverage.json,
//    findings.sarif and penetration_test_report.md.
//  - Telemetry is on by default: strix.gateway.scarf.sh and us.i.posthog.com on every scan.
// The model can be anything LiteLLM reaches; Gambit's operator ran GLM 5.2 and DeepSeek v4 Pro through OpenRouter, which
// behaviors hunt 02 covers. Names and paths need a code change, apart from the image tag and the run folder location.

let Window = 30d;
union isfuzzy=true
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where (ProcessCommandLine matches regex @"(^|[/\\\s])strix(\.exe)?\s" and ProcessCommandLine matches regex @"\s(--target|-t|--target-list|--scan-mode|--resume)[\s=]")
            or ProcessCommandLine matches regex @"((pip|pip3|pipx)\s+install|uv\s+(tool\s+install|tool\s+run|pip\s+install)|uvx)\s(.*\s)?[""']?strix-agent" or ProcessCommandLine contains "usestrix/strix-sandbox"
            or (ProcessCommandLine contains "caido-cli" and ProcessCommandLine contains "--allow-guests")
        | project Timestamp, DeviceName, Signal="Strix command, install or sandbox", Detail=substring(ProcessCommandLine, 0, 300),
            Parent=strcat(InitiatingProcessFileName, " ", substring(InitiatingProcessCommandLine, 0, 150))),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FolderPath matches regex @"[/\\]strix_runs[/\\]"
            and FileName in~ ("run.json", "agents.json", "vulnerabilities.json", "vulnerabilities.csv", "findings.sarif", "penetration_test_report.md")
        | summarize Files=make_set(FileName, 10), Timestamp=min(Timestamp) by DeviceName, Folder=tostring(split(FolderPath, "strix_runs")[1])
        | project Timestamp, DeviceName, Signal="Strix run folder", Detail=strcat("strix_runs", Folder, " ", tostring(Files)), Parent=""),
    (DeviceNetworkEvents
        | where Timestamp > ago(Window)
        | where RemoteUrl has "strix.gateway.scarf.sh"
        | project Timestamp, DeviceName, Signal="Strix telemetry", Detail=RemoteUrl, Parent=InitiatingProcessCommandLine)
| order by Timestamp desc

// Strix telemetry and results viewers seen from your network
// Agentic attack detections by ThreatDefence (Strix). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1071.001 (Application Layer Protocol: Web Protocols)
// Example hunt for Microsoft Sentinel. DNS works everywhere; URL paths need a proxy that records full URLs. Test before alerting.
// From the Strix source code. Every scan reports itself unless the operator sets STRIX_TELEMETRY=false:
//  - POST https://strix.gateway.scarf.sh/scan_started/<version>?..., /finding_reported/<version>?severity=<level>&cwe=...
//    and /scan_ended/<version> (strix/telemetry/scarf.py). A finding_reported call means Strix just found something.
//  - POST https://us.i.posthog.com/capture/ with the project key phc_7rO3XRuNT5sgSKAl6HDIrWdSGh1COzxw0vxVIAR6vVZ.
// The results viewer (strix_runs browser) serves a page titled "Strix Results" with /api/runs, /api/run and
// /api/agents/steer, on 127.0.0.1 and a random port by default; GitGuardian found 13 exposed, on 8080.
// A machine on your network sending Strix telemetry is running Strix: an authorized test, or someone attacking from inside.

let Window = 30d;
union isfuzzy=true
    (DnsEvents
        | where TimeGenerated > ago(Window)
        | where Name has "strix.gateway.scarf.sh"
        | summarize Queries=count(), Timestamp=min(TimeGenerated) by Src=ClientIP
        | project Timestamp, Src, Signal="DNS for Strix telemetry", Detail=strcat("x", Queries)),
    (CommonSecurityLog
        | where TimeGenerated > ago(Window)
        | where DestinationHostName has "strix.gateway.scarf.sh" or RequestURL contains "strix.gateway.scarf.sh"
            or (RequestURL contains "/api/agents/steer" or RequestURL endswith "/api/runs")
        | extend Event = extract(@"scarf\.sh/([a-z_]+)/", 1, RequestURL), Severity = extract(@"severity=([a-z]+)", 1, RequestURL)
        | summarize Requests=count(), Events=make_set(Event, 5), Severities=make_set(Severity, 5), URLs=make_set(RequestURL, 5),
            Timestamp=min(TimeGenerated) by Src=SourceIP
        | project Timestamp, Src, Signal="Strix telemetry or viewer API through the proxy",
            Detail=strcat("events ", tostring(Events), " finding severities ", tostring(Severities), " ", tostring(URLs)))
| order by Timestamp desc

// VulnBot on a host you monitor: the controller and the Kali host it drives
// Agentic attack detections by ThreatDefence (VulnBot). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1059.004 (Command and Scripting Interpreter: Unix Shell), T1021.004 (Remote Services: SSH), T1588.002 (Obtain Capabilities: Tool)
// Example hunt for Defender XDR advanced hunting. Test and baseline before alerting.
// VulnBot (KHenryAegis/VulnBot, reviewed at 9a12effa) is a Python CLI whose three agents (reconnaissance, scanning,
// exploitation) run every command in one SSH shell on a separate Kali host. No report of its use in a real intrusion
// was found on November 26, 2026, so this hunt looks for the software itself, from its source code:
//  - Controller: python cli.py vulnbot -m <n> [-t <s>], cli.py start -a (API on 7861, Streamlit on 8501), cli.py init.
//  - Kali host: right after an SSH password login (default root/root) the shell runs touch ~/.hushlogin,
//    sudo touch /etc/legal, sudo chmod 644 /etc/legal, sudo rm -f /etc/motd, sudo rm -f /etc/update-motd.d/*, then
//    the Kali tools the model chose (nmap, nikto, dirb, sqlmap, hydra, msfconsole and others).
//  - Files: logs/Auto-Pentest.log, basic_config.yaml, model_config.yaml, kb_config.yaml, db_config.yaml in its folder.
// What each signal relies on in the source is in ../../source-code-signals.md.

let Window = 30d;
let SetupCommands = DeviceProcessEvents
    | where Timestamp > ago(Window)
    | where (FileName in~ ("touch", "chmod", "sudo") and ProcessCommandLine has "/etc/legal")
        or (FileName in~ ("rm", "sudo") and ProcessCommandLine has "-f" and ProcessCommandLine has_any ("/etc/motd", "/etc/update-motd.d/"))
        or (FileName =~ "touch" and ProcessCommandLine endswith "/.hushlogin");
union isfuzzy=true
    (SetupCommands
        | summarize Steps=dcount(case(ProcessCommandLine has "/etc/legal", "legal", ProcessCommandLine has "motd", "motd", "hushlogin")),
            Commands=make_set(ProcessCommandLine, 10), First=min(Timestamp) by DeviceName, AccountName, Bucket=bin(Timestamp, 2m)
        | where Steps >= 2
        | project Timestamp=First, DeviceName, Signal="VulnBot SSH shell setup on the host it drives", Detail=strcat(AccountName, " ", tostring(Commands))),
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine has "cli.py" and ProcessCommandLine has_any (" vulnbot", " pentestgpt", " start -a", "VulnBot/cli.py", "VulnBot\\cli.py")
        | summarize Commands=make_set(substring(ProcessCommandLine, 0, 200), 10), Timestamp=min(Timestamp) by DeviceName, AccountName
        | project Timestamp, DeviceName, Signal="VulnBot command line", Detail=strcat(AccountName, " ", tostring(Commands))),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FileName =~ "Auto-Pentest.log" or (FolderPath has "/logs/run_api_server_" or FolderPath has "/logs/run_webui_")
        | summarize Files=make_set(FolderPath, 10), Timestamp=min(Timestamp) by DeviceName
        | project Timestamp, DeviceName, Signal="VulnBot log files", Detail=tostring(Files))
| order by Timestamp desc

// Indicator sweep with the agentic watchlist
// Agentic attack detections by ThreatDefence (VulnBot). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1588.002 (Obtain Capabilities: Tool), T1059.004 (Command and Scripting Interpreter: Unix Shell)
// Upload feeds/sentinel-watchlist.csv as a Microsoft Sentinel watchlist with the alias AGENTIC_IOCs and the search key
// "value". A match needs investigation.
// No VulnBot infrastructure has been published, so these rows are fingerprints of the software: its prompts, its
// command lines, its log file name and the shell setup it runs on the Kali host it drives.

let IOC = _GetWatchlist('AGENTIC_IOCs') | where framework has "vulnbot" | project value=tostring(SearchKey), type, confidence, actor, source;
let Strings = toscalar(IOC | where type == "string" and confidence in ("high", "medium") | summarize make_list(value));
let FileNames = toscalar(IOC | where type == "file_name" | summarize make_list(value));
let Paths = toscalar(IOC | where type == "uri_string" | summarize make_list(value));
union isfuzzy=true
    (DeviceProcessEvents | where Timestamp > ago(30d)
        | where ProcessCommandLine has_any (Strings)
        | extend Indicator=Strings | mv-expand Indicator to typeof(string) | where ProcessCommandLine contains Indicator
        | project TimeGenerated=Timestamp, Source="DeviceProcessEvents", Indicator, Detail=strcat(DeviceName, " ", substring(ProcessCommandLine, 0, 200))),
    (DeviceFileEvents | where Timestamp > ago(30d)
        | where FileName in~ (FileNames)
        | project TimeGenerated=Timestamp, Source="DeviceFileEvents", Indicator=FileName, Detail=strcat(DeviceName, " ", FolderPath)),
    (CommonSecurityLog | where TimeGenerated > ago(90d)
        | where RequestURL has_any (Paths)
        | extend Indicator=Paths | mv-expand Indicator to typeof(string) | where RequestURL contains Indicator
        | project TimeGenerated, Source="CommonSecurityLog", Indicator, Detail=strcat(SourceIP, " -> ", RequestURL)),
    (W3CIISLog | where TimeGenerated > ago(90d)
        | where csUriStem has_any (Paths)
        | extend Indicator=Paths | mv-expand Indicator to typeof(string) | where csUriStem contains Indicator
        | project TimeGenerated, Source="W3CIISLog", Indicator, Detail=strcat(cIP, " ", csUriStem))
| join kind=leftouter (IOC) on $left.Indicator == $right.value
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Details=make_set(Detail, 10)
    by Source, Indicator, actor, confidence
| order by LastSeen desc

// VulnBot in web and proxy logs: its open knowledge base API and the models it downloads
// Agentic attack detections by ThreatDefence (VulnBot). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1071.001 (Application Layer Protocol: Web Protocols), T1588.002 (Obtain Capabilities: Tool)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// VulnBot sends no marker of its own to the targets it tests: its traffic is the Kali tools the model picks. What
// does show in web and proxy logs, from the source code (KHenryAegis/VulnBot, reviewed at 9a12effa):
//  - Its knowledge base API (FastAPI, port 7861, bound to 0.0.0.0, no authentication) under /knowledge_base/:
//    list_knowledge_bases, create_knowledge_base, upload_docs, search_docs, download_doc and others. The Streamlit page
//    on 8501 calls it. Langchain-Chatchat, which this code comes from, has the same paths, so check the host.
//  - Hugging Face downloads of maidalun1020/bce-embedding-base_v1 and maidalun1020/bce-reranker-base_v1, its default
//    embedding and reranking models (other RAG tools use them too: context only).
// Its prompts appear only in model traffic you can read (AI gateway logs, TLS inspection); see the Suricata rules.

let ApiPaths = dynamic(["/knowledge_base/list_knowledge_bases", "/knowledge_base/create_knowledge_base", "/knowledge_base/upload_docs",
    "/knowledge_base/search_docs", "/knowledge_base/download_doc", "/knowledge_base/delete_knowledge_base"]);
let Models = dynamic(["maidalun1020/bce-embedding-base_v1", "maidalun1020/bce-reranker-base_v1"]);
union isfuzzy=true
    (CommonSecurityLog | where TimeGenerated > ago(90d)
        | where RequestURL has_any (ApiPaths) or (DestinationHostName has "huggingface.co" and RequestURL has_any (Models))
        | project TimeGenerated, Source="CommonSecurityLog", Src=SourceIP, Target=coalesce(DestinationHostName, DestinationIP),
            Port=DestinationPort, Detail=RequestURL),
    (W3CIISLog | where TimeGenerated > ago(90d)
        | where csUriStem has_any (ApiPaths)
        | project TimeGenerated, Source="W3CIISLog", Src=cIP, Target=csHost, Port=sPort, Detail=strcat(csMethod, " ", csUriStem, "?", csUriQuery))
| extend Signal=iff(Detail has "maidalun1020", "VulnBot default RAG model download (context only)", "VulnBot knowledge base API path")
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Samples=make_set(Detail, 10), Ports=make_set(Port, 5)
    by Source, Signal, Src, Target
| order by FirstSeen asc

// Xalgorix on a host you monitor
// Agentic attack detections by ThreatDefence (Xalgorix). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1588.002 (Obtain Capabilities: Tool)
// Example hunt for Defender XDR advanced hunting. Test and baseline before alerting.
// Xalgorix (xalgorix/xalgorix) is a Go binary with a web dashboard on port 9137 whose agent runs a penetration test
// without asking for approval. No report of its use in a real intrusion was found on November 23, 2026, so this hunt
// looks for the software itself, from its source code:
//  - The binary (xalgorix --web) or the image xalgord/xalgorix, run privileged with the volume xalgorix-data.
//  - Every command the agent runs is bash -c with a wrapper that starts export XALGORIX_WORKSPACE=... and defines
//    __xalgorix_resolve_path. As root on Linux it also uses xalgorix-scan-init and nsenter.
//  - Its browser: Chromium with --no-sandbox --disable-web-security --allow-running-insecure-content.
//  - Files: ~/.xalgorix.env, /etc/xalgorix.env, ~/.xalgorix/data/<target>/, /etc/systemd/system/xalgorix.service.
// What each signal relies on in the source is in ../../source-code-signals.md.

let Window = 30d;
let Wrapper = dynamic(["XALGORIX_WORKSPACE=", "__xalgorix_resolve_path", "xalgorix-scan-init", "xalgord/xalgorix", "xalgorix --web"]);
let XalgorixProcesses = DeviceProcessEvents
    | where Timestamp > ago(Window)
    | where FileName =~ "xalgorix" or ProcessCommandLine has_any (Wrapper);
let XalgorixDevices = XalgorixProcesses | distinct DeviceName;
union isfuzzy=true
    (XalgorixProcesses
        | summarize Commands=make_set(substring(ProcessCommandLine, 0, 200), 10), Timestamp=min(Timestamp) by DeviceName
        | project Timestamp, DeviceName, Signal="Xalgorix binary, image or agent shell wrapper", Detail=tostring(Commands)),
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where DeviceName in (XalgorixDevices)
        | where ProcessCommandLine has "--disable-web-security" and ProcessCommandLine has "--allow-running-insecure-content"
        | summarize Runs=count(), Timestamp=min(Timestamp) by DeviceName, FileName
        | project Timestamp, DeviceName, Signal="Browser with web security off on a device that runs Xalgorix", Detail=strcat(FileName, " x", Runs)),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FolderPath has "/.xalgorix/data/" or FileName =~ ".xalgorix.env" or FolderPath in~ ("/etc/xalgorix.env", "/etc/systemd/system/xalgorix.service")
        | summarize Files=make_set(FolderPath, 10), Timestamp=min(Timestamp) by DeviceName
        | project Timestamp, DeviceName, Signal="Xalgorix configuration, service or scan data", Detail=tostring(Files))
| order by Timestamp desc

// Xalgorix testing you: its verifier paths, canary and user agents in web and proxy logs
// Agentic attack detections by ThreatDefence (Xalgorix). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1595.002 (Active Scanning: Vulnerability Scanning), T1190 (Exploit Public-Facing Application)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the Xalgorix source code (xalgorix/xalgorix, reviewed at f5b1a99a):
//  - When its verifier confirms a finding it requests <path>-xalgorix-nonexistent-<id> (access control) and
//    <dir>/xalgorix-missing-<id> followed by ../ steps to etc/passwd (path traversal). These strings are in the code.
//  - The reflection canary XALG0R1XTEST is an example in its system prompt, so the model may use another string.
//  - Its own user agents start with xalgorix (xalgorix-origin-calibration/1, xalgorix/<version>).
// A verifier marker means a finding was being confirmed: look at what the same source requested just before it.

let Markers = @"xalgorix-nonexistent-|xalgorix-missing-|XALG0R1XTEST";
union isfuzzy=true
    (W3CIISLog | extend UA=replace_string(csUserAgent, "+", " ")
        | where csUriStem matches regex Markers or csUriQuery matches regex Markers or UA startswith "xalgorix"
        | project TimeGenerated, Source="W3CIISLog", Src=cIP, Target=csHost, Detail=strcat(csUriStem, "?", csUriQuery), UA),
    (CommonSecurityLog | where RequestURL matches regex Markers or RequestClientApplication startswith "xalgorix"
        | project TimeGenerated, Source="CommonSecurityLog", Src=SourceIP, Target=DestinationHostName, Detail=RequestURL, UA=RequestClientApplication)
| where TimeGenerated > ago(90d)
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Samples=make_set(Detail, 10),
    UAs=make_set(UA, 5) by Source, Src, Target
| order by FirstSeen asc
